select ac_cargar_unidad($ac${"slug":"plantas-1","rama":"plantas","orden":1,"nivel":1,"titulo_es":"Cómo vive una planta","bajada_es":"Una planta fabrica su comida con luz, aire y agua. Sus partes, cómo se alimenta, cómo crece y por qué sostiene casi toda la vida.","objetivos_es":["Identificar las partes de una planta y la función de cada una","Explicar la fotosíntesis y la respiración de las plantas","Describir cómo una planta toma y mueve el agua y los nutrientes","Seguir el ciclo de vida de una planta con flor","Reconocer el papel de las plantas en la vida del planeta"],"repasa":["tronco-1"],"requiere_tronco":1,"fuentes":["bar-on-biomasa-2018","fao-suelos","ipbes-global","plantas-nativas","inta"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"plantas-1.s1","orden":1,"tipo":"leccion","titulo_es":"Las partes de una planta","bajada_es":"Raíz, tallo, hojas, flores, frutos y semillas: cada parte tiene un trabajo.","minutos":11,"pasos":[{"slug":"plantas-1.s1.p1","orden":1,"grupo":"plantas-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un cuerpo con divisiones de trabajo","cuerpo":["Una planta con flor tiene partes especializadas. La raíz la sujeta al suelo y absorbe agua y nutrientes. El tallo la sostiene y transporta agua y alimento entre la raíz y las hojas. Las hojas fabrican el alimento con la luz del sol. Las flores sirven para reproducirse; de ellas salen los frutos, que protegen y ayudan a dispersar las semillas.","Cada parte depende de las otras: sin hojas no hay alimento para la raíz, y sin raíz no hay agua para las hojas."]},"solucion":{}},{"slug":"plantas-1.s1.p2","orden":2,"grupo":"plantas-1.s1.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada parte de la planta con su función principal.","izquierda":[{"id":"a1","texto":"Raíz"},{"id":"a2","texto":"Tallo"},{"id":"a3","texto":"Hoja"},{"id":"a4","texto":"Flor"}],"derecha":[{"id":"b1","texto":"Absorber agua y sujetar la planta"},{"id":"b2","texto":"Sostener y transportar"},{"id":"b3","texto":"Fabricar alimento con luz"},{"id":"b4","texto":"Reproducirse"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Una división del trabajo que funciona como un equipo."}},{"slug":"plantas-1.s1.p3","orden":3,"grupo":"plantas-1.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Partes que comemos","cuerpo":["Muchos de nuestros alimentos son partes de plantas. De la papa comemos un tallo subterráneo engrosado (un tubérculo); de la zanahoria, una raíz; de la lechuga, hojas; del brócoli, flores sin abrir; del tomate, un fruto; de los porotos, semillas.","Saber qué parte comemos ayuda a entender cómo se cultiva cada alimento y por qué algunos se conservan más que otros."]},"solucion":{}},{"slug":"plantas-1.s1.p4","orden":4,"grupo":"plantas-1.s1.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué parte de la planta comemos en cada caso?","grupos":[{"id":"g1","nombre":"Raíz"},{"id":"g2","nombre":"Hoja"},{"id":"g3","nombre":"Fruto"},{"id":"g4","nombre":"Semilla"}],"items":[{"id":"i1","texto":"Zanahoria"},{"id":"i2","texto":"Lechuga"},{"id":"i3","texto":"Tomate"},{"id":"i4","texto":"Lentejas"},{"id":"i5","texto":"Batata"},{"id":"i6","texto":"Acelga"},{"id":"i7","texto":"Zapallo"},{"id":"i8","texto":"Maní"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g4","i5":"g1","i6":"g2","i7":"g3","i8":"g4"},"explicacion":"La verdulería es una clase de botánica. Y la papa, aunque crezca bajo tierra, es un tallo, no una raíz."}},{"slug":"plantas-1.s1.p5","orden":5,"grupo":"plantas-1.s1.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La papa es una raíz.","razones":[{"id":"r1","texto":"Porque tiene yemas (\"ojos\") de donde brotan tallos"},{"id":"r2","texto":"Porque crece dentro de la tierra"},{"id":"r3","texto":"Porque no tiene hojas"}]},"solucion":{"valor":false,"explicacion":"Es un tallo subterráneo engrosado, llamado tubérculo. Tiene \"ojos\", que son yemas de donde brotan tallos nuevos, algo que las raíces no tienen.","clave":["r1"]}},{"slug":"plantas-1.s1.p6","orden":6,"grupo":"plantas-1.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las hojas, fábricas planas","cuerpo":["Las hojas suelen ser planas y anchas para captar mucha luz. En su superficie tienen poros microscópicos, los estomas, por donde entra el dióxido de carbono del aire y sale oxígeno y vapor de agua. Las nervaduras son los caños que llevan agua a la hoja y sacan el alimento que fabrica.","En zonas secas, muchas plantas tienen hojas chicas, gruesas o convertidas en espinas, como los cactus, para perder menos agua."]},"solucion":{}},{"slug":"plantas-1.s1.p7","orden":7,"grupo":"plantas-1.s1.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué los cactus tienen espinas en lugar de hojas anchas?","opciones":[{"id":"o1","texto":"Para perder menos agua en climas secos"},{"id":"o2","texto":"Para hacer más fotosíntesis que otras plantas"},{"id":"o3","texto":"Para atraer a los insectos polinizadores"},{"id":"o4","texto":"Porque no necesitan luz para vivir"}]},"solucion":{"clave":["o1"],"explicacion":"Menos superficie, menos evaporación. En los cactus, el tallo verde hace la fotosíntesis.","por_opcion":{"o3":"Las espinas pueden defender, pero su origen tiene que ver con perder menos agua."}}},{"slug":"plantas-1.s1.p8","orden":8,"grupo":"plantas-1.s1.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué pasa a través de los estomas de una hoja? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Entra dióxido de carbono"},{"id":"o2","texto":"Sale oxígeno"},{"id":"o3","texto":"Sale vapor de agua"},{"id":"o4","texto":"Entra tierra del suelo"},{"id":"o5","texto":"Salen las semillas"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Los estomas son las puertas de la hoja al aire. Por ahí entra la materia prima de la fotosíntesis."}},{"slug":"plantas-1.s1.p9","orden":9,"grupo":"plantas-1.s1.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de trabajo en equipo de una planta.","items":[{"id":"i1","texto":"La raíz absorbe agua del suelo"},{"id":"i2","texto":"El tallo la lleva hasta las hojas"},{"id":"i3","texto":"Las hojas fabrican azúcares con luz"},{"id":"i4","texto":"El tallo reparte los azúcares a toda la planta"},{"id":"i5","texto":"La raíz usa parte de ese alimento para crecer"},{"id":"i6","texto":"La raíz fabrica el alimento con la luz del sol"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Agua hacia arriba, alimento hacia todos lados. Un sistema de transporte en dos direcciones."}},{"slug":"plantas-1.s1.p10","orden":10,"grupo":"plantas-1.s1.p10","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada alimento con la parte de la planta que es.","izquierda":[{"id":"a1","texto":"Papa"},{"id":"a2","texto":"Brócoli"},{"id":"a3","texto":"Apio"},{"id":"a4","texto":"Choclo"}],"derecha":[{"id":"b1","texto":"Tallo subterráneo"},{"id":"b2","texto":"Flores sin abrir"},{"id":"b3","texto":"Pecíolo de la hoja"},{"id":"b4","texto":"Semillas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Algunos alimentos engañan. El apio es el \"palito\" que une la hoja al tallo."}},{"slug":"plantas-1.s1.p11","orden":11,"grupo":"plantas-1.s1.p11","tipo":"detectar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación de un chico y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Las raíces absorben agua del suelo."},{"id":"s2","texto":"Las hojas sirven solo para dar sombra."},{"id":"s3","texto":"El tomate es un fruto."},{"id":"s4","texto":"Las flores no sirven para nada, son decoración."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Cada parte tiene una función vital. Ninguna está de adorno.","por_opcion":{"s2":"Las hojas fabrican el alimento de la planta con la fotosíntesis.","s4":"Las flores son el órgano de reproducción de la planta."}}},{"slug":"plantas-1.s1.p12","orden":12,"grupo":"plantas-1.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La {{0}} absorbe agua, las {{1}} fabrican el alimento y las {{2}} sirven para reproducirse.","banco":[{"id":"w1","texto":"raíz"},{"id":"w2","texto":"hojas"},{"id":"w3","texto":"flores"},{"id":"w4","texto":"semillas"},{"id":"w5","texto":"espinas"},{"id":"w6","texto":"nervaduras"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres partes, tres trabajos, en una sola línea."}},{"slug":"plantas-1.s1.p13","orden":13,"grupo":"plantas-1.s1.p13","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas partes de una planta de abajo hacia arriba en un árbol típico.","items":[{"id":"i1","texto":"Raíces"},{"id":"i2","texto":"Tronco"},{"id":"i3","texto":"Ramas"},{"id":"i4","texto":"Hojas y flores"}],"extremos":["Abajo","Arriba"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Una estructura que va del suelo a la luz. Por eso los árboles pueden crecer tan alto: compiten por el sol.","valores":{"i1":"bajo tierra","i2":"desde el suelo","i3":"salen del tronco","i4":"en la copa"}}}]},{"slug":"plantas-1.s2","orden":2,"tipo":"leccion","titulo_es":"Fotosíntesis y respiración","bajada_es":"Cómo una planta convierte luz, aire y agua en alimento, y por qué también respira.","minutos":12,"pasos":[{"slug":"plantas-1.s2.p1","orden":1,"grupo":"plantas-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La receta de la fotosíntesis","cuerpo":["En las hojas, la clorofila —el pigmento verde— captura la luz del sol. Con esa energía, la planta combina el dióxido de carbono del aire con el agua que trae de la raíz y fabrica azúcares. Como resultado, libera oxígeno.","Dicho en una línea: dióxido de carbono + agua + luz → azúcares + oxígeno. Lo que la planta \"come\" es luz y aire."],"destacado":{"valor":"CO₂ + agua + luz","texto":"se convierten en azúcares y oxígeno. Esa es la fotosíntesis."}},"solucion":{}},{"slug":"plantas-1.s2.p2","orden":2,"grupo":"plantas-1.s2.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué necesita una planta para hacer fotosíntesis? Marcá todo.","opciones":[{"id":"o1","texto":"Luz"},{"id":"o2","texto":"Dióxido de carbono"},{"id":"o3","texto":"Agua"},{"id":"o4","texto":"Clorofila"},{"id":"o5","texto":"Oxígeno del suelo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Luz como energía, CO₂ y agua como materias primas, y clorofila para capturar la luz."}},{"slug":"plantas-1.s2.p3","orden":3,"grupo":"plantas-1.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"De dónde sale el peso de un árbol","cuerpo":["Una pregunta famosa: si un árbol pesa toneladas, ¿de dónde salió toda esa materia? No sale de la tierra: si se pesa la tierra de una maceta antes y después de que crezca un árbol, casi no cambia. Sale del aire.","La madera está hecha sobre todo de carbono que la planta tomó del CO₂ del aire, más el agua. Un árbol es, en buena parte, aire convertido en sólido."]},"solucion":{}},{"slug":"plantas-1.s2.p4","orden":4,"grupo":"plantas-1.s2.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿De dónde viene la mayor parte de la materia de un árbol?","opciones":[{"id":"o1","texto":"Del dióxido de carbono del aire, más agua"},{"id":"o2","texto":"De la tierra que absorbe por las raíces"},{"id":"o3","texto":"De los fertilizantes que se le agregan"},{"id":"o4","texto":"De la luz del sol convertida en madera"}]},"solucion":{"clave":["o1"],"explicacion":"La luz aporta la energía, no la materia. La materia viene del CO₂ y del agua.","por_opcion":{"o3":"Los nutrientes del suelo son importantes, pero pesan muy poco comparados con el carbono del aire."}}},{"slug":"plantas-1.s2.p5","orden":5,"grupo":"plantas-1.s2.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un árbol crece \"comiendo\" la tierra de su maceta, por eso la maceta pierde mucho peso.","razones":[{"id":"r1","texto":"Porque su materia viene sobre todo del CO₂ del aire y del agua"},{"id":"r2","texto":"Porque el árbol no tiene raíces"},{"id":"r3","texto":"Porque la tierra de la maceta se evapora"}]},"solucion":{"valor":false,"explicacion":"La tierra casi no pierde peso. La materia del árbol viene sobre todo del CO₂ del aire y del agua. Del suelo toma nutrientes, que pesan poco.","clave":["r1"]}},{"slug":"plantas-1.s2.p6","orden":6,"grupo":"plantas-1.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las plantas también respiran","cuerpo":["Además de hacer fotosíntesis, las plantas respiran todo el tiempo, de día y de noche: usan parte de los azúcares que fabricaron para obtener energía, y en ese proceso toman oxígeno y liberan CO₂, como los animales.","Durante el día, una planta sana hace mucha más fotosíntesis que respiración, así que en total absorbe CO₂ y libera oxígeno. De noche, sin luz, solo respira."]},"solucion":{}},{"slug":"plantas-1.s2.p7","orden":7,"grupo":"plantas-1.s2.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esto ocurre en la fotosíntesis o en la respiración?","grupos":[{"id":"g1","nombre":"Fotosíntesis"},{"id":"g2","nombre":"Respiración"}],"items":[{"id":"i1","texto":"Se usa la luz del sol"},{"id":"i2","texto":"Se usa azúcar para obtener energía"},{"id":"i3","texto":"Se fabrica azúcar"},{"id":"i4","texto":"Se libera CO₂"},{"id":"i5","texto":"Se libera oxígeno"},{"id":"i6","texto":"Ocurre también de noche"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Son procesos opuestos. En el balance de un día, una planta que crece fabrica más de lo que gasta."}},{"slug":"plantas-1.s2.p8","orden":8,"grupo":"plantas-1.s2.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el camino del carbono desde el aire hasta tu cuerpo.","items":[{"id":"i1","texto":"Hay CO₂ en el aire"},{"id":"i2","texto":"Una planta de trigo lo toma por sus estomas"},{"id":"i3","texto":"Lo convierte en almidón en sus granos"},{"id":"i4","texto":"Comés pan hecho con esa harina"},{"id":"i5","texto":"Tu cuerpo usa ese carbono para vivir y exhala CO₂"},{"id":"i6","texto":"El carbono se destruye cuando lo comés"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El carbono da vueltas, como viste en el tronco: del aire a la planta, de la planta a vos, y de vos otra vez al aire."}},{"slug":"plantas-1.s2.p9","orden":9,"grupo":"plantas-1.s2.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Casi toda la vida depende de esto","cuerpo":["La fotosíntesis es la puerta de entrada de la energía del sol a casi todos los seres vivos. Además, produjo durante millones de años el oxígeno de la atmósfera. Hoy, alrededor de la mitad del oxígeno que se produce en el planeta lo generan algas microscópicas del océano, el fitoplancton; la otra mitad, las plantas terrestres."]},"solucion":{}},{"slug":"plantas-1.s2.p10","orden":10,"grupo":"plantas-1.s2.p10","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje del oxígeno que se produce en el planeta viene del fitoplancton del océano.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":50,"banda":"lineal","explicacion":"Alrededor de la mitad. Las selvas son importantes, pero el océano es un pulmón tan grande como ellas."}},{"slug":"plantas-1.s2.p11","orden":11,"grupo":"plantas-1.s2.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"De noche, las plantas liberan CO₂.","razones":[{"id":"r1","texto":"Porque de noche solo respiran, sin fotosíntesis"},{"id":"r2","texto":"Porque de noche hacen más fotosíntesis"},{"id":"r3","texto":"Porque de noche absorben oxígeno para fabricar azúcar"}]},"solucion":{"valor":true,"explicacion":"Sin luz no hay fotosíntesis, pero la respiración sigue. Por eso de noche una planta libera CO₂. En todo el día, si crece, absorbe más de lo que libera.","clave":["r1"]}},{"slug":"plantas-1.s2.p12","orden":12,"grupo":"plantas-1.s2.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La clorofila captura la luz del sol."},{"id":"s2","texto":"Las plantas solo respiran de noche."},{"id":"s3","texto":"La fotosíntesis libera oxígeno."},{"id":"s4","texto":"La madera de un árbol viene de la tierra de la maceta."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Fotosíntesis y respiración conviven. El aire es la materia prima principal.","por_opcion":{"s2":"Respiran todo el tiempo; de día la fotosíntesis supera a la respiración.","s4":"Viene sobre todo del CO₂ del aire y del agua."}}},{"slug":"plantas-1.s2.p13","orden":13,"grupo":"plantas-1.s2.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En la fotosíntesis, la planta usa {{0}}, dióxido de carbono y agua para fabricar {{1}} y liberar {{2}}.","banco":[{"id":"w1","texto":"luz"},{"id":"w2","texto":"azúcares"},{"id":"w3","texto":"oxígeno"},{"id":"w4","texto":"sombra"},{"id":"w5","texto":"proteínas"},{"id":"w6","texto":"nitrógeno"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La receta básica de casi toda la vida en la Tierra."}},{"slug":"plantas-1.s2.p14","orden":14,"grupo":"plantas-1.s2.p14","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos tipos de vida según cuánta biomasa tienen en la Tierra, de más a menos (en carbono).","items":[{"id":"i1","texto":"Plantas"},{"id":"i2","texto":"Bacterias"},{"id":"i3","texto":"Animales"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"Las plantas son, por lejos, la mayor parte de la vida del planeta medida en carbono. Los animales, incluidas las personas, somos una parte mínima.","valores":{"i1":"≈ 80 % de la biomasa","i2":"≈ 13 %","i3":"≈ 0,4 %"}}}]},{"slug":"plantas-1.s3","orden":3,"tipo":"leccion","titulo_es":"Agua y nutrientes","bajada_es":"Cómo sube el agua por un árbol de 30 metros sin bomba, qué comen las raíces y quiénes las ayudan.","minutos":11,"pasos":[{"slug":"plantas-1.s3.p1","orden":1,"grupo":"plantas-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un caño de la raíz a la hoja","cuerpo":["El agua entra por los pelos absorbentes de la raíz y sube por unos conductos del tallo llamados xilema, hasta las hojas. Allí, casi toda se evapora por los estomas. Esa evaporación, la transpiración, \"tira\" del agua hacia arriba como cuando se sorbe con una bombilla.","La mayor parte del agua que absorbe una planta, más del 90 %, se va por transpiración. Solo una parte chica queda en la planta o se usa en la fotosíntesis."],"destacado":{"valor":"> 90 %","texto":"del agua que absorbe una planta se evapora por las hojas: la transpiración."}},"solucion":{}},{"slug":"plantas-1.s3.p2","orden":2,"grupo":"plantas-1.s3.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué hace subir el agua desde la raíz hasta las hojas de un árbol alto?","opciones":[{"id":"o1","texto":"La evaporación en las hojas, que lo tira"},{"id":"o2","texto":"Un corazón que bombea savia dentro del tronco"},{"id":"o3","texto":"La gravedad que empuja el agua hacia arriba"},{"id":"o4","texto":"El viento que sopla sobre el tronco del árbol"}]},"solucion":{"clave":["o1"],"explicacion":"Las plantas no tienen bomba: la transpiración funciona como una bombilla gigante.","por_opcion":{"o3":"La gravedad tira hacia abajo: el agua sube porque las hojas la \"sorben\"."}}},{"slug":"plantas-1.s3.p3","orden":3,"grupo":"plantas-1.s3.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un árbol absorbe 200 litros de agua en un día de verano. Si el 95 % se evapora por las hojas, ¿cuántos litros transpira?","unidad":"litros","decimales":0},"solucion":{"valor":190,"tolerancia":3.8000000000000003,"explicacion":"200 × 95 ÷ 100 = 190 litros. Por eso un árbol refresca el aire a su alrededor: el agua que evapora se lleva calor."}},{"slug":"plantas-1.s3.p3.v2","orden":3,"grupo":"plantas-1.s3.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un árbol absorbe 100 litros de agua en un día de verano. Si el 95 % se evapora por las hojas, ¿cuántos litros transpira?","unidad":"litros","decimales":0},"solucion":{"valor":95,"tolerancia":1.9000000000000001,"explicacion":"100 × 95 ÷ 100 = 95 litros. Por eso un árbol refresca el aire a su alrededor: el agua que evapora se lleva calor."}},{"slug":"plantas-1.s3.p3.v3","orden":3,"grupo":"plantas-1.s3.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un árbol absorbe 400 litros de agua en un día de verano. Si el 95 % se evapora por las hojas, ¿cuántos litros transpira?","unidad":"litros","decimales":0},"solucion":{"valor":380,"tolerancia":7.6000000000000005,"explicacion":"400 × 95 ÷ 100 = 380 litros. Por eso un árbol refresca el aire a su alrededor: el agua que evapora se lleva calor."}},{"slug":"plantas-1.s3.p4","orden":4,"grupo":"plantas-1.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los nutrientes del suelo","cuerpo":["Además de agua, las raíces toman del suelo nutrientes minerales disueltos. Los que la planta necesita en más cantidad son el nitrógeno (para crecer hojas y tallos), el fósforo (para raíces, flores y semillas) y el potasio (para resistir enfermedades y la falta de agua). Por eso muchos fertilizantes dicen \"N-P-K\".","También necesitan en menores cantidades calcio, magnesio, hierro y otros. Una planta con hojas amarillas puede estar mostrando que le falta alguno."]},"solucion":{}},{"slug":"plantas-1.s3.p5","orden":5,"grupo":"plantas-1.s3.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada nutriente con su función principal.","izquierda":[{"id":"a1","texto":"Nitrógeno (N)"},{"id":"a2","texto":"Fósforo (P)"},{"id":"a3","texto":"Potasio (K)"}],"derecha":[{"id":"b1","texto":"Crecimiento de hojas y tallos"},{"id":"b2","texto":"Raíces, flores y semillas"},{"id":"b3","texto":"Resistencia a enfermedades y sequía"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"N-P-K: las tres letras de cualquier bolsa de fertilizante."}},{"slug":"plantas-1.s3.p6","orden":6,"grupo":"plantas-1.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Aliados bajo tierra","cuerpo":["Las raíces no trabajan solas. La mayoría de las plantas terrestres se asocia con hongos llamados micorrizas: los hongos extienden redes finísimas en el suelo que llegan a agua y nutrientes que la raíz sola no alcanzaría, y a cambio reciben azúcares de la planta.","Las legumbres, como porotos, arvejas y soja, se asocian con bacterias que viven en nódulos de sus raíces y toman nitrógeno del aire para convertirlo en nutriente. Por eso enriquecen el suelo."]},"solucion":{}},{"slug":"plantas-1.s3.p7","orden":7,"grupo":"plantas-1.s3.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué hace cada aliado de las raíces?","grupos":[{"id":"g1","nombre":"Hongos micorrícicos"},{"id":"g2","nombre":"Bacterias de las legumbres"}],"items":[{"id":"i1","texto":"Extienden redes que llegan a más agua"},{"id":"i2","texto":"Toman nitrógeno del aire"},{"id":"i3","texto":"Ayudan a tomar fósforo del suelo"},{"id":"i4","texto":"Viven en nódulos de las raíces"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Dos alianzas antiguas. Las dos se basan en un intercambio: la planta paga con azúcares."}},{"slug":"plantas-1.s3.p8","orden":8,"grupo":"plantas-1.s3.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las legumbres pueden aportar nitrógeno al suelo.","razones":[{"id":"r1","texto":"Por las bacterias de sus raíces que toman nitrógeno del aire"},{"id":"r2","texto":"Porque sus hojas absorben nitrógeno de la lluvia"},{"id":"r3","texto":"Porque el nitrógeno sale de sus semillas al germinar"}]},"solucion":{"valor":true,"explicacion":"Gracias a bacterias de sus raíces que toman nitrógeno del aire. Por eso se usan en rotaciones de cultivos y en huertas.","clave":["r1"]}},{"slug":"plantas-1.s3.p9","orden":9,"grupo":"plantas-1.s3.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué una planta se marchita un día de mucho calor.","items":[{"id":"i1","texto":"Hace mucho calor y el aire está seco"},{"id":"i2","texto":"Las hojas transpiran mucha agua"},{"id":"i3","texto":"La raíz no alcanza a absorber tanta del suelo seco"},{"id":"i4","texto":"Las células pierden agua y la planta se ablanda"},{"id":"i5","texto":"El calor le quita la clorofila a las hojas"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Es un problema de balance: sale más agua de la que entra. Regar temprano o a la tarde, y el mulch, ayudan."}},{"slug":"plantas-1.s3.p10","orden":10,"grupo":"plantas-1.s3.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué señales pueden indicar que a una planta le falta agua? Marcá todas.","opciones":[{"id":"o1","texto":"Hojas caídas o blandas"},{"id":"o2","texto":"Bordes de las hojas secos y quebradizos"},{"id":"o3","texto":"Tierra seca varios centímetros abajo"},{"id":"o4","texto":"Tierra encharcada y con olor feo"},{"id":"o5","texto":"Hojas firmes y brillantes"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Ojo: el encharcamiento también puede marchitar, porque las raíces se ahogan sin oxígeno. Por eso hay que tocar la tierra antes de regar."}},{"slug":"plantas-1.s3.p11","orden":11,"grupo":"plantas-1.s3.p11","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una planta tiene la tierra encharcada y las hojas caídas. ¿Qué conviene hacer?","opciones":[{"id":"o1","texto":"Dejar de regar y mejorar el drenaje"},{"id":"o2","texto":"Regarla más porque está marchita"},{"id":"o3","texto":"Ponerla al sol fuerte todo el día para que absorba"},{"id":"o4","texto":"Agregarle mucho fertilizante"}]},"solucion":{"clave":["o1"],"explicacion":"Las raíces también respiran. En tierra encharcada se ahogan y no pueden absorber agua, aunque haya de sobra.","por_opcion":{"o3":"El problema es el exceso de agua: las raíces no tienen oxígeno."}}},{"slug":"plantas-1.s3.p12","orden":12,"grupo":"plantas-1.s3.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos de jardinería y marcá los equivocados.","segmentos":[{"id":"s1","texto":"Tocá la tierra antes de regar."},{"id":"s2","texto":"Si la planta está marchita, regala siempre más."},{"id":"s3","texto":"Las legumbres ayudan a enriquecer el suelo con nitrógeno."},{"id":"s4","texto":"Cuanto más fertilizante, mejor crece la planta."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Observar antes de actuar: la misma señal puede tener causas opuestas.","por_opcion":{"s2":"Puede estar marchita por exceso de agua: primero hay que revisar la tierra.","s4":"El exceso de fertilizante puede quemar raíces y contaminar el agua."}}},{"slug":"plantas-1.s3.p13","orden":13,"grupo":"plantas-1.s3.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El agua sube por el {{0}} gracias a la {{1}} de las hojas; los tres nutrientes principales son nitrógeno, fósforo y {{2}}.","banco":[{"id":"w1","texto":"xilema"},{"id":"w2","texto":"transpiración"},{"id":"w3","texto":"potasio"},{"id":"w4","texto":"floema"},{"id":"w5","texto":"gravedad"},{"id":"w6","texto":"oxígeno"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"El transporte del agua y los nutrientes, resumidos en una línea."}}]},{"slug":"plantas-1.s4","orden":4,"tipo":"leccion","titulo_es":"De la semilla a la semilla","bajada_es":"Germinar, crecer, florecer, ser polinizada, dar frutos y dispersar semillas: el ciclo de vida de una planta con flor.","minutos":12,"pasos":[{"slug":"plantas-1.s4.p1","orden":1,"grupo":"plantas-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una semilla es una planta dormida","cuerpo":["Una semilla tiene adentro un embrión —una plantita en miniatura— y una reserva de alimento, protegidos por una cubierta. Puede esperar meses o años hasta que haya condiciones adecuadas: humedad, temperatura y, en algunas especies, luz.","Cuando germina, primero sale la raíz, que busca agua y sujeta la plántula, y después el tallito con las primeras hojas, que buscan la luz. Hasta que las hojas empiezan a hacer fotosíntesis, la plantita vive de la reserva de la semilla."]},"solucion":{}},{"slug":"plantas-1.s4.p2","orden":2,"grupo":"plantas-1.s4.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de la germinación de un poroto.","items":[{"id":"i1","texto":"La semilla absorbe agua y se hincha"},{"id":"i2","texto":"Se rompe la cubierta"},{"id":"i3","texto":"Sale la raíz hacia abajo"},{"id":"i4","texto":"Sale el tallito hacia arriba"},{"id":"i5","texto":"Aparecen las primeras hojas y empieza la fotosíntesis"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La raíz sale primero: sin agua no hay crecimiento posible."}},{"slug":"plantas-1.s4.p3","orden":3,"grupo":"plantas-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Flores y polinización","cuerpo":["Cuando la planta madura, florece. En la flor, el polen (con las células masculinas) tiene que llegar al pistilo (la parte femenina) de otra flor o de la misma. Eso es la polinización. Después, el óvulo fecundado se convierte en semilla y la base de la flor, en fruto.","El polen viaja con el viento o, muy a menudo, con animales: abejas, mariposas, moscas, escarabajos, picaflores y hasta murciélagos. Los colores, los perfumes y el néctar de las flores son invitaciones para esos polinizadores."]},"solucion":{}},{"slug":"plantas-1.s4.p4","orden":4,"grupo":"plantas-1.s4.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una abeja ayuda a que haya un zapallo.","items":[{"id":"i1","texto":"La abeja visita una flor macho de zapallo y se carga de polen"},{"id":"i2","texto":"Vuela a una flor hembra"},{"id":"i3","texto":"Deja el polen en el pistilo"},{"id":"i4","texto":"La flor es fecundada"},{"id":"i5","texto":"La base de la flor crece y se convierte en zapallo"},{"id":"i6","texto":"La abeja fabrica el zapallo con su miel"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Sin polinización no hay fruto. Por eso los polinizadores son tan importantes para la comida, como vas a ver en esta rama."}},{"slug":"plantas-1.s4.p5","orden":5,"grupo":"plantas-1.s4.p5","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada característica de una flor con el polinizador que suele atraer.","izquierda":[{"id":"a1","texto":"Flores rojas con tubo largo y mucho néctar"},{"id":"a2","texto":"Flores blancas y perfumadas que abren de noche"},{"id":"a3","texto":"Flores chicas, sin pétalos vistosos, con mucho polen suelto"},{"id":"a4","texto":"Flores amarillas o azules con pista de aterrizaje"}],"derecha":[{"id":"b1","texto":"Picaflores"},{"id":"b2","texto":"Polillas"},{"id":"b3","texto":"El viento"},{"id":"b4","texto":"Abejas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Las flores evolucionaron junto a sus polinizadores. Su forma es un \"aviso\" para el visitante correcto."}},{"slug":"plantas-1.s4.p6","orden":6,"grupo":"plantas-1.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Viajar sin moverse","cuerpo":["Las plantas no caminan, pero sus semillas viajan. Algunas vuelan con el viento, como las del panadero (el diente de león) o las de la tipa, que tienen alas. Otras viajan dentro de frutos carnosos que comen los animales y después las dejan en otro lugar con sus excrementos. Otras flotan, se enganchan en el pelo de los animales o son lanzadas cuando el fruto se abre de golpe.","Dispersar las semillas lejos evita que las plantas hijas compitan con la madre por luz y agua, y permite colonizar lugares nuevos."]},"solucion":{}},{"slug":"plantas-1.s4.p7","orden":7,"grupo":"plantas-1.s4.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Cómo viaja cada semilla?","grupos":[{"id":"g1","nombre":"Con el viento"},{"id":"g2","nombre":"Con animales que comen el fruto"},{"id":"g3","nombre":"Enganchada en el pelo o la ropa"}],"items":[{"id":"i1","texto":"Semilla alada de la tipa"},{"id":"i2","texto":"Semillas de la mora"},{"id":"i3","texto":"Abrojo"},{"id":"i4","texto":"Pelusa del panadero"},{"id":"i5","texto":"Semillas del tala"},{"id":"i6","texto":"Cadillo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada forma de semilla es una estrategia de viaje. Mirarla dice mucho de cómo se dispersa."}},{"slug":"plantas-1.s4.p8","orden":8,"grupo":"plantas-1.s4.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las plantas no necesitan a los animales para reproducirse en ningún caso.","razones":[{"id":"r1","texto":"Porque muchas dependen de animales para polinizarse o dispersarse"},{"id":"r2","texto":"Porque todas las plantas se polinizan solas con el viento"},{"id":"r3","texto":"Porque las semillas caminan hasta un lugar nuevo"}]},"solucion":{"valor":false,"explicacion":"Muchísimas plantas dependen de animales para la polinización o para dispersar sus semillas. Algunas usan el viento, pero una gran parte necesita animales.","clave":["r1"]}},{"slug":"plantas-1.s4.p9","orden":9,"grupo":"plantas-1.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ciclos cortos y largos","cuerpo":["Algunas plantas completan su ciclo en un año o menos (anuales), como el maíz o la albahaca. Otras tardan dos años (bienales), como la zanahoria si se la deja florecer. Y otras viven muchos años (perennes), como los árboles, que pueden vivir siglos."]},"solucion":{}},{"slug":"plantas-1.s4.p10","orden":10,"grupo":"plantas-1.s4.p10","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es anual o perenne?","grupos":[{"id":"g1","nombre":"Anual"},{"id":"g2","nombre":"Perenne"}],"items":[{"id":"i1","texto":"Maíz"},{"id":"i2","texto":"Ombú"},{"id":"i3","texto":"Albahaca"},{"id":"i4","texto":"Algarrobo"},{"id":"i5","texto":"Girasol"},{"id":"i6","texto":"Jacarandá"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las anuales apuestan todo a las semillas; las perennes, a durar."}},{"slug":"plantas-1.s4.p11","orden":11,"grupo":"plantas-1.s4.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se siembran 200 semillas y germina el 80 %. ¿Cuántas plantitas nacen?","unidad":"plantitas","decimales":0},"solucion":{"valor":160,"tolerancia":3.2,"explicacion":"200 × 80 ÷ 100 = 160. Nunca germinan todas: por eso se siembra de más y después se ralea."}},{"slug":"plantas-1.s4.p11.v2","orden":11,"grupo":"plantas-1.s4.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se siembran 500 semillas y germina el 60 %. ¿Cuántas plantitas nacen?","unidad":"plantitas","decimales":0},"solucion":{"valor":300,"tolerancia":6,"explicacion":"500 × 60 ÷ 100 = 300. Nunca germinan todas: por eso se siembra de más y después se ralea."}},{"slug":"plantas-1.s4.p11.v3","orden":11,"grupo":"plantas-1.s4.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se siembran 50 semillas y germina el 90 %. ¿Cuántas plantitas nacen?","unidad":"plantitas","decimales":0},"solucion":{"valor":45,"tolerancia":0.9,"explicacion":"50 × 90 ÷ 100 = 45. Nunca germinan todas: por eso se siembra de más y después se ralea."}},{"slug":"plantas-1.s4.p12","orden":12,"grupo":"plantas-1.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La semilla tiene un embrión y reservas de alimento."},{"id":"s2","texto":"Al germinar, primero salen las hojas y después la raíz."},{"id":"s3","texto":"El fruto se forma a partir de la flor."},{"id":"s4","texto":"Las plantas no pueden mover sus semillas a otro lugar."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un ciclo completo: de la semilla a la planta, de la flor al fruto y de nuevo a la semilla.","por_opcion":{"s2":"Primero sale la raíz, para tomar agua y sujetarse.","s4":"Las dispersan con el viento, el agua o los animales."}}},{"slug":"plantas-1.s4.p13","orden":13,"grupo":"plantas-1.s4.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El traslado del polen de una flor a otra se llama {{0}}; después la flor se convierte en {{1}}, que protege las {{2}}.","banco":[{"id":"w1","texto":"polinización"},{"id":"w2","texto":"fruto"},{"id":"w3","texto":"semillas"},{"id":"w4","texto":"germinación"},{"id":"w5","texto":"raíz"},{"id":"w6","texto":"hojas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"El corazón del ciclo de vida de una planta con flor."}},{"slug":"plantas-1.s4.p14","orden":14,"grupo":"plantas-1.s4.p14","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué a muchas plantas les conviene que sus semillas viajen lejos?","opciones":[{"id":"o1","texto":"Para no competir con la madre y llegar a lugares nuevos"},{"id":"o2","texto":"Porque las semillas no pueden germinar cerca del suelo"},{"id":"o3","texto":"Porque la planta madre se come a las semillas cercanas"},{"id":"o4","texto":"Para que los animales no las encuentren nunca"}]},"solucion":{"clave":["o1"],"explicacion":"Dispersarse es una forma de sobrevivir y expandirse sin poder caminar.","por_opcion":{"o3":"Las plantas no comen semillas: el problema es la competencia por luz y agua."}}}]},{"slug":"plantas-1.s5","orden":5,"tipo":"leccion","titulo_es":"Las plantas y nosotros","bajada_es":"Comida, oxígeno, sombra, agua, medicinas y carbono: todo lo que las plantas hacen por las personas.","minutos":12,"pasos":[{"slug":"plantas-1.s5.p1","orden":1,"grupo":"plantas-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La base de todo","cuerpo":["Las plantas son la base de casi todas las cadenas alimentarias: toda la comida que existe viene de plantas directamente o de animales que comieron plantas. Además, producen oxígeno, guardan carbono, forman y protegen el suelo, regulan el agua y el clima, y dan madera, fibras y medicinas.","Medidas en carbono, las plantas son alrededor del 80 % de toda la biomasa de la Tierra. Los animales, incluidas las personas, son una parte muy chica."]},"solucion":{}},{"slug":"plantas-1.s5.p2","orden":2,"grupo":"plantas-1.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hacen las plantas por las personas? Marcá todo lo que corresponde.","opciones":[{"id":"o1","texto":"Producen alimentos"},{"id":"o2","texto":"Liberan oxígeno"},{"id":"o3","texto":"Guardan carbono"},{"id":"o4","texto":"Protegen el suelo de la erosión"},{"id":"o5","texto":"Dan madera, fibras y medicinas"},{"id":"o6","texto":"Fabrican petróleo en pocos años"}]},"solucion":{"clave":["o1","o2","o3","o4","o5"],"explicacion":"Las plantas hacen casi todo lo que necesitamos para vivir. El petróleo viene de restos de seres vivos de hace millones de años, no de plantas actuales."}},{"slug":"plantas-1.s5.p3","orden":3,"grupo":"plantas-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Guardar carbono","cuerpo":["Mientras crece, un árbol va guardando carbono en su tronco, sus ramas y sus raíces. Un árbol adulto puede absorber del orden de decenas de kilos de CO₂ por año, según la especie, el tamaño y el clima. Los bosques y los suelos guardan enormes cantidades de carbono.","Cuando un bosque se quema o se desmonta, ese carbono vuelve al aire como CO₂. Por eso proteger los bosques que ya existen es una de las formas más efectivas de cuidar el clima."]},"solucion":{}},{"slug":"plantas-1.s5.p4","orden":4,"grupo":"plantas-1.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 100 árboles adultos que absorben, en promedio, 20 kg de CO₂ por año cada uno. ¿Cuántas toneladas de CO₂ absorben por año?","unidad":"toneladas de CO₂","decimales":1},"solucion":{"valor":2,"tolerancia":0.05,"explicacion":"100 × 20 = 2.000 kg = 2 t. Ayuda, pero es poco comparado con las emisiones de un barrio: plantar no reemplaza reducir."}},{"slug":"plantas-1.s5.p4.v2","orden":4,"grupo":"plantas-1.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 500 árboles adultos que absorben, en promedio, 25 kg de CO₂ por año cada uno. ¿Cuántas toneladas de CO₂ absorben por año?","unidad":"toneladas de CO₂","decimales":1},"solucion":{"valor":12.5,"tolerancia":0.25,"explicacion":"500 × 25 = 12.500 kg = 12,5 t. Ayuda, pero es poco comparado con las emisiones de un barrio: plantar no reemplaza reducir."}},{"slug":"plantas-1.s5.p4.v3","orden":4,"grupo":"plantas-1.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 1.000 árboles adultos que absorben, en promedio, 15 kg de CO₂ por año cada uno. ¿Cuántas toneladas de CO₂ absorben por año?","unidad":"toneladas de CO₂","decimales":1},"solucion":{"valor":15,"tolerancia":0.3,"explicacion":"1.000 × 15 = 15.000 kg = 15 t. Ayuda, pero es poco comparado con las emisiones de un barrio: plantar no reemplaza reducir."}},{"slug":"plantas-1.s5.p5","orden":5,"grupo":"plantas-1.s5.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Plantar árboles alcanza para compensar todas las emisiones de una ciudad.","razones":[{"id":"r1","texto":"Porque absorben mucho menos de lo que emite una ciudad"},{"id":"r2","texto":"Porque los árboles no absorben CO₂"},{"id":"r3","texto":"Porque los árboles emiten más de lo que absorben"}]},"solucion":{"valor":false,"explicacion":"Los árboles absorben CO₂, pero muchísimo menos de lo que emite una ciudad. Plantar ayuda y tiene muchos otros beneficios, pero no reemplaza reducir emisiones.","clave":["r1"]}},{"slug":"plantas-1.s5.p6","orden":6,"grupo":"plantas-1.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Sombra, agua y suelo","cuerpo":["Un árbol en la vereda da sombra y, con la transpiración, refresca el aire; en verano, la temperatura bajo un árbol puede ser varios grados más baja que al sol. Las raíces sujetan el suelo y ayudan a que la lluvia se infiltre en vez de escurrir. Las hojas que caen alimentan el suelo.","Todo esto se llama servicios ecosistémicos: beneficios que la naturaleza da gratis y que, si se pierden, cuesta muchísimo reemplazar."]},"solucion":{}},{"slug":"plantas-1.s5.p7","orden":7,"grupo":"plantas-1.s5.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada servicio de un árbol con cómo lo hace.","izquierda":[{"id":"a1","texto":"Refrescar el aire"},{"id":"a2","texto":"Evitar inundaciones"},{"id":"a3","texto":"Proteger el suelo"},{"id":"a4","texto":"Cuidar el clima"}],"derecha":[{"id":"b1","texto":"Sombra y transpiración"},{"id":"b2","texto":"Raíces que ayudan a infiltrar la lluvia"},{"id":"b3","texto":"Raíces que lo sujetan"},{"id":"b4","texto":"Guardar carbono en la madera"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Un solo árbol hace muchos trabajos a la vez. En la rama vas a ver cómo se aprovecha en las ciudades."}},{"slug":"plantas-1.s5.p8","orden":8,"grupo":"plantas-1.s5.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué pasa cuando se tala un bosque en una ladera.","items":[{"id":"i1","texto":"Se cortan los árboles de la ladera"},{"id":"i2","texto":"Las raíces dejan de sujetar el suelo"},{"id":"i3","texto":"La lluvia arrastra la tierra"},{"id":"i4","texto":"El suelo se erosiona y los ríos se llenan de sedimento"},{"id":"i5","texto":"La lluvia deja de caer en la ladera"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los efectos viajan, como en el tronco: del bosque al suelo, y del suelo al río."}},{"slug":"plantas-1.s5.p9","orden":9,"grupo":"plantas-1.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Medicinas y materiales","cuerpo":["Muchos medicamentos tienen origen en plantas. La aspirina se desarrolló a partir de una sustancia de la corteza del sauce; la quinina, contra la malaria, viene de la corteza del árbol de la quina. En Argentina, muchas plantas nativas tienen usos tradicionales, como la marcela, la peperina o el cedrón.","También vienen de plantas la madera, el papel, el algodón, el lino, el corcho y muchos otros materiales."]},"solucion":{}},{"slug":"plantas-1.s5.p10","orden":10,"grupo":"plantas-1.s5.p10","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este material o producto viene de plantas o no?","grupos":[{"id":"g1","nombre":"Viene de plantas"},{"id":"g2","nombre":"No viene de plantas"}],"items":[{"id":"i1","texto":"El papel"},{"id":"i2","texto":"El vidrio de un frasco"},{"id":"i3","texto":"El algodón de una remera"},{"id":"i4","texto":"El aluminio de una lata"},{"id":"i5","texto":"El corcho de una botella"},{"id":"i6","texto":"La lana de oveja"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Muchos objetos cotidianos son plantas transformadas. La lana viene de un animal, que comió plantas."}},{"slug":"plantas-1.s5.p11","orden":11,"grupo":"plantas-1.s5.p11","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué proteger un bosque que ya existe suele ser mejor para el clima que plantar uno nuevo?","opciones":[{"id":"o1","texto":"Porque ya guarda mucho carbono y biodiversidad"},{"id":"o2","texto":"Porque los árboles jóvenes no hacen fotosíntesis"},{"id":"o3","texto":"Porque plantar árboles aumenta las emisiones"},{"id":"o4","texto":"Porque los bosques viejos no necesitan agua"}]},"solucion":{"clave":["o1"],"explicacion":"Un bosque maduro tardó siglos en acumular su carbono y su diversidad. Si se pierde, recuperarlo lleva décadas o más.","por_opcion":{"o3":"Plantar bien hecho ayuda; lo que pasa es que un bosque nuevo tarda décadas en igualar al viejo."}}},{"slug":"plantas-1.s5.p12","orden":12,"grupo":"plantas-1.s5.p12","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos grupos por su biomasa en la Tierra, de más a menos (en carbono).","items":[{"id":"i1","texto":"Plantas"},{"id":"i2","texto":"Hongos"},{"id":"i3","texto":"Animales"},{"id":"i4","texto":"Personas"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las personas somos una parte mínima de la vida del planeta, pero con un impacto enorme sobre las otras.","valores":{"i1":"≈ 450 gigatoneladas de carbono","i2":"≈ 12 gigatoneladas","i3":"≈ 2 gigatoneladas","i4":"≈ 0,06 gigatoneladas"}}},{"slug":"plantas-1.s5.p13","orden":13,"grupo":"plantas-1.s5.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Las plantas son la base de casi todas las cadenas alimentarias."},{"id":"s2","texto":"Plantar árboles es suficiente para frenar el cambio climático."},{"id":"s3","texto":"La aspirina se desarrolló a partir de una sustancia del sauce."},{"id":"s4","texto":"Talar un bosque no afecta a los ríos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las plantas hacen muchísimo, y justamente por eso no se las puede cargar con todo.","por_opcion":{"s2":"Ayuda, pero no reemplaza reducir las emisiones.","s4":"Sin bosque, el suelo se erosiona y los ríos reciben sedimentos."}}},{"slug":"plantas-1.s5.p14","orden":14,"grupo":"plantas-1.s5.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los beneficios que la naturaleza da gratis se llaman servicios {{0}}; las plantas son cerca del {{1}} % de la biomasa de la Tierra.","banco":[{"id":"w1","texto":"ecosistémicos"},{"id":"w2","texto":"80"},{"id":"w3","texto":"municipales"},{"id":"w4","texto":"8"},{"id":"w5","texto":"20"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas para dimensionar la importancia de las plantas."}}]},{"slug":"plantas-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: cómo vive una planta","bajada_es":"Partes, fotosíntesis, agua, ciclo de vida y servicios, mezclados.","minutos":8,"pasos":[{"slug":"plantas-1.s6.p1","orden":1,"grupo":"plantas-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Cómo vive una planta». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"plantas-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el potus de Martina","bajada_es":"Martina tiene una planta que no anda bien. Con lo que aprendiste, hacé el diagnóstico. Aprobalo para hacer crecer la rama.","minutos":10,"pasos":[{"slug":"plantas-1.s7.p1","orden":1,"grupo":"plantas-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La planta de Martina","cuerpo":["Martina tiene un potus en una maceta sin agujeros, en un rincón oscuro del living. Lo riega un vaso grande todos los días \"para que no le falte\". Las hojas de abajo están amarillas, la tierra tiene olor feo y hay hongos blancos en la superficie.","Su abuela le dice que le ponga mucho fertilizante para que se recupere."]},"solucion":{}},{"slug":"plantas-1.s7.p2","orden":2,"grupo":"plantas-1.s7.p2","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el problema principal del potus?","opciones":[{"id":"o1","texto":"Exceso de agua: las raíces se ahogan sin oxígeno"},{"id":"o2","texto":"Le falta agua porque la maceta es chica"},{"id":"o3","texto":"Le falta fertilizante"},{"id":"o4","texto":"Hace demasiado frío en el living"}]},"solucion":{"clave":["o1"],"explicacion":"Tierra con olor feo, hongos y hojas amarillas en una maceta sin drenaje: raíces ahogadas.","por_opcion":{"o3":"Con la tierra encharcada, el problema no son los nutrientes: las raíces no pueden funcionar."}}},{"slug":"plantas-1.s7.p3","orden":3,"grupo":"plantas-1.s7.p3","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de lo que le pasa al potus.","items":[{"id":"i1","texto":"La maceta no tiene agujeros y se riega todos los días"},{"id":"i2","texto":"El agua se acumula en el fondo"},{"id":"i3","texto":"Las raíces quedan sin oxígeno"},{"id":"i4","texto":"Las raíces se pudren y no absorben bien"},{"id":"i5","texto":"Las hojas se ponen amarillas"},{"id":"i6","texto":"El agua sube por las hojas y las vuelve amarillas"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Paradójicamente, una planta con raíces ahogadas puede no conseguir el agua que tiene de sobra."}},{"slug":"plantas-1.s7.p4","orden":4,"grupo":"plantas-1.s7.p4","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería hacer Martina? Marcá todo lo que ayuda.","opciones":[{"id":"o1","texto":"Pasarlo a una maceta con agujeros de drenaje"},{"id":"o2","texto":"Regar solo cuando la tierra esté seca unos centímetros abajo"},{"id":"o3","texto":"Moverlo a un lugar con más luz, sin sol directo fuerte"},{"id":"o4","texto":"Cortar las raíces podridas al trasplantar"},{"id":"o5","texto":"Agregarle mucho fertilizante ya"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Drenaje, riego según la tierra y luz. El fertilizante, más adelante y en poca dosis, si hace falta."}},{"slug":"plantas-1.s7.p5","orden":5,"grupo":"plantas-1.s7.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El consejo de la abuela de poner mucho fertilizante ayudaría a que el potus se recupere rápido.","razones":[{"id":"r1","texto":"Porque con raíces dañadas el exceso de fertilizante las quema más"},{"id":"r2","texto":"Porque los potus no usan nutrientes"},{"id":"r3","texto":"Porque el fertilizante tapa los agujeros de la maceta"}]},"solucion":{"valor":false,"explicacion":"Con raíces dañadas, mucho fertilizante puede quemarlas todavía más. Primero hay que resolver el agua y el drenaje.","clave":["r1"]}},{"slug":"plantas-1.s7.p6","orden":6,"grupo":"plantas-1.s7.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Martina regaba un vaso de 250 ml por día. Si pasa a regar solo una vez por semana con la misma cantidad, ¿cuántos ml por semana deja de agregar?","unidad":"ml","decimales":0},"solucion":{"valor":1500,"tolerancia":30,"explicacion":"Antes: 250 × 7 = 1750 ml por semana. Ahora: 250. Deja de agregar 1500 ml. Para una planta de interior con poca luz, eso es mucho más razonable."}},{"slug":"plantas-1.s7.p6.v2","orden":6,"grupo":"plantas-1.s7.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Martina regaba un vaso de 300 ml por día. Si pasa a regar solo una vez por semana con la misma cantidad, ¿cuántos ml por semana deja de agregar?","unidad":"ml","decimales":0},"solucion":{"valor":1800,"tolerancia":36,"explicacion":"Antes: 300 × 7 = 2100 ml por semana. Ahora: 300. Deja de agregar 1800 ml. Para una planta de interior con poca luz, eso es mucho más razonable."}},{"slug":"plantas-1.s7.p6.v3","orden":6,"grupo":"plantas-1.s7.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Martina regaba un vaso de 200 ml por día. Si pasa a regar solo una vez por semana con la misma cantidad, ¿cuántos ml por semana deja de agregar?","unidad":"ml","decimales":0},"solucion":{"valor":1200,"tolerancia":24,"explicacion":"Antes: 200 × 7 = 1400 ml por semana. Ahora: 200. Deja de agregar 1200 ml. Para una planta de interior con poca luz, eso es mucho más razonable."}},{"slug":"plantas-1.s7.p7","orden":7,"grupo":"plantas-1.s7.p7","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Martina escribe su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Trasplantar a una maceta con agujeros y tierra nueva."},{"id":"s2","texto":"Regarlo todos los días un poco, para que se acostumbre."},{"id":"s3","texto":"Ponerlo cerca de una ventana con luz indirecta."},{"id":"s4","texto":"Taparlo con una bolsa para que no pierda agua."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen diagnóstico lleva a un buen plan: drenaje, riego según la tierra y luz.","por_opcion":{"s2":"La clave es regar cuando la tierra está seca, no por calendario.","s4":"Con exceso de humedad, taparlo empeora los hongos."}}},{"slug":"plantas-1.s7.p8","orden":8,"grupo":"plantas-1.s7.p8","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá estas señales según qué problema suelen indicar.","grupos":[{"id":"g1","nombre":"Exceso de agua"},{"id":"g2","nombre":"Falta de agua"}],"items":[{"id":"i1","texto":"Tierra con olor feo"},{"id":"i2","texto":"Tierra seca y separada de la maceta"},{"id":"i3","texto":"Hongos en la superficie"},{"id":"i4","texto":"Hojas crocantes en los bordes"},{"id":"i5","texto":"Tallo blando en la base"},{"id":"i6","texto":"Hojas caídas que se recuperan al regar"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las hojas amarillas o caídas pueden aparecer en los dos casos: la tierra es la que dice cuál es."}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"plantas-2","rama":"plantas","orden":2,"nivel":1,"titulo_es":"Nativas, exóticas e invasoras","bajada_es":"No todas las plantas verdes hacen lo mismo por tu barrio. Qué es una nativa, por qué importa y qué pasa cuando una exótica se escapa.","objetivos_es":["Distinguir plantas nativas, exóticas, naturalizadas e invasoras","Reconocer las principales ecorregiones de Argentina","Explicar la relación entre plantas nativas y fauna local","Describir cómo una especie exótica se vuelve invasora y sus impactos","Elegir plantas adecuadas para un espacio según su ecorregión"],"repasa":["plantas-1","tronco-1"],"requiere_tronco":1,"fuentes":["ecorregiones-pba","plantas-nativas","invasoras-mayds","ipbes-global","sib-apn","reserva-costanera-sur"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"plantas-2.s1","orden":1,"tipo":"leccion","titulo_es":"Qué es una planta nativa","bajada_es":"Nativas, exóticas y naturalizadas: tres palabras para saber de dónde viene lo que crece a tu alrededor.","minutos":11,"pasos":[{"slug":"plantas-2.s1.p1","orden":1,"grupo":"plantas-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Nativa y exótica","cuerpo":["Una planta nativa (o autóctona) es la que crece naturalmente en una región desde antes de que las personas la trasladaran: evolucionó ahí durante miles o millones de años, junto con el clima, el suelo y los animales del lugar.","Una planta exótica es la que llegó de otra región o de otro continente, traída por las personas a propósito (para jardines, cultivos, forestación) o por accidente. Que una planta sea exótica no la hace mala: el trigo, la lechuga o la zanahoria de la huerta son exóticos en Argentina."]},"solucion":{}},{"slug":"plantas-2.s1.p2","orden":2,"grupo":"plantas-2.s1.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es nativa de Argentina o exótica?","grupos":[{"id":"g1","nombre":"Nativa de Argentina"},{"id":"g2","nombre":"Exótica"}],"items":[{"id":"i1","texto":"Ceibo"},{"id":"i2","texto":"Eucalipto"},{"id":"i3","texto":"Algarrobo"},{"id":"i4","texto":"Plátano de las veredas"},{"id":"i5","texto":"Lapacho"},{"id":"i6","texto":"Ligustro"},{"id":"i7","texto":"Tala"},{"id":"i8","texto":"Pino"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1","i8":"g2"},"explicacion":"Muchos árboles comunes de las ciudades argentinas son exóticos. El eucalipto viene de Australia; el plátano, del hemisferio norte."}},{"slug":"plantas-2.s1.p3","orden":3,"grupo":"plantas-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Nativa de dónde","cuerpo":["Ser nativa depende de la escala. El lapacho es nativo de Argentina, pero del noreste y el noroeste, no de la Patagonia. Una planta nativa de las Yungas puede ser exótica en la Pampa.","Por eso, cuando se habla de plantar nativas, lo ideal es elegir las de la propia ecorregión: la zona con clima, suelo y especies parecidas donde uno vive."]},"solucion":{}},{"slug":"plantas-2.s1.p4","orden":4,"grupo":"plantas-2.s1.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una planta es nativa de Argentina, es nativa de cualquier lugar del país.","razones":[{"id":"r1","texto":"Porque cada región tiene sus propias especies según clima y suelo"},{"id":"r2","texto":"Porque todas las plantas argentinas crecen igual en todo el país"},{"id":"r3","texto":"Porque las nativas no dependen del clima"}]},"solucion":{"valor":false,"explicacion":"Argentina tiene regiones muy distintas. Una planta de la selva misionera puede ser exótica en la estepa patagónica. Lo ideal es pensar en la ecorregión.","clave":["r1"]}},{"slug":"plantas-2.s1.p5","orden":5,"grupo":"plantas-2.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Naturalizadas","cuerpo":["Algunas exóticas se \"naturalizan\": se reproducen solas en el lugar nuevo sin ayuda de las personas. Muchas se quedan en lugares alterados, como bordes de caminos, y no causan grandes problemas.","Otras se expanden sin control, desplazan a las nativas y cambian el ecosistema: esas son las invasoras, que vas a ver en esta unidad."]},"solucion":{}},{"slug":"plantas-2.s1.p6","orden":6,"grupo":"plantas-2.s1.p6","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos típicos de una planta exótica que se vuelve invasora.","items":[{"id":"i1","texto":"Llega de otro continente traída por personas"},{"id":"i2","texto":"Se planta en jardines o plazas"},{"id":"i3","texto":"Empieza a reproducirse sola fuera de los jardines"},{"id":"i4","texto":"Se expande y desplaza a las plantas nativas"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"No todas las exóticas recorren todo el camino. Las que llegan al último paso son las invasoras."}},{"slug":"plantas-2.s1.p7","orden":7,"grupo":"plantas-2.s1.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada término con su definición.","izquierda":[{"id":"a1","texto":"Nativa"},{"id":"a2","texto":"Exótica"},{"id":"a3","texto":"Naturalizada"},{"id":"a4","texto":"Invasora"}],"derecha":[{"id":"b1","texto":"Evolucionó en la región sin intervención humana"},{"id":"b2","texto":"Llegó de otra región traída por personas"},{"id":"b3","texto":"Exótica que se reproduce sola"},{"id":"b4","texto":"Exótica que se expande y desplaza a las nativas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro palabras que ordenan cualquier conversación sobre plantas y biodiversidad."}},{"slug":"plantas-2.s1.p8","orden":8,"grupo":"plantas-2.s1.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas afirmaciones sobre las plantas exóticas son correctas? Marcá todas.","opciones":[{"id":"o1","texto":"Muchos cultivos de alimentos son exóticos"},{"id":"o2","texto":"Algunas se vuelven invasoras"},{"id":"o3","texto":"Llegaron traídas por personas, a propósito o por accidente"},{"id":"o4","texto":"Todas las exóticas son dañinas"},{"id":"o5","texto":"Ninguna exótica puede reproducirse sola"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Exótica no es sinónimo de dañina. El problema son las que se vuelven invasoras."}},{"slug":"plantas-2.s1.p9","orden":9,"grupo":"plantas-2.s1.p9","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una vecina dice que el jacarandá es nativo de Buenos Aires porque hay miles en las calles. ¿Qué le responderías?","opciones":[{"id":"o1","texto":"Es nativo, pero del noroeste argentino"},{"id":"o2","texto":"Tiene razón: si hay muchos, es nativo del lugar"},{"id":"o3","texto":"Es de Australia, como el eucalipto"},{"id":"o4","texto":"Es una planta invasora que llegó de Europa"}]},"solucion":{"clave":["o1"],"explicacion":"Que haya muchos no lo hace nativo: se plantaron. Es nativo de Argentina, pero de otra ecorregión.","por_opcion":{"o3":"El jacarandá sí es sudamericano: crece naturalmente en el noroeste argentino y Bolivia."}}},{"slug":"plantas-2.s1.p10","orden":10,"grupo":"plantas-2.s1.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este cartel de una plaza y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El ceibo es la flor nacional argentina."},{"id":"s2","texto":"Todos los árboles de esta plaza son nativos porque crecen bien acá."},{"id":"s3","texto":"El eucalipto vino de Australia."},{"id":"s4","texto":"Las plantas exóticas siempre son invasoras."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Nativa, exótica e invasora son categorías distintas. Confundirlas lleva a malas decisiones.","por_opcion":{"s2":"Crecer bien no significa ser nativo: muchas exóticas se adaptan muy bien.","s4":"Solo algunas exóticas se vuelven invasoras."}}},{"slug":"plantas-2.s1.p11","orden":11,"grupo":"plantas-2.s1.p11","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una planta {{0}} evolucionó en la región; una {{1}} llegó traída por personas; y si se expande y desplaza a las nativas, es {{2}}.","banco":[{"id":"w1","texto":"nativa"},{"id":"w2","texto":"exótica"},{"id":"w3","texto":"invasora"},{"id":"w4","texto":"híbrida"},{"id":"w5","texto":"podada"},{"id":"w6","texto":"anual"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las tres categorías básicas, en una sola línea."}},{"slug":"plantas-2.s1.p12","orden":12,"grupo":"plantas-2.s1.p12","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es nativa de la región pampeana o de otra región del país?","grupos":[{"id":"g1","nombre":"Región pampeana y alrededores"},{"id":"g2","nombre":"Otra región argentina"}],"items":[{"id":"i1","texto":"Tala"},{"id":"i2","texto":"Lenga"},{"id":"i3","texto":"Coronillo"},{"id":"i4","texto":"Lapacho"},{"id":"i5","texto":"Ceibo"},{"id":"i6","texto":"Jacarandá"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Todas son argentinas, pero no todas son de la misma ecorregión. Para un jardín en la Pampa, conviene la primera columna."}},{"slug":"plantas-2.s1.p13","orden":13,"grupo":"plantas-2.s1.p13","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál de estos alimentos es exótico en América del Sur, es decir, se originó en otro continente?","opciones":[{"id":"o1","texto":"El trigo"},{"id":"o2","texto":"El maní"},{"id":"o3","texto":"El zapallo"},{"id":"o4","texto":"La papa"}]},"solucion":{"clave":["o1"],"explicacion":"El trigo llegó de Medio Oriente. El maní, el zapallo y la papa son aportes de América del Sur al mundo.","por_opcion":{"o3":"El zapallo criollo se domesticó en América del Sur, a partir de parientes silvestres que crecen en la región."}}},{"slug":"plantas-2.s1.p14","orden":14,"grupo":"plantas-2.s1.p14","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas especies de plantas vasculares nativas tiene Argentina.","min":100,"max":100000,"paso":1,"unidad":"especies","escala":"log"},"solucion":{"valor":10000,"banda":"log","explicacion":"Alrededor de diez mil, según los catálogos de la flora argentina. Una riqueza enorme que muchas veces no se ve en plazas y jardines."}}]},{"slug":"plantas-2.s2","orden":2,"tipo":"leccion","titulo_es":"Las ecorregiones de Argentina","bajada_es":"De la selva a la estepa, de la Puna al Delta: las grandes regiones naturales del país y sus plantas.","minutos":12,"pasos":[{"slug":"plantas-2.s2.p1","orden":1,"grupo":"plantas-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un país de muchos paisajes","cuerpo":["Una ecorregión es un territorio con un clima, un relieve, un suelo y unas especies características. Argentina tiene 18 ecorregiones, 15 de ellas continentales: entre otras, la Selva Paranaense, las Yungas, el Chaco Seco y el Chaco Húmedo, el Espinal, la Pampa, el Delta e Islas del Paraná, el Monte, la Puna, los Altos Andes, la Estepa Patagónica y los Bosques Patagónicos.","Cada ecorregión tiene su propia flora. Conocer la de tu zona es el primer paso para elegir plantas nativas."],"destacado":{"valor":"18","texto":"ecorregiones tiene Argentina, desde selvas subtropicales hasta el Mar Argentino y la Antártida."}},"solucion":{}},{"slug":"plantas-2.s2.p2","orden":2,"grupo":"plantas-2.s2.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ecorregión con un rasgo característico.","izquierda":[{"id":"a1","texto":"Selva Paranaense"},{"id":"a2","texto":"Yungas"},{"id":"a3","texto":"Pampa"},{"id":"a4","texto":"Estepa Patagónica"}],"derecha":[{"id":"b1","texto":"Selva húmeda con lapachos y palmitos"},{"id":"b2","texto":"Selvas de montaña en el noroeste"},{"id":"b3","texto":"Pastizales en llanuras"},{"id":"b4","texto":"Arbustos bajos y pastos duros con viento"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro de las 18. Cada una con plantas adaptadas a su clima."}},{"slug":"plantas-2.s2.p3","orden":3,"grupo":"plantas-2.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La Pampa, un pastizal","cuerpo":["La Pampa, donde viven millones de personas, era originalmente un pastizal: una llanura de pastos y hierbas, casi sin árboles, con algunos bosques de tala en las barrancas y lomas. Hoy casi toda está transformada en campos de cultivo y ciudades, y los pastizales naturales que quedan son muy pocos.","Por eso, en la región pampeana, \"plantar nativas\" no es solo plantar árboles: también es recuperar pastos y hierbas del pastizal, que alimentan a muchos insectos y aves."]},"solucion":{}},{"slug":"plantas-2.s2.p4","orden":4,"grupo":"plantas-2.s2.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La región pampeana estaba cubierta originalmente por un bosque denso.","razones":[{"id":"r1","texto":"Porque era sobre todo un pastizal con pocos árboles"},{"id":"r2","texto":"Porque los árboles de las rutas son todos nativos"},{"id":"r3","texto":"Porque la Pampa siempre fue un desierto sin plantas"}]},"solucion":{"valor":false,"explicacion":"Era sobre todo un pastizal, con bosques de tala en algunas barrancas y lomas. Muchos árboles que hoy se ven fueron plantados.","clave":["r1"]}},{"slug":"plantas-2.s2.p5","orden":5,"grupo":"plantas-2.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los bosques del norte y del sur","cuerpo":["En el norte están los bosques más extensos del país: el Chaco, con quebrachos y algarrobos, y las selvas de las Yungas y la Paranaense, con una enorme diversidad. En el sur, los Bosques Patagónicos, con lengas, coihues, ñires y el pehuén, la araucaria que da piñones.","Entre ellos, el Espinal forma un arco de bosques bajos de algarrobos, ñandubay, caldén y espinillo alrededor de la Pampa."]},"solucion":{}},{"slug":"plantas-2.s2.p6","orden":6,"grupo":"plantas-2.s2.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿En qué zona es nativo cada árbol?","grupos":[{"id":"g1","nombre":"Norte (Chaco, Yungas o Selva Paranaense)"},{"id":"g2","nombre":"Sur (Bosques Patagónicos)"}],"items":[{"id":"i1","texto":"Quebracho colorado"},{"id":"i2","texto":"Lenga"},{"id":"i3","texto":"Lapacho"},{"id":"i4","texto":"Coihue"},{"id":"i5","texto":"Palo borracho"},{"id":"i6","texto":"Pehuén"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Dos mundos forestales muy distintos: subtropicales en el norte, fríos en el sur."}},{"slug":"plantas-2.s2.p7","orden":7,"grupo":"plantas-2.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Zonas secas","cuerpo":["Una parte grande del país es árida o semiárida: el Monte, la Puna y la Estepa Patagónica. Allí las plantas tienen adaptaciones para ahorrar agua: hojas chicas o resinosas, espinas, raíces muy profundas o muy extendidas. Algunas, como la jarilla, cubren enormes extensiones.","Estas plantas son ideales para jardines de zonas secas: una vez establecidas, casi no necesitan riego."]},"solucion":{}},{"slug":"plantas-2.s2.p8","orden":8,"grupo":"plantas-2.s2.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué adaptaciones tienen muchas plantas de zonas secas? Marcá todas.","opciones":[{"id":"o1","texto":"Hojas chicas"},{"id":"o2","texto":"Espinas en lugar de hojas"},{"id":"o3","texto":"Raíces muy profundas o extendidas"},{"id":"o4","texto":"Hojas cubiertas de resina o pelos"},{"id":"o5","texto":"Hojas enormes y finas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Todas las adaptaciones apuntan a lo mismo: perder menos agua o conseguir más."}},{"slug":"plantas-2.s2.p9","orden":9,"grupo":"plantas-2.s2.p9","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estas ecorregiones de norte a sur.","items":[{"id":"i1","texto":"Selva Paranaense"},{"id":"i2","texto":"Espinal"},{"id":"i3","texto":"Pampa"},{"id":"i4","texto":"Estepa Patagónica"}],"extremos":["Norte","Sur"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un recorrido del trópico húmedo a la estepa fría y ventosa."}},{"slug":"plantas-2.s2.p10","orden":10,"grupo":"plantas-2.s2.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Vivís en Mendoza, en el Monte. ¿Qué plantas conviene elegir para un jardín que ahorre agua?","opciones":[{"id":"o1","texto":"Nativas del Monte, como jarilla o algarrobo"},{"id":"o2","texto":"Césped inglés regado todos los días"},{"id":"o3","texto":"Plantas de la Selva Paranaense, porque son nativas"},{"id":"o4","texto":"Helechos tropicales de sombra"}]},"solucion":{"clave":["o1"],"explicacion":"Nativas de la propia ecorregión: adaptadas al clima, con poca necesidad de riego.","por_opcion":{"o3":"Son nativas de Argentina, pero de una selva húmeda: en Mendoza necesitarían muchísima agua."}}},{"slug":"plantas-2.s2.p11","orden":11,"grupo":"plantas-2.s2.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué la Pampa perdió casi todos sus pastizales.","items":[{"id":"i1","texto":"Sus suelos son muy fértiles"},{"id":"i2","texto":"Se volvieron muy valiosos para la agricultura y la ganadería"},{"id":"i3","texto":"Los pastizales se araron o se reemplazaron"},{"id":"i4","texto":"Hoy quedan muy pocos pastizales naturales"},{"id":"i5","texto":"Los pastizales se secaron solos por falta de lluvia"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La misma fertilidad que hizo rica a la región hizo que su ecosistema original casi desapareciera."}},{"slug":"plantas-2.s2.p12","orden":12,"grupo":"plantas-2.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta descripción y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Argentina tiene 18 ecorregiones."},{"id":"s2","texto":"La Pampa era originalmente una selva."},{"id":"s3","texto":"El pehuén es nativo de los Bosques Patagónicos."},{"id":"s4","texto":"Las plantas del Monte necesitan mucha agua."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Cada ecorregión tiene su lógica. Conocerla evita errores al plantar.","por_opcion":{"s2":"Era un pastizal, con pocos árboles.","s4":"Están adaptadas a la aridez y necesitan muy poca."}}},{"slug":"plantas-2.s2.p13","orden":13,"grupo":"plantas-2.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La Pampa era originalmente un {{0}}; los quebrachos crecen en el {{1}}; y las lengas, en los bosques {{2}}.","banco":[{"id":"w1","texto":"pastizal"},{"id":"w2","texto":"Chaco"},{"id":"w3","texto":"patagónicos"},{"id":"w4","texto":"selva"},{"id":"w5","texto":"Delta"},{"id":"w6","texto":"pampeanos"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ecorregiones del país, con tres paisajes muy distintos."}},{"slug":"plantas-2.s2.p14","orden":14,"grupo":"plantas-2.s2.p14","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una zona había 100 mil hectáreas de pastizal natural y hoy quedan 3 mil. ¿Qué porcentaje del pastizal original queda?","unidad":"%","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"3 ÷ 100 × 100 = 3 %. En muchas zonas de la Pampa, lo que queda de pastizal natural es un porcentaje muy chico."}},{"slug":"plantas-2.s2.p14.v2","orden":14,"grupo":"plantas-2.s2.p14","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una zona había 50 mil hectáreas de pastizal natural y hoy quedan 2 mil. ¿Qué porcentaje del pastizal original queda?","unidad":"%","decimales":1},"solucion":{"valor":4,"tolerancia":0.08,"explicacion":"2 ÷ 50 × 100 = 4 %. En muchas zonas de la Pampa, lo que queda de pastizal natural es un porcentaje muy chico."}},{"slug":"plantas-2.s2.p14.v3","orden":14,"grupo":"plantas-2.s2.p14","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una zona había 200 mil hectáreas de pastizal natural y hoy quedan 5 mil. ¿Qué porcentaje del pastizal original queda?","unidad":"%","decimales":1},"solucion":{"valor":2.5,"tolerancia":0.05,"explicacion":"5 ÷ 200 × 100 = 2,5 %. En muchas zonas de la Pampa, lo que queda de pastizal natural es un porcentaje muy chico."}}]},{"slug":"plantas-2.s3","orden":3,"tipo":"leccion","titulo_es":"Por qué importan las nativas","bajada_es":"Mariposas que solo comen una planta, aves que dependen de frutos del lugar: la red que se arma con las nativas.","minutos":12,"pasos":[{"slug":"plantas-2.s3.p1","orden":1,"grupo":"plantas-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Evolucionar juntos","cuerpo":["Las plantas nativas y los animales del lugar evolucionaron juntos durante miles de años. Muchos insectos solo pueden alimentarse de ciertas plantas: sus orugas no pueden comer otra cosa. Muchas aves se alimentan de frutos e insectos de las plantas nativas.","Cuando se reemplazan las nativas por exóticas, el paisaje sigue verde, pero se rompe esa red: hay menos insectos, menos aves y menos polinizadores."]},"solucion":{}},{"slug":"plantas-2.s3.p2","orden":2,"grupo":"plantas-2.s3.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Mariposas y sus plantas","cuerpo":["La mariposa bandera argentina, celeste y blanca, pone sus huevos en el coronillo, un arbusto nativo: sin coronillo, no hay bandera argentina. La mariposa espejito cría sus orugas en la pasionaria, una enredadera nativa. Muchas otras mariposas dependen de plantas específicas.","A esas plantas se las llama plantas hospederas. Un jardín con flores exóticas puede alimentar a mariposas adultas con néctar, pero sin plantas hospederas nativas no nacen mariposas nuevas."]},"solucion":{}},{"slug":"plantas-2.s3.p3","orden":3,"grupo":"plantas-2.s3.p3","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada mariposa con su planta hospedera.","izquierda":[{"id":"a1","texto":"Bandera argentina"},{"id":"a2","texto":"Espejito"},{"id":"a3","texto":"Monarca"}],"derecha":[{"id":"b1","texto":"Coronillo"},{"id":"b2","texto":"Pasionaria"},{"id":"b3","texto":"Asclepias"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Sin la planta hospedera, la mariposa no puede completar su ciclo. Es una relación de miles de años."}},{"slug":"plantas-2.s3.p4","orden":4,"grupo":"plantas-2.s3.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué pasa si en un barrio desaparecen los coronillos.","items":[{"id":"i1","texto":"Se reemplazan los coronillos por arbustos exóticos"},{"id":"i2","texto":"La bandera argentina no tiene dónde poner huevos"},{"id":"i3","texto":"No nacen orugas nuevas"},{"id":"i4","texto":"La mariposa desaparece del barrio"},{"id":"i5","texto":"La mariposa se adapta a comer plástico"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Una planta menos puede significar una especie menos. Los efectos viajan por la red."}},{"slug":"plantas-2.s3.p5","orden":5,"grupo":"plantas-2.s3.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un jardín lleno de flores exóticas con néctar alcanza para que las mariposas se reproduzcan.","razones":[{"id":"r1","texto":"Porque las orugas necesitan plantas hospederas específicas"},{"id":"r2","texto":"Porque las mariposas no toman néctar"},{"id":"r3","texto":"Porque las mariposas nacen de las flores"}]},"solucion":{"valor":false,"explicacion":"El néctar alimenta a las adultas, pero muchas orugas solo pueden comer ciertas plantas nativas. Sin plantas hospederas, no hay mariposas nuevas.","clave":["r1"]}},{"slug":"plantas-2.s3.p6","orden":6,"grupo":"plantas-2.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Adaptadas al lugar","cuerpo":["Las nativas están adaptadas al clima y al suelo de su ecorregión: soportan sus sequías, sus heladas y sus plagas. Una vez establecidas, suelen necesitar menos riego, menos fertilizante y menos cuidados que muchas exóticas.","Además, forman parte de la identidad de cada región: el ceibo en el Delta, el algarrobo en el Chaco y el Monte, la lenga en la Patagonia."]},"solucion":{}},{"slug":"plantas-2.s3.p7","orden":7,"grupo":"plantas-2.s3.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ventajas tienen las plantas nativas de tu ecorregión? Marcá todas.","opciones":[{"id":"o1","texto":"Alimentan a insectos y aves del lugar"},{"id":"o2","texto":"Están adaptadas al clima y al suelo"},{"id":"o3","texto":"Suelen necesitar menos riego una vez establecidas"},{"id":"o4","texto":"Forman parte de la identidad del paisaje"},{"id":"o5","texto":"Nunca necesitan ningún cuidado, ni al plantarlas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Al principio necesitan riego y cuidado como cualquier planta. Después, mucho menos que muchas exóticas."}},{"slug":"plantas-2.s3.p8","orden":8,"grupo":"plantas-2.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Corredores de vida","cuerpo":["Un jardín o un balcón con nativas es chico, pero muchos juntos forman corredores: caminos de plantas que permiten a insectos y aves moverse por la ciudad entre reservas, plazas y arroyos.","En varias ciudades argentinas hay proyectos de corredores de nativas, donde vecinos, escuelas y municipios suman plantas nativas en veredas, plazas y patios."]},"solucion":{}},{"slug":"plantas-2.s3.p9","orden":9,"grupo":"plantas-2.s3.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es un corredor de nativas en una ciudad?","opciones":[{"id":"o1","texto":"Una serie de espacios con nativas que conecta hábitats"},{"id":"o2","texto":"Una calle exclusiva para plantar árboles exóticos"},{"id":"o3","texto":"Un vivero que vende solo plantas de otros países"},{"id":"o4","texto":"Una pista de atletismo rodeada de césped"}]},"solucion":{"clave":["o1"],"explicacion":"Muchos espacios chicos, conectados, funcionan como un hábitat grande para la fauna.","por_opcion":{"o3":"Los corredores son redes de espacios verdes con nativas, no viveros."}}},{"slug":"plantas-2.s3.p10","orden":10,"grupo":"plantas-2.s3.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta planta alimenta a la fauna nativa o casi no la alimenta?","grupos":[{"id":"g1","nombre":"La alimenta mucho"},{"id":"g2","nombre":"Casi no la alimenta"}],"items":[{"id":"i1","texto":"Tala con frutos para aves"},{"id":"i2","texto":"Césped corto sin flores"},{"id":"i3","texto":"Pasionaria para orugas de mariposa"},{"id":"i4","texto":"Arbusto exótico podado en forma de bola"},{"id":"i5","texto":"Salvia nativa con néctar para picaflores"},{"id":"i6","texto":"Plantas de plástico"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Lo verde no siempre es hábitat. Lo que importa es qué ofrece a la fauna."}},{"slug":"plantas-2.s3.p11","orden":11,"grupo":"plantas-2.s3.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos espacios según cuánto hábitat ofrecen a la fauna nativa, de más a menos.","items":[{"id":"i1","texto":"Jardín con nativas de varios tamaños y flores"},{"id":"i2","texto":"Plaza con árboles nativos y césped"},{"id":"i3","texto":"Plaza con árboles exóticos y césped"},{"id":"i4","texto":"Patio de cemento"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Variedad de nativas y estructura (pastos, arbustos, árboles) es lo que más hábitat crea.","valores":{"i1":"mucho hábitat","i2":"hábitat medio","i3":"poco hábitat","i4":"casi nada"}}},{"slug":"plantas-2.s3.p12","orden":12,"grupo":"plantas-2.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este folleto de un vivero y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"Las nativas están adaptadas al clima de la región."},{"id":"s2","texto":"Las nativas no necesitan agua nunca, ni recién plantadas."},{"id":"s3","texto":"Algunas mariposas dependen de plantas nativas específicas."},{"id":"s4","texto":"Cualquier planta verde sirve igual a la fauna."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las nativas ayudan mucho, pero no son mágicas.","por_opcion":{"s2":"Al principio necesitan riego como cualquier planta; después, menos.","s4":"No: la fauna nativa depende mucho de las plantas nativas."}}},{"slug":"plantas-2.s3.p13","orden":13,"grupo":"plantas-2.s3.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las plantas de las que se alimentan las orugas se llaman plantas {{0}}; la bandera argentina depende del {{1}}.","banco":[{"id":"w1","texto":"hospederas"},{"id":"w2","texto":"coronillo"},{"id":"w3","texto":"exóticas"},{"id":"w4","texto":"eucalipto"},{"id":"w5","texto":"césped"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Una relación que explica por qué las nativas importan."}},{"slug":"plantas-2.s3.p14","orden":14,"grupo":"plantas-2.s3.p14","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un balcón con plantas nativas no sirve para nada porque es muy chico.","razones":[{"id":"r1","texto":"Porque muchos espacios chicos juntos forman corredores"},{"id":"r2","texto":"Porque los insectos no vuelan a los balcones"},{"id":"r3","texto":"Porque las nativas no crecen en macetas"}]},"solucion":{"valor":false,"explicacion":"Muchos espacios chicos juntos forman corredores. Un balcón con nativas puede alimentar a mariposas, abejas nativas y picaflores.","clave":["r1"]}}]},{"slug":"plantas-2.s4","orden":4,"tipo":"leccion","titulo_es":"Exóticas que invaden","bajada_es":"Ligustros, acacias negras, pinos y rosas mosqueta: cómo algunas plantas traídas se vuelven un problema serio.","minutos":12,"pasos":[{"slug":"plantas-2.s4.p1","orden":1,"grupo":"plantas-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es una invasora","cuerpo":["Una especie exótica invasora es una especie traída de otra región que se reproduce sola, se expande y causa daño: desplaza a especies nativas, cambia cómo funciona el ecosistema o provoca pérdidas económicas o problemas de salud.","Según la IPBES, la plataforma científica internacional sobre biodiversidad, las especies invasoras son una de las cinco grandes causas directas de pérdida de biodiversidad en el mundo."]},"solucion":{}},{"slug":"plantas-2.s4.p2","orden":2,"grupo":"plantas-2.s4.p2","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que una exótica sea considerada invasora? Marcá todo lo que corresponde.","opciones":[{"id":"o1","texto":"Se reproduce sola fuera de los jardines"},{"id":"o2","texto":"Se expande en ambientes naturales"},{"id":"o3","texto":"Desplaza a especies nativas"},{"id":"o4","texto":"Causa daños al ecosistema o a la economía"},{"id":"o5","texto":"Tiene flores muy lindas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Que sea linda o útil no importa: lo que la define es que se expande y daña."}},{"slug":"plantas-2.s4.p3","orden":3,"grupo":"plantas-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué algunas ganan","cuerpo":["En su lugar de origen, una planta convive con insectos, hongos y animales que la comen o la enferman, y eso la mantiene a raya. Al llegar a un lugar nuevo, muchas veces esos enemigos no están. Si además produce muchas semillas que dispersan las aves o el viento, y crece rápido, puede ganarle a las nativas."]},"solucion":{}},{"slug":"plantas-2.s4.p4","orden":4,"grupo":"plantas-2.s4.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el ligustro invade un bosque nativo.","items":[{"id":"i1","texto":"Se planta ligustro en cercos y veredas"},{"id":"i2","texto":"Produce muchísimos frutos"},{"id":"i3","texto":"Las aves comen los frutos y dispersan las semillas"},{"id":"i4","texto":"Crecen ligustros dentro del bosque nativo"},{"id":"i5","texto":"Su sombra densa impide crecer a las nativas"},{"id":"i6","texto":"El ligustro se queda siempre en el cerco"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El ligustro invade las sierras de Córdoba, las Yungas y el Delta, entre otras zonas. Empezó siendo un cerco."}},{"slug":"plantas-2.s4.p5","orden":5,"grupo":"plantas-2.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ejemplos argentinos","cuerpo":["El ligustro, un árbol asiático, forma bosques densos que reemplazan a los nativos en las sierras de Córdoba, las Yungas y otras zonas. La acacia negra, de América del Norte, invade pastizales y riberas con sus espinas enormes. En la Patagonia, los pinos plantados se expanden sobre la estepa y aumentan el riesgo de incendios, y la rosa mosqueta y la retama cubren laderas.","También hay animales invasores, como el castor en Tierra del Fuego o el jabalí en muchas regiones, que vas a ver en la rama de Animales."]},"solucion":{}},{"slug":"plantas-2.s4.p6","orden":6,"grupo":"plantas-2.s4.p6","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada invasora con la zona donde es un problema.","izquierda":[{"id":"a1","texto":"Ligustro"},{"id":"a2","texto":"Pinos"},{"id":"a3","texto":"Acacia negra"},{"id":"a4","texto":"Rosa mosqueta"}],"derecha":[{"id":"b1","texto":"Sierras de Córdoba y Yungas"},{"id":"b2","texto":"Estepa patagónica"},{"id":"b3","texto":"Pastizales y riberas de la región pampeana"},{"id":"b4","texto":"Laderas de la Patagonia"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Casi todas llegaron como ornamentales o forestales. Ninguna llegó como \"invasora\"."}},{"slug":"plantas-2.s4.p7","orden":7,"grupo":"plantas-2.s4.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las plantas invasoras llegaron a Argentina por sí solas, sin ayuda de las personas.","razones":[{"id":"r1","texto":"Porque casi todas fueron traídas por personas"},{"id":"r2","texto":"Porque las semillas cruzan el océano volando"},{"id":"r3","texto":"Porque ninguna planta viaja con las personas"}]},"solucion":{"valor":false,"explicacion":"Casi todas fueron traídas por personas: para jardines, forestación, cercos o de forma accidental. Por eso prevenir es tan importante.","clave":["r1"]}},{"slug":"plantas-2.s4.p8","orden":8,"grupo":"plantas-2.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Prevenir es más barato","cuerpo":["Una vez que una invasora se expande, controlarla es carísimo y a veces imposible. Por eso la prevención es la mejor herramienta: no plantar especies con historial invasor, informarse antes de comprar y avisar cuando aparecen en lugares nuevos.","Argentina tiene una lista oficial de especies exóticas invasoras, y algunas provincias prohíben plantar ciertas especies."]},"solucion":{}},{"slug":"plantas-2.s4.p9","orden":9,"grupo":"plantas-2.s4.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las estrategias contra las invasoras de la más barata a la más cara.","items":[{"id":"i1","texto":"Prevenir: no traerla ni plantarla"},{"id":"i2","texto":"Detectar temprano: sacar los primeros ejemplares"},{"id":"i3","texto":"Contener: evitar que siga avanzando"},{"id":"i4","texto":"Restaurar: sacarla de áreas grandes y replantar nativas"}],"extremos":["Más barata","Más cara"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada paso más tarde cuesta mucho más. La prevención es casi gratis."}},{"slug":"plantas-2.s4.p10","orden":10,"grupo":"plantas-2.s4.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción ayuda a prevenir invasiones o las favorece?","grupos":[{"id":"g1","nombre":"Ayuda a prevenir"},{"id":"g2","nombre":"Las favorece"}],"items":[{"id":"i1","texto":"Consultar la lista oficial de invasoras antes de comprar"},{"id":"i2","texto":"Tirar restos de poda de ornamentales en un arroyo"},{"id":"i3","texto":"Elegir nativas para un cerco"},{"id":"i4","texto":"Plantar acacia negra como cerco vivo"},{"id":"i5","texto":"Arrancar plantines de ligustro en una reserva con permiso"},{"id":"i6","texto":"Regalar semillas de plantas invasoras"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Muchas invasiones empiezan en jardines y cercos. Ahí también se previenen."}},{"slug":"plantas-2.s4.p11","orden":11,"grupo":"plantas-2.s4.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué las plantas invasoras muchas veces crecen mejor que en su lugar de origen?","opciones":[{"id":"o1","texto":"Porque no están sus enemigos naturales"},{"id":"o2","texto":"Porque el suelo argentino es siempre más fértil"},{"id":"o3","texto":"Porque las nativas son plantas débiles"},{"id":"o4","texto":"Porque las riegan más que a las nativas"}]},"solucion":{"clave":["o1"],"explicacion":"Sin los insectos y enfermedades que las controlan en su origen, algunas se expanden sin freno.","por_opcion":{"o3":"Las nativas no son débiles: están en equilibrio con sus propios enemigos."}}},{"slug":"plantas-2.s4.p12","orden":12,"grupo":"plantas-2.s4.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una mancha de ligustro ocupa 10 hectáreas y crece un 20 % por año. ¿Cuántas hectáreas ocupará en un año?","unidad":"hectáreas","decimales":1},"solucion":{"valor":12,"tolerancia":0.24,"explicacion":"10 × 1,2 = 12 ha. Y el año siguiente crece sobre esa superficie mayor: por eso actuar temprano es clave."}},{"slug":"plantas-2.s4.p12.v2","orden":12,"grupo":"plantas-2.s4.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una mancha de ligustro ocupa 25 hectáreas y crece un 10 % por año. ¿Cuántas hectáreas ocupará en un año?","unidad":"hectáreas","decimales":1},"solucion":{"valor":27.500000000000004,"tolerancia":0.55,"explicacion":"25 × 1,1 = 27,5 ha. Y el año siguiente crece sobre esa superficie mayor: por eso actuar temprano es clave."}},{"slug":"plantas-2.s4.p12.v3","orden":12,"grupo":"plantas-2.s4.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una mancha de ligustro ocupa 5 hectáreas y crece un 50 % por año. ¿Cuántas hectáreas ocupará en un año?","unidad":"hectáreas","decimales":1},"solucion":{"valor":7.5,"tolerancia":0.15,"explicacion":"5 × 1,5 = 7,5 ha. Y el año siguiente crece sobre esa superficie mayor: por eso actuar temprano es clave."}},{"slug":"plantas-2.s4.p13","orden":13,"grupo":"plantas-2.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El ligustro se dispersa con las aves que comen sus frutos."},{"id":"s2","texto":"Como es lindo y crece rápido, es ideal para cualquier cerco."},{"id":"s3","texto":"Las invasoras son una de las grandes causas de pérdida de biodiversidad."},{"id":"s4","texto":"Si una invasora ya se expandió, es barato sacarla."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Prevenir es la mejor herramienta, y empieza por lo que se planta.","por_opcion":{"s2":"Es una invasora: sus semillas escapan del cerco e invaden bosques.","s4":"Controlar una invasión avanzada es muy caro y a veces imposible."}}},{"slug":"plantas-2.s4.p14","orden":14,"grupo":"plantas-2.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las especies invasoras son una de las {{0}} grandes causas directas de pérdida de biodiversidad; contra ellas, lo más barato es {{1}}.","banco":[{"id":"w1","texto":"cinco"},{"id":"w2","texto":"prevenir"},{"id":"w3","texto":"diez"},{"id":"w4","texto":"restaurar"},{"id":"w5","texto":"fumigar"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La idea central de la lección sobre especies invasoras."}}]},{"slug":"plantas-2.s5","orden":5,"tipo":"leccion","titulo_es":"Elegir nativas","bajada_es":"Cómo elegir, conseguir y cuidar plantas nativas para un jardín, un balcón, una vereda o una escuela.","minutos":12,"pasos":[{"slug":"plantas-2.s5.p1","orden":1,"grupo":"plantas-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Primero, la ecorregión","cuerpo":["Para elegir nativas, el primer paso es saber en qué ecorregión estás. Hay guías y mapas oficiales y de organizaciones que muestran las ecorregiones y las plantas de cada una. Después conviene mirar el espacio: cuánto sol recibe, si es húmedo o seco, cuánto lugar hay para que crezca.","Una planta nativa en el lugar equivocado puede sufrir igual que una exótica: un árbol de selva al sol pleno de una vereda seca, o un cactus en un rincón húmedo y oscuro."]},"solucion":{}},{"slug":"plantas-2.s5.p2","orden":2,"grupo":"plantas-2.s5.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para elegir nativas para un espacio.","items":[{"id":"i1","texto":"Averiguar la ecorregión"},{"id":"i2","texto":"Observar el sol, la humedad y el espacio disponible"},{"id":"i3","texto":"Buscar nativas de la ecorregión que se adapten a esas condiciones"},{"id":"i4","texto":"Conseguirlas en un vivero de nativas"},{"id":"i5","texto":"Plantarlas y regarlas hasta que se establezcan"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Ecorregión, lugar, especie, vivero y cuidado inicial."}},{"slug":"plantas-2.s5.p3","orden":3,"grupo":"plantas-2.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dónde conseguirlas","cuerpo":["Cada vez hay más viveros que producen nativas, incluidos viveros municipales, de universidades y de organizaciones. También se pueden conseguir semillas y hacer plantines en casa.","Lo que no hay que hacer es sacar plantas de ambientes naturales: se daña el lugar, muchas veces la planta no sobrevive al trasplante y, en áreas protegidas, está prohibido."]},"solucion":{}},{"slug":"plantas-2.s5.p4","orden":4,"grupo":"plantas-2.s5.p4","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Sacar plantas nativas de una reserva natural es una buena forma de conseguirlas para el jardín.","razones":[{"id":"r1","texto":"Porque daña el ambiente y en áreas protegidas está prohibido"},{"id":"r2","texto":"Porque las plantas de las reservas son todas exóticas"},{"id":"r3","texto":"Porque las nativas no se pueden trasplantar nunca"}]},"solucion":{"valor":false,"explicacion":"Daña el ambiente, muchas veces la planta muere y en áreas protegidas está prohibido. Lo correcto es un vivero de nativas o semillas obtenidas de forma responsable.","clave":["r1"]}},{"slug":"plantas-2.s5.p5","orden":5,"grupo":"plantas-2.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Árboles para la vereda","cuerpo":["Un árbol de vereda tiene que convivir con cables, veredas, casas y personas. Conviene elegir especies de tamaño adecuado al ancho de la vereda, con raíces que no levanten el piso y que no sean invasoras. Muchos municipios tienen un listado de especies recomendadas para el arbolado.","En el área metropolitana de Buenos Aires se usan nativas como el timbó (para espacios grandes), la anacahuita, el chal chal, el ceibo y el tala, entre otras."]},"solucion":{}},{"slug":"plantas-2.s5.p6","orden":6,"grupo":"plantas-2.s5.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hay que tener en cuenta para elegir un árbol de vereda? Marcá todo.","opciones":[{"id":"o1","texto":"El tamaño que va a tener de adulto"},{"id":"o2","texto":"El ancho de la vereda y los cables"},{"id":"o3","texto":"Que no sea una especie invasora"},{"id":"o4","texto":"Las especies que recomienda el municipio"},{"id":"o5","texto":"Que sea el que crece más rápido, sin importar el tamaño final"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El árbol correcto en el lugar correcto dura décadas sin problemas. El incorrecto termina podado o arrancado."}},{"slug":"plantas-2.s5.p7","orden":7,"grupo":"plantas-2.s5.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una vereda angosta con cables, ¿qué conviene plantar?","opciones":[{"id":"o1","texto":"Un árbol nativo de porte chico o mediano"},{"id":"o2","texto":"Un timbó, que puede superar los 20 metros"},{"id":"o3","texto":"Un eucalipto, porque crece rápido"},{"id":"o4","texto":"Un ligustro, porque es resistente"}]},"solucion":{"clave":["o1"],"explicacion":"Un árbol grande en una vereda angosta termina mutilado por las podas. Mejor uno adecuado desde el principio.","por_opcion":{"o3":"Crece rápido, pero es enorme, exótico y no apto para veredas angostas."}}},{"slug":"plantas-2.s5.p8","orden":8,"grupo":"plantas-2.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Balcones y macetas","cuerpo":["En un balcón se pueden tener muchas nativas en macetas: hierbas y flores como verbenas, salvias y margaritas nativas, enredaderas como la pasionaria, y hasta pequeños arbustos. Atraen mariposas, abejas nativas y picaflores.","Las macetas se secan más rápido que el suelo, así que conviene agruparlas, usar macetas grandes y mulch (una capa de hojas o corteza sobre la tierra)."]},"solucion":{}},{"slug":"plantas-2.s5.p9","orden":9,"grupo":"plantas-2.s5.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una buena práctica para nativas en macetas o no?","grupos":[{"id":"g1","nombre":"Buena práctica"},{"id":"g2","nombre":"Mala práctica"}],"items":[{"id":"i1","texto":"Usar macetas grandes"},{"id":"i2","texto":"Macetas sin agujeros de drenaje"},{"id":"i3","texto":"Agrupar las macetas"},{"id":"i4","texto":"Plantas de selva al sol pleno del mediodía"},{"id":"i5","texto":"Cubrir la tierra con mulch"},{"id":"i6","texto":"Regar todos los días sin mirar la tierra"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las nativas también necesitan la maceta y el lugar correctos."}},{"slug":"plantas-2.s5.p10","orden":10,"grupo":"plantas-2.s5.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada espacio con una opción nativa adecuada (zona pampeana).","izquierda":[{"id":"a1","texto":"Balcón soleado"},{"id":"a2","texto":"Reja o alambrado"},{"id":"a3","texto":"Vereda angosta"},{"id":"a4","texto":"Jardín grande"}],"derecha":[{"id":"b1","texto":"Verbenas y salvias nativas"},{"id":"b2","texto":"Pasionaria"},{"id":"b3","texto":"Árbol nativo de porte chico"},{"id":"b4","texto":"Tala o timbó"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Hay nativas para casi cualquier espacio. La clave es el tamaño y las condiciones."}},{"slug":"plantas-2.s5.p11","orden":11,"grupo":"plantas-2.s5.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un balcón con nativas ayuda a la biodiversidad.","items":[{"id":"i1","texto":"Se plantan pasionaria y salvias nativas en el balcón"},{"id":"i2","texto":"Llegan mariposas espejito y picaflores"},{"id":"i3","texto":"La espejito pone huevos en la pasionaria"},{"id":"i4","texto":"Nacen orugas y después mariposas nuevas"},{"id":"i5","texto":"Las mariposas fabrican la pasionaria"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un balcón puede ser una guardería de mariposas."}},{"slug":"plantas-2.s5.p12","orden":12,"grupo":"plantas-2.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan de un vecino y marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Voy a averiguar mi ecorregión."},{"id":"s2","texto":"Voy a sacar plantas de la reserva de la costa para mi jardín."},{"id":"s3","texto":"Voy a poner una pasionaria en la reja."},{"id":"s4","texto":"Voy a plantar un timbó en la vereda angosta con cables."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Buenas intenciones, mejores con información.","por_opcion":{"s2":"Está prohibido y daña el ambiente; mejor un vivero de nativas.","s4":"El timbó es enorme: necesita mucho espacio."}}},{"slug":"plantas-2.s5.p13","orden":13,"grupo":"plantas-2.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para elegir nativas, primero hay que saber la {{0}}; se consiguen en {{1}}, nunca sacándolas de una {{2}}.","banco":[{"id":"w1","texto":"ecorregión"},{"id":"w2","texto":"viveros"},{"id":"w3","texto":"reserva"},{"id":"w4","texto":"provincia"},{"id":"w5","texto":"ferreterías"},{"id":"w6","texto":"plaza"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres reglas para empezar bien un jardín de nativas."}},{"slug":"plantas-2.s5.p14","orden":14,"grupo":"plantas-2.s5.p14","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un balcón tiene 6 metros de largo. Si se pone una maceta de nativas cada 2 metros, ¿cuántas macetas entran?","unidad":"macetas","decimales":0},"solucion":{"valor":3,"tolerancia":0.5,"explicacion":"6 ÷ 2 = 3 macetas. Agruparlas ayuda a que conserven la humedad y formen un pequeño hábitat."}},{"slug":"plantas-2.s5.p14.v2","orden":14,"grupo":"plantas-2.s5.p14","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un balcón tiene 4 metros de largo. Si se pone una maceta de nativas cada metro, ¿cuántas macetas entran?","unidad":"macetas","decimales":0},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"4 ÷ 1 = 4 macetas. Agruparlas ayuda a que conserven la humedad y formen un pequeño hábitat."}},{"slug":"plantas-2.s5.p14.v3","orden":14,"grupo":"plantas-2.s5.p14","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un balcón tiene 8 metros de largo. Si se pone una maceta de nativas cada 3 metros, ¿cuántas macetas entran?","unidad":"macetas","decimales":3},"solucion":{"valor":2.6666666666666665,"tolerancia":0.05333333333333333,"explicacion":"8 ÷ 3 = 2.6666666666666665 macetas. Agruparlas ayuda a que conserven la humedad y formen un pequeño hábitat."}}]},{"slug":"plantas-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: nativas, exóticas e invasoras","bajada_es":"Categorías, ecorregiones, relaciones con la fauna, invasoras y elección de plantas, mezclados.","minutos":8,"pasos":[{"slug":"plantas-2.s6.p1","orden":1,"grupo":"plantas-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Nativas, exóticas e invasoras». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"plantas-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el cantero de la escuela","bajada_es":"Una escuela de la zona pampeana quiere transformar su cantero en un jardín de nativas. Revisá el plan y armalo bien.","minutos":10,"pasos":[{"slug":"plantas-2.s7.p1","orden":1,"grupo":"plantas-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El cantero","cuerpo":["La escuela tiene un cantero de 20 metros cuadrados, con sol la mitad del día, en la zona pampeana. Hoy tiene césped, dos ligustros grandes y un eucalipto chico. Quieren atraer mariposas y aves, gastar poca agua y que los chicos aprendan.","Tienen presupuesto para 25 plantas y un vivero municipal de nativas a pocas cuadras."]},"solucion":{}},{"slug":"plantas-2.s7.p2","orden":2,"grupo":"plantas-2.s7.p2","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conviene hacer con los ligustros?","opciones":[{"id":"o1","texto":"Reemplazarlos de a poco por nativas, porque son invasores"},{"id":"o2","texto":"Dejarlos y plantar más ligustros para que den sombra"},{"id":"o3","texto":"Dejarlos, porque todo árbol es bueno para la fauna"},{"id":"o4","texto":"Cortarles solo las ramas bajas y conservarlos siempre"}]},"solucion":{"clave":["o1"],"explicacion":"Reemplazar invasoras por nativas evita que sigan dispersando semillas. Hacerlo de a poco permite mantener sombra mientras crecen las nuevas.","por_opcion":{"o3":"El ligustro es invasor: sus semillas escapan y afectan bosques y reservas."}}},{"slug":"plantas-2.s7.p3","orden":3,"grupo":"plantas-2.s7.p3","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué plantas convienen para el cantero? Marcá todas las adecuadas.","opciones":[{"id":"o1","texto":"Coronillo, hospedera de la bandera argentina"},{"id":"o2","texto":"Pasionaria en el alambrado"},{"id":"o3","texto":"Salvias y verbenas nativas para el néctar"},{"id":"o4","texto":"Pastos nativos del pastizal"},{"id":"o5","texto":"Más eucaliptos para que crezca rápido"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Hospederas, néctar y pastos: un pequeño pedazo de pastizal y espinal en la escuela."}},{"slug":"plantas-2.s7.p4","orden":4,"grupo":"plantas-2.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se reparten 25 plantas en los 20 m² del cantero, ¿cuántas plantas por m² son? Redondeá a un decimal.","unidad":"plantas por m²","decimales":1},"solucion":{"valor":1.3,"tolerancia":0.05,"explicacion":"25 ÷ 20 ≈ 1,3 plantas por m². Una densidad razonable para que crezcan sin taparse y cubran el suelo con el tiempo."}},{"slug":"plantas-2.s7.p4.v2","orden":4,"grupo":"plantas-2.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se reparten 30 plantas en los 20 m² del cantero, ¿cuántas plantas por m² son? Redondeá a un decimal.","unidad":"plantas por m²","decimales":1},"solucion":{"valor":1.5,"tolerancia":0.05,"explicacion":"30 ÷ 20 ≈ 1,5 plantas por m². Una densidad razonable para que crezcan sin taparse y cubran el suelo con el tiempo."}},{"slug":"plantas-2.s7.p4.v3","orden":4,"grupo":"plantas-2.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se reparten 20 plantas en los 20 m² del cantero, ¿cuántas plantas por m² son? Redondeá a un decimal.","unidad":"plantas por m²","decimales":1},"solucion":{"valor":1,"tolerancia":0.05,"explicacion":"20 ÷ 20 ≈ 1 plantas por m². Una densidad razonable para que crezcan sin taparse y cubran el suelo con el tiempo."}},{"slug":"plantas-2.s7.p5","orden":5,"grupo":"plantas-2.s7.p5","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos del proyecto.","items":[{"id":"i1","texto":"Averiguar qué nativas de la ecorregión se adaptan al lugar"},{"id":"i2","texto":"Conseguir las plantas en el vivero municipal"},{"id":"i3","texto":"Retirar el césped de una parte y preparar la tierra"},{"id":"i4","texto":"Plantar y cubrir con mulch"},{"id":"i5","texto":"Regar hasta que se establezcan y registrar qué fauna aparece"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Informarse, conseguir, preparar, plantar, cuidar y observar."}},{"slug":"plantas-2.s7.p6","orden":6,"grupo":"plantas-2.s7.p6","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las ideas de los docentes.","grupos":[{"id":"g1","nombre":"Buena idea"},{"id":"g2","nombre":"Mala idea"}],"items":[{"id":"i1","texto":"Carteles con el nombre de cada nativa"},{"id":"i2","texto":"Traer plantas sacadas de una reserva cercana"},{"id":"i3","texto":"Registrar las mariposas que aparecen en ArgentiNat"},{"id":"i4","texto":"Fumigar para que no haya orugas"},{"id":"i5","texto":"Juntar semillas del cantero para otras escuelas"},{"id":"i6","texto":"Regar todos los días aunque llueva"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las orugas son justamente el objetivo: sin ellas no hay mariposas."}},{"slug":"plantas-2.s7.p7","orden":7,"grupo":"plantas-2.s7.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si aparecen orugas comiendo las hojas de la pasionaria, hay que fumigar.","razones":[{"id":"r1","texto":"Porque esas orugas son las futuras mariposas que se buscan atraer"},{"id":"r2","texto":"Porque las orugas no comen plantas"},{"id":"r3","texto":"Porque fumigar ayuda a las mariposas"}]},"solucion":{"valor":false,"explicacion":"Esas orugas son probablemente de mariposa espejito: el objetivo del proyecto. La pasionaria se recupera, y de las orugas salen mariposas.","clave":["r1"]}},{"slug":"plantas-2.s7.p8","orden":8,"grupo":"plantas-2.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La escuela escribe el proyecto. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Reemplazaremos los ligustros de a poco por talas y coronillos."},{"id":"s2","texto":"Plantaremos un timbó en el centro del cantero de 20 m²."},{"id":"s3","texto":"Sumaremos pastos nativos y flores para polinizadores."},{"id":"s4","texto":"Pondremos mariposas compradas para que el jardín tenga vida desde el primer día."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen jardín de nativas crea las condiciones y deja que la fauna llegue.","por_opcion":{"s2":"El timbó es un árbol enorme: no entra en un cantero chico.","s4":"Si hay plantas hospederas y de néctar, las mariposas llegan solas."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"plantas-3","rama":"plantas","orden":3,"nivel":2,"titulo_es":"Verde urbano","bajada_es":"Una cuadra con árboles puede estar varios grados más fresca que una sin ellos. La isla de calor, qué hacen los árboles por la ciudad y cómo elegirlos y cuidarlos.","objetivos_es":["Explicar la isla de calor urbana y sus efectos","Describir los servicios que el arbolado presta a una ciudad","Elegir especies adecuadas para cada espacio urbano","Reconocer buenas y malas prácticas en el cuidado del arbolado","Proponer estrategias para ciudades más verdes"],"repasa":["plantas-1","plantas-2","agua-5"],"requiere_tronco":2,"fuentes":["epa-isla-calor","oms-espacios-verdes","plantas-nativas","ecorregiones-pba","ipcc-ar6-syr"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"plantas-3.s1","orden":1,"tipo":"leccion","titulo_es":"La isla de calor","bajada_es":"Por qué las ciudades son más calurosas que el campo que las rodea y a quién afecta más.","minutos":11,"pasos":[{"slug":"plantas-3.s1.p1","orden":1,"grupo":"plantas-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una ciudad más caliente","cuerpo":["Las ciudades suelen ser más calurosas que las zonas rurales cercanas: es la isla de calor urbana. El asfalto, el cemento y los techos oscuros absorben el sol durante el día y liberan ese calor de noche. Hay pocas plantas que refresquen con su transpiración, los edificios frenan el viento, y los autos y aires acondicionados suman calor.","La diferencia suele ser de varios grados, y es mayor de noche, cuando el campo se enfría y la ciudad sigue devolviendo el calor acumulado."]},"solucion":{}},{"slug":"plantas-3.s1.p2","orden":2,"grupo":"plantas-3.s1.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué contribuye a la isla de calor urbana? Marcá todo.","opciones":[{"id":"o1","texto":"Asfalto y techos oscuros que absorben el sol"},{"id":"o2","texto":"Pocas plantas que refresquen el aire"},{"id":"o3","texto":"Edificios que frenan el viento"},{"id":"o4","texto":"Calor de autos y aires acondicionados"},{"id":"o5","texto":"Parques con muchos árboles"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Materiales que guardan calor, poco verde y mucha actividad: la receta de la isla de calor."}},{"slug":"plantas-3.s1.p3","orden":3,"grupo":"plantas-3.s1.p3","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué la ciudad sigue caliente de noche.","items":[{"id":"i1","texto":"Durante el día, el asfalto y el cemento absorben el sol"},{"id":"i2","texto":"Guardan ese calor en su masa"},{"id":"i3","texto":"De noche, lo liberan lentamente al aire"},{"id":"i4","texto":"La temperatura nocturna baja poco"},{"id":"i5","texto":"Las noches se vuelven más calurosas que en el campo"},{"id":"i6","texto":"El asfalto enfría el aire de noche"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Por eso las olas de calor pesan tanto en las ciudades: no hay descanso nocturno."}},{"slug":"plantas-3.s1.p4","orden":4,"grupo":"plantas-3.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quiénes sufren más","cuerpo":["El calor extremo es un riesgo para la salud: puede causar golpes de calor y empeorar enfermedades del corazón y los pulmones. Afecta más a personas mayores, bebés, personas con enfermedades crónicas, trabajadores al aire libre y a quienes viven en viviendas precarias sin ventilación ni aire acondicionado.","Muchas veces los barrios con menos árboles son los barrios de menores ingresos: la isla de calor también es desigual."]},"solucion":{}},{"slug":"plantas-3.s1.p5","orden":5,"grupo":"plantas-3.s1.p5","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta persona es más vulnerable al calor extremo?","grupos":[{"id":"g1","nombre":"Más vulnerable"},{"id":"g2","nombre":"Menos vulnerable"}],"items":[{"id":"i1","texto":"Un abuelo que vive solo en un departamento sin ventilación"},{"id":"i2","texto":"Un adulto sano en una casa ventilada con árboles alrededor"},{"id":"i3","texto":"Un bebé"},{"id":"i4","texto":"Una joven sana que trabaja en una oficina fresca"},{"id":"i5","texto":"Un repartidor que trabaja al sol"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"La vulnerabilidad depende de la edad, la salud, el trabajo y la vivienda."}},{"slug":"plantas-3.s1.p6","orden":6,"grupo":"plantas-3.s1.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La isla de calor afecta a todos los barrios de una ciudad por igual.","razones":[{"id":"r1","texto":"Porque los barrios con menos verde suelen ser más calurosos"},{"id":"r2","texto":"Porque la temperatura es igual en toda la ciudad"},{"id":"r3","texto":"Porque el calor solo afecta a los barrios con árboles"}]},"solucion":{"valor":false,"explicacion":"Los barrios con menos árboles y más cemento suelen ser más calurosos, y muchas veces coinciden con los de menores ingresos.","clave":["r1"]}},{"slug":"plantas-3.s1.p7","orden":7,"grupo":"plantas-3.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Techos y pavimentos","cuerpo":["Los colores oscuros absorben más sol y se calientan más. Un techo de membrana negra puede superar los 70 °C en un día de verano, mientras que uno blanco o claro se mantiene mucho más fresco. Pintar techos de blanco y usar pavimentos claros o permeables ayuda a bajar la temperatura de las casas y de la ciudad."]},"solucion":{}},{"slug":"plantas-3.s1.p8","orden":8,"grupo":"plantas-3.s1.p8","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas superficies por cuánto se calientan al sol de verano, de más a menos.","items":[{"id":"i1","texto":"Techo de membrana negra"},{"id":"i2","texto":"Asfalto"},{"id":"i3","texto":"Techo pintado de blanco"},{"id":"i4","texto":"Pasto a la sombra de un árbol"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Color, material y sombra deciden cuánto calor absorbe una superficie.","valores":{"i1":"muy caliente","i2":"caliente","i3":"mucho menos","i4":"la más fresca"}}},{"slug":"plantas-3.s1.p9","orden":9,"grupo":"plantas-3.s1.p9","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un barrio muy caluroso, ¿qué medida ayuda rápido a bajar la temperatura dentro de las casas?","opciones":[{"id":"o1","texto":"Pintar los techos de blanco"},{"id":"o2","texto":"Pintar los techos de negro"},{"id":"o3","texto":"Sacar los árboles para que corra más aire"},{"id":"o4","texto":"Asfaltar los patios de tierra"}]},"solucion":{"clave":["o1"],"explicacion":"Un techo claro refleja el sol y puede bajar varios grados la temperatura interior.","por_opcion":{"o3":"Los árboles dan sombra y refrescan: sacarlos empeora el calor."}}},{"slug":"plantas-3.s1.p10","orden":10,"grupo":"plantas-3.s1.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una noche de verano, el campo cercano llega a 26 °C y el centro de la ciudad está 4 °C más caliente. ¿Qué temperatura hay en el centro?","unidad":"°C","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"26 + 4 = 30 °C. Unos grados de más de noche impiden que el cuerpo descanse y aumentan los riesgos para la salud."}},{"slug":"plantas-3.s1.p10.v2","orden":10,"grupo":"plantas-3.s1.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una noche de verano, el campo cercano llega a 28 °C y el centro de la ciudad está 3 °C más caliente. ¿Qué temperatura hay en el centro?","unidad":"°C","decimales":0},"solucion":{"valor":31,"tolerancia":0.62,"explicacion":"28 + 3 = 31 °C. Unos grados de más de noche impiden que el cuerpo descanse y aumentan los riesgos para la salud."}},{"slug":"plantas-3.s1.p10.v3","orden":10,"grupo":"plantas-3.s1.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una noche de verano, el campo cercano llega a 25 °C y el centro de la ciudad está 5 °C más caliente. ¿Qué temperatura hay en el centro?","unidad":"°C","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"25 + 5 = 30 °C. Unos grados de más de noche impiden que el cuerpo descanse y aumentan los riesgos para la salud."}},{"slug":"plantas-3.s1.p11","orden":11,"grupo":"plantas-3.s1.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Las ciudades suelen ser más calurosas que el campo."},{"id":"s2","texto":"La isla de calor desaparece de noche."},{"id":"s3","texto":"Los techos claros se calientan menos que los oscuros."},{"id":"s4","texto":"El calor extremo solo es molesto, no afecta la salud."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El calor urbano es un tema de salud pública.","por_opcion":{"s2":"Suele ser más intensa de noche, cuando el cemento libera el calor acumulado.","s4":"Puede causar golpes de calor y agravar enfermedades."}}},{"slug":"plantas-3.s1.p12","orden":12,"grupo":"plantas-3.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las ciudades suelen ser más calurosas que el campo por la isla de {{0}}; el efecto es mayor de {{1}}; y los techos {{2}} ayudan a reducirlo.","banco":[{"id":"w1","texto":"calor"},{"id":"w2","texto":"noche"},{"id":"w3","texto":"claros"},{"id":"w4","texto":"humo"},{"id":"w5","texto":"mañana"},{"id":"w6","texto":"oscuros"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La isla de calor, resumida en una sola línea."}},{"slug":"plantas-3.s1.p13","orden":13,"grupo":"plantas-3.s1.p13","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada causa de la isla de calor con una solución.","izquierda":[{"id":"a1","texto":"Techos oscuros"},{"id":"a2","texto":"Falta de sombra"},{"id":"a3","texto":"Suelos sellados"},{"id":"a4","texto":"Calor de motores"}],"derecha":[{"id":"b1","texto":"Pintarlos de blanco o hacer techos verdes"},{"id":"b2","texto":"Plantar árboles en veredas y plazas"},{"id":"b3","texto":"Pavimentos permeables y canteros"},{"id":"b4","texto":"Menos autos y más transporte público"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada causa tiene su respuesta: sombra, color, suelo y movilidad."}}]},{"slug":"plantas-3.s2","orden":2,"tipo":"leccion","titulo_es":"Qué hacen los árboles por la ciudad","bajada_es":"Sombra, frescura, agua, aire, ruido, biodiversidad y salud mental: el trabajo del arbolado.","minutos":11,"pasos":[{"slug":"plantas-3.s2.p1","orden":1,"grupo":"plantas-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Sombra y frescura","cuerpo":["Un árbol refresca de dos formas: su copa da sombra, y con la transpiración evapora agua, que se lleva calor del aire. Según la Agencia de Protección Ambiental de Estados Unidos, las superficies a la sombra pueden estar entre 10 y 25 °C más frescas que las expuestas al sol, y la transpiración puede bajar algunos grados la temperatura del aire."],"destacado":{"valor":"10-25 °C","texto":"más frescas pueden estar las superficies a la sombra que las expuestas al sol, según la EPA."}},"solucion":{}},{"slug":"plantas-3.s2.p2","orden":2,"grupo":"plantas-3.s2.p2","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un árbol refresca una cuadra.","items":[{"id":"i1","texto":"El árbol da sombra sobre la vereda"},{"id":"i2","texto":"El suelo y las paredes absorben menos sol"},{"id":"i3","texto":"Además, transpira agua por sus hojas"},{"id":"i4","texto":"La evaporación se lleva calor del aire"},{"id":"i5","texto":"La cuadra está más fresca"},{"id":"i6","texto":"El árbol genera aire acondicionado eléctrico"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Sombra más evaporación: el aire acondicionado natural de la ciudad."}},{"slug":"plantas-3.s2.p3","orden":3,"grupo":"plantas-3.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Agua, aire y ruido","cuerpo":["Las copas interceptan parte de la lluvia y las raíces ayudan a que el agua se infiltre, lo que reduce la escorrentía y el riesgo de anegamientos, como viste en la rama de Agua. Las hojas retienen polvo y partículas del aire. Y la vegetación densa puede amortiguar algo el ruido.","Los árboles también son hábitat de aves e insectos, y conectan plazas y reservas como corredores de biodiversidad."]},"solucion":{}},{"slug":"plantas-3.s2.p4","orden":4,"grupo":"plantas-3.s2.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada servicio del arbolado con cómo lo hace.","izquierda":[{"id":"a1","texto":"Refrescar"},{"id":"a2","texto":"Reducir anegamientos"},{"id":"a3","texto":"Mejorar el aire"},{"id":"a4","texto":"Sostener biodiversidad"}],"derecha":[{"id":"b1","texto":"Sombra y transpiración"},{"id":"b2","texto":"Interceptar lluvia y ayudar a infiltrar"},{"id":"b3","texto":"Retener polvo y partículas en las hojas"},{"id":"b4","texto":"Dar refugio y alimento a aves e insectos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Un árbol de vereda hace muchos trabajos a la vez."}},{"slug":"plantas-3.s2.p5","orden":5,"grupo":"plantas-3.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Salud y bienestar","cuerpo":["La Organización Mundial de la Salud reconoce que los espacios verdes urbanos tienen beneficios para la salud: promueven la actividad física, reducen el estrés, mejoran la salud mental, favorecen el encuentro social y mitigan el calor. Vivir cerca de plazas y parques se asocia con mejor bienestar."]},"solucion":{}},{"slug":"plantas-3.s2.p6","orden":6,"grupo":"plantas-3.s2.p6","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué beneficios para la salud tienen los espacios verdes, según la OMS? Marcá todos.","opciones":[{"id":"o1","texto":"Promueven la actividad física"},{"id":"o2","texto":"Reducen el estrés"},{"id":"o3","texto":"Favorecen el encuentro social"},{"id":"o4","texto":"Mitigan el calor"},{"id":"o5","texto":"Curan cualquier enfermedad"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Muchos beneficios comprobados, sin ser un remedio mágico."}},{"slug":"plantas-3.s2.p7","orden":7,"grupo":"plantas-3.s2.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un árbol de vereda solo sirve para decorar.","razones":[{"id":"r1","texto":"Porque presta muchos servicios: es infraestructura verde"},{"id":"r2","texto":"Porque los árboles no hacen fotosíntesis en la ciudad"},{"id":"r3","texto":"Porque los árboles calientan las veredas"}]},"solucion":{"valor":false,"explicacion":"Da sombra, refresca, reduce anegamientos, retiene partículas, alberga fauna y mejora el bienestar. Es infraestructura verde.","clave":["r1"]}},{"slug":"plantas-3.s2.p8","orden":8,"grupo":"plantas-3.s2.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una vereda al sol llega a 55 °C. Si la sombra de un árbol la deja 20 °C más fresca, ¿qué temperatura tiene a la sombra?","unidad":"°C","decimales":0},"solucion":{"valor":35,"tolerancia":0.7000000000000001,"explicacion":"55 − 20 = 35 °C. Por eso la gente busca instintivamente la vereda con árboles."}},{"slug":"plantas-3.s2.p8.v2","orden":8,"grupo":"plantas-3.s2.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una vereda al sol llega a 60 °C. Si la sombra de un árbol la deja 25 °C más fresca, ¿qué temperatura tiene a la sombra?","unidad":"°C","decimales":0},"solucion":{"valor":35,"tolerancia":0.7000000000000001,"explicacion":"60 − 25 = 35 °C. Por eso la gente busca instintivamente la vereda con árboles."}},{"slug":"plantas-3.s2.p8.v3","orden":8,"grupo":"plantas-3.s2.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una vereda al sol llega a 50 °C. Si la sombra de un árbol la deja 15 °C más fresca, ¿qué temperatura tiene a la sombra?","unidad":"°C","decimales":0},"solucion":{"valor":35,"tolerancia":0.7000000000000001,"explicacion":"50 − 15 = 35 °C. Por eso la gente busca instintivamente la vereda con árboles."}},{"slug":"plantas-3.s2.p9","orden":9,"grupo":"plantas-3.s2.p9","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este beneficio del arbolado es ambiental o social?","grupos":[{"id":"g1","nombre":"Ambiental"},{"id":"g2","nombre":"Social"}],"items":[{"id":"i1","texto":"Guardar carbono"},{"id":"i2","texto":"Invitar a caminar"},{"id":"i3","texto":"Dar hábitat a las aves"},{"id":"i4","texto":"Lugar de encuentro en la plaza"},{"id":"i5","texto":"Ayudar a infiltrar la lluvia"},{"id":"i6","texto":"Reducir el estrés"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El verde urbano cuida el ambiente y a las personas al mismo tiempo."}},{"slug":"plantas-3.s2.p10","orden":10,"grupo":"plantas-3.s2.p10","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una ola de calor, ¿qué cuadra es probablemente más fresca a la tarde?","opciones":[{"id":"o1","texto":"La que tiene árboles grandes en las dos veredas"},{"id":"o2","texto":"La que tiene el asfalto recién hecho"},{"id":"o3","texto":"La que tiene más autos estacionados"},{"id":"o4","texto":"La que tiene veredas de cemento sin árboles"}]},"solucion":{"clave":["o1"],"explicacion":"Árboles grandes y sanos: la mejor defensa de una cuadra contra el calor.","por_opcion":{"o3":"Los autos al sol se calientan y suman calor."}}},{"slug":"plantas-3.s2.p11","orden":11,"grupo":"plantas-3.s2.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos espacios por cuánto refrescan en un día de calor, de más a menos.","items":[{"id":"i1","texto":"Parque con árboles grandes y césped"},{"id":"i2","texto":"Vereda con árboles adultos"},{"id":"i3","texto":"Plaza seca con pocos árboles jóvenes"},{"id":"i4","texto":"Estacionamiento de asfalto"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El tamaño de las copas y la cantidad de verde hacen la diferencia.","valores":{"i1":"mucho","i2":"bastante","i3":"poco","i4":"nada: suma calor"}}},{"slug":"plantas-3.s2.p12","orden":12,"grupo":"plantas-3.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión en un grupo vecinal y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los árboles dan sombra y refrescan la cuadra."},{"id":"s2","texto":"Los árboles ensucian y no sirven para nada."},{"id":"s3","texto":"Las copas interceptan parte de la lluvia."},{"id":"s4","texto":"Sacar los árboles hace que la cuadra sea más fresca porque corre más aire."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los árboles tienen costos de mantenimiento, pero sus beneficios son mucho mayores.","por_opcion":{"s2":"Las hojas se pueden compostar; y los árboles prestan muchos servicios.","s4":"Sin sombra ni transpiración, la cuadra se calienta más."}}},{"slug":"plantas-3.s2.p13","orden":13,"grupo":"plantas-3.s2.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un árbol refresca con la {{0}} y la {{1}}; y según la OMS, los espacios verdes reducen el {{2}}.","banco":[{"id":"w1","texto":"sombra"},{"id":"w2","texto":"transpiración"},{"id":"w3","texto":"estrés"},{"id":"w4","texto":"lluvia"},{"id":"w5","texto":"raíz"},{"id":"w6","texto":"tránsito"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Cómo trabajan los árboles por la ciudad, en una línea."}},{"slug":"plantas-3.s2.p14","orden":14,"grupo":"plantas-3.s2.p14","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos grados más fresca puede estar una superficie a la sombra que una al sol, según la EPA.","min":0,"max":40,"paso":1,"unidad":"°C","escala":"lineal"},"solucion":{"valor":18,"banda":"lineal","explicacion":"Entre 10 y 25 °C. Una diferencia enorme que se siente al caminar."}}]},{"slug":"plantas-3.s3","orden":3,"tipo":"leccion","titulo_es":"El árbol correcto en el lugar correcto","bajada_es":"Tamaño adulto, raíces, cables, veredas, especies nativas y la cazuela: cómo elegir.","minutos":11,"pasos":[{"slug":"plantas-3.s3.p1","orden":1,"grupo":"plantas-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Pensar en el árbol adulto","cuerpo":["El error más común al plantar en la ciudad es pensar en el árbol chico y no en cómo va a ser de adulto. Un árbol que llega a 20 metros de alto y 15 de copa no entra en una vereda angosta con cables: terminará mutilado por las podas o levantando la vereda.","Por eso se elige la especie según el espacio disponible: ancho de vereda, altura de cables, distancia a la casa y tamaño de la cazuela, el hueco de tierra donde se planta."]},"solucion":{}},{"slug":"plantas-3.s3.p2","orden":2,"grupo":"plantas-3.s3.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tamaño de árbol conviene para cada lugar?","grupos":[{"id":"g1","nombre":"Árbol grande (más de 15 m)"},{"id":"g2","nombre":"Árbol chico o mediano"}],"items":[{"id":"i1","texto":"Plaza amplia"},{"id":"i2","texto":"Vereda angosta con cables"},{"id":"i3","texto":"Parque"},{"id":"i4","texto":"Patio chico"},{"id":"i5","texto":"Avenida ancha sin cables"},{"id":"i6","texto":"Cantero de un edificio"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Cada espacio tiene su tamaño de árbol. Así se evitan podas drásticas y veredas rotas."}},{"slug":"plantas-3.s3.p3","orden":3,"grupo":"plantas-3.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Raíces y cazuelas","cuerpo":["Las raíces necesitan espacio, aire y agua. En una cazuela diminuta rodeada de cemento, el árbol sufre y sus raíces buscan salir, a veces levantando baldosas. Cazuelas más grandes o canteros corridos, con suelo suelto, hacen árboles más sanos y veredas más enteras."]},"solucion":{}},{"slug":"plantas-3.s3.p4","orden":4,"grupo":"plantas-3.s3.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué una cazuela chica termina rompiendo la vereda.","items":[{"id":"i1","texto":"Se planta un árbol en una cazuela muy chica"},{"id":"i2","texto":"Las raíces no tienen espacio, aire ni agua suficientes"},{"id":"i3","texto":"Crecen cerca de la superficie buscando agua y aire"},{"id":"i4","texto":"Levantan las baldosas"},{"id":"i5","texto":"Se culpa al árbol y se lo quiere sacar"},{"id":"i6","texto":"El árbol levanta la vereda a propósito"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Muchas veces el problema no es el árbol, sino el espacio que se le dio."}},{"slug":"plantas-3.s3.p5","orden":5,"grupo":"plantas-3.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Nativas y diversidad","cuerpo":["Como viste en la rama, las especies nativas de la ecorregión alimentan mejor a la fauna local y suelen adaptarse bien al clima. En el arbolado urbano también importa la diversidad: si todas las calles tienen la misma especie, una plaga o enfermedad puede afectar a miles de árboles a la vez.","Las especies invasoras, como el ligustro, no conviene plantarlas."]},"solucion":{}},{"slug":"plantas-3.s3.p6","orden":6,"grupo":"plantas-3.s3.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Es buena idea plantar la misma especie en todas las calles de una ciudad.","razones":[{"id":"r1","texto":"Porque una plaga podría afectar a todos a la vez"},{"id":"r2","texto":"Porque todas las especies son iguales"},{"id":"r3","texto":"Porque la diversidad aumenta las plagas"}]},"solucion":{"valor":false,"explicacion":"Si llega una plaga o una enfermedad que afecta a esa especie, se pueden perder miles de árboles a la vez. La diversidad es un seguro.","clave":["r1"]}},{"slug":"plantas-3.s3.p7","orden":7,"grupo":"plantas-3.s3.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada condición del lugar con la elección adecuada.","izquierda":[{"id":"a1","texto":"Vereda angosta con cables"},{"id":"a2","texto":"Plaza grande"},{"id":"a3","texto":"Zona seca"},{"id":"a4","texto":"Barrio con una sola especie"}],"derecha":[{"id":"b1","texto":"Especie de porte chico"},{"id":"b2","texto":"Especie de porte grande y copa amplia"},{"id":"b3","texto":"Especie adaptada a poca agua"},{"id":"b4","texto":"Sumar especies distintas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Elegir es mirar el lugar antes que la especie."}},{"slug":"plantas-3.s3.p8","orden":8,"grupo":"plantas-3.s3.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene tener en cuenta al elegir un árbol para una vereda? Marcá todo.","opciones":[{"id":"o1","texto":"Su tamaño adulto"},{"id":"o2","texto":"El ancho de la vereda y los cables"},{"id":"o3","texto":"Que no sea invasor"},{"id":"o4","texto":"La diversidad de especies de la cuadra"},{"id":"o5","texto":"Que crezca lo más rápido posible sin importar el tamaño final"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Pensar en décadas de vida del árbol, no en el primer año."}},{"slug":"plantas-3.s3.p9","orden":9,"grupo":"plantas-3.s3.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una vereda mide 2,5 m de ancho y hay que dejar al menos 1,5 m libres para caminar. ¿Cuántos metros de ancho quedan como máximo para la cazuela o el cantero?","unidad":"metros","decimales":1},"solucion":{"valor":1,"tolerancia":0.05,"explicacion":"2,5 − 1,5 = 1 m. Con menos de 1 m de cazuela, conviene un árbol chico o un cantero corrido."}},{"slug":"plantas-3.s3.p9.v2","orden":9,"grupo":"plantas-3.s3.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una vereda mide 3 m de ancho y hay que dejar al menos 1,5 m libres para caminar. ¿Cuántos metros de ancho quedan como máximo para la cazuela o el cantero?","unidad":"metros","decimales":1},"solucion":{"valor":1.5,"tolerancia":0.05,"explicacion":"3 − 1,5 = 1,5 m. Con menos de 1 m de cazuela, conviene un árbol chico o un cantero corrido."}},{"slug":"plantas-3.s3.p9.v3","orden":9,"grupo":"plantas-3.s3.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una vereda mide 4 m de ancho y hay que dejar al menos 1,5 m libres para caminar. ¿Cuántos metros de ancho quedan como máximo para la cazuela o el cantero?","unidad":"metros","decimales":1},"solucion":{"valor":2.5,"tolerancia":0.05,"explicacion":"4 − 1,5 = 2,5 m. Con menos de 1 m de cazuela, conviene un árbol chico o un cantero corrido."}},{"slug":"plantas-3.s3.p10","orden":10,"grupo":"plantas-3.s3.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una vereda angosta con cables, un vecino quiere plantar un timbó. ¿Qué le aconsejarías?","opciones":[{"id":"o1","texto":"Elegir una especie nativa de porte chico"},{"id":"o2","texto":"Plantarlo igual y podarlo fuerte cada año"},{"id":"o3","texto":"Plantar un eucalipto, que crece más rápido"},{"id":"o4","texto":"No plantar ningún árbol en toda la cuadra"}]},"solucion":{"clave":["o1"],"explicacion":"El timbó es magnífico en una plaza grande. En una vereda angosta, mejor una nativa chica.","por_opcion":{"o3":"Es enorme y exótico: no apto para una vereda angosta."}}},{"slug":"plantas-3.s3.p11","orden":11,"grupo":"plantas-3.s3.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas cazuelas de la peor a la mejor para la salud de un árbol.","items":[{"id":"i1","texto":"Cazuela de 40 × 40 cm rodeada de cemento"},{"id":"i2","texto":"Cazuela de 80 × 80 cm"},{"id":"i3","texto":"Cazuela de 1 × 2 m con suelo suelto"},{"id":"i4","texto":"Cantero corrido a lo largo de la vereda"}],"extremos":["Peor","Mejor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Más suelo vivo alrededor, más árbol sano y menos veredas rotas.","valores":{"i1":"la peor","i2":"regular","i3":"buena","i4":"la mejor"}}},{"slug":"plantas-3.s3.p12","orden":12,"grupo":"plantas-3.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan de arbolado y marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Elegiremos especies según el ancho de cada vereda."},{"id":"s2","texto":"Plantaremos ligustro porque crece rápido."},{"id":"s3","texto":"Sumaremos varias especies nativas en cada barrio."},{"id":"s4","texto":"Haremos cazuelas de 30 × 30 cm para no ocupar vereda."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Buenas intenciones, mejores con criterio técnico.","por_opcion":{"s2":"Es una especie invasora: no conviene plantarla.","s4":"Son demasiado chicas: el árbol sufre y termina levantando la vereda."}}},{"slug":"plantas-3.s3.p13","orden":13,"grupo":"plantas-3.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Al plantar hay que pensar en el tamaño {{0}}; el hueco de tierra donde se planta es la {{1}}; y la {{2}} de especies protege de plagas.","banco":[{"id":"w1","texto":"adulto"},{"id":"w2","texto":"cazuela"},{"id":"w3","texto":"diversidad"},{"id":"w4","texto":"inicial"},{"id":"w5","texto":"maceta"},{"id":"w6","texto":"uniformidad"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres criterios para elegir árboles urbanos."}},{"slug":"plantas-3.s3.p14","orden":14,"grupo":"plantas-3.s3.p14","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos metros de ancho libre conviene dejar en una vereda para caminar cómodo, incluso con silla de ruedas.","min":0.5,"max":5,"paso":0.1,"unidad":"metros","escala":"lineal"},"solucion":{"valor":1.5,"banda":"lineal","explicacion":"Alrededor de 1,5 metros. Árboles y peatones tienen que convivir en la vereda."}}]},{"slug":"plantas-3.s4","orden":4,"tipo":"leccion","titulo_es":"Cuidar el arbolado","bajada_es":"Riego inicial, poda correcta, el desmoche que mata árboles y cómo reclamar.","minutos":11,"pasos":[{"slug":"plantas-3.s4.p1","orden":1,"grupo":"plantas-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los primeros años","cuerpo":["Un árbol recién plantado necesita riego regular durante los primeros dos o tres años, sobre todo en verano, hasta que sus raíces se establecen. Un tutor lo sostiene mientras el tronco se afirma, y una protección evita golpes. Muchos árboles jóvenes mueren por falta de riego o por daños en ese período."]},"solucion":{}},{"slug":"plantas-3.s4.p2","orden":2,"grupo":"plantas-3.s4.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los cuidados de un árbol recién plantado.","items":[{"id":"i1","texto":"Plantarlo en una cazuela amplia con buena tierra"},{"id":"i2","texto":"Colocar un tutor y una protección"},{"id":"i3","texto":"Regarlo seguido los primeros años, sobre todo en verano"},{"id":"i4","texto":"Retirar el tutor cuando el tronco se afirma"},{"id":"i5","texto":"Controlar su salud y podar solo si hace falta"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los primeros años deciden si el árbol llega a adulto."}},{"slug":"plantas-3.s4.p3","orden":3,"grupo":"plantas-3.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Podar bien","cuerpo":["Una buena poda es mínima y tiene un motivo: sacar ramas secas, enfermas o peligrosas, o despejar un cartel o un cable. Se corta en el lugar correcto, cerca del tronco o de otra rama, sin dejar tocones.","El desmoche —cortar todas las ramas principales dejando \"muñones\"— es una de las peores prácticas: debilita al árbol, lo expone a hongos y plagas, hace que rebrote con ramas débiles y peligrosas, y le quita sombra por años."]},"solucion":{}},{"slug":"plantas-3.s4.p4","orden":4,"grupo":"plantas-3.s4.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una poda correcta o un desmoche dañino?","grupos":[{"id":"g1","nombre":"Poda correcta"},{"id":"g2","nombre":"Desmoche"}],"items":[{"id":"i1","texto":"Sacar una rama seca"},{"id":"i2","texto":"Cortar todas las ramas principales dejando muñones"},{"id":"i3","texto":"Despejar una rama que toca un cable"},{"id":"i4","texto":"Dejar solo el tronco \"para que rebrote\""},{"id":"i5","texto":"Cortar una rama enferma cerca del tronco"},{"id":"i6","texto":"Podar todo el árbol cada año por costumbre"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Podar poco y con motivo. El desmoche no \"renueva\" el árbol: lo enferma."}},{"slug":"plantas-3.s4.p5","orden":5,"grupo":"plantas-3.s4.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el desmoche es peligroso.","items":[{"id":"i1","texto":"Se cortan todas las ramas grandes"},{"id":"i2","texto":"Quedan heridas grandes por donde entran hongos"},{"id":"i3","texto":"El árbol rebrota con muchas ramas débiles"},{"id":"i4","texto":"Esas ramas se quiebran con el viento"},{"id":"i5","texto":"El árbol queda enfermo y más peligroso que antes"},{"id":"i6","texto":"El árbol queda más fuerte y seguro"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una práctica que se hace \"por seguridad\" termina generando más riesgo."}},{"slug":"plantas-3.s4.p6","orden":6,"grupo":"plantas-3.s4.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Podar mucho un árbol todos los años lo hace más sano y fuerte.","razones":[{"id":"r1","texto":"Porque le quita hojas y abre heridas a enfermedades"},{"id":"r2","texto":"Porque los árboles necesitan perder todas sus ramas"},{"id":"r3","texto":"Porque la poda no afecta al árbol"}]},"solucion":{"valor":false,"explicacion":"Las podas excesivas debilitan al árbol, le quitan hojas para hacer fotosíntesis y abren heridas a enfermedades. Lo mejor es podar poco y solo con motivo.","clave":["r1"]}},{"slug":"plantas-3.s4.p7","orden":7,"grupo":"plantas-3.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quién cuida el arbolado","cuerpo":["En muchas ciudades, el arbolado de las veredas es público y su cuidado corresponde al municipio: plantar, podar, extraer árboles peligrosos y reponer los que faltan. Los vecinos pueden ayudar regando, cuidando la cazuela y reclamando cuando un árbol está enfermo o hace falta plantar. Muchas ciudades prohíben que los vecinos poden o saquen árboles de la vereda sin autorización."]},"solucion":{}},{"slug":"plantas-3.s4.p8","orden":8,"grupo":"plantas-3.s4.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cómo pueden ayudar los vecinos al arbolado? Marcá todo.","opciones":[{"id":"o1","texto":"Regar los árboles jóvenes en verano"},{"id":"o2","texto":"Mantener la cazuela sin basura"},{"id":"o3","texto":"Reclamar al municipio cuando falta un árbol"},{"id":"o4","texto":"Avisar si un árbol tiene ramas peligrosas"},{"id":"o5","texto":"Desmochar el árbol de su vereda sin permiso"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cuidar y reclamar, sí. Podar o sacar sin autorización, no."}},{"slug":"plantas-3.s4.p9","orden":9,"grupo":"plantas-3.s4.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un árbol joven necesita 20 litros de agua 2 veces por semana durante 4 meses de verano (4 semanas por mes). ¿Cuántos litros necesita en total?","unidad":"litros","decimales":0},"solucion":{"valor":640,"tolerancia":12.8,"explicacion":"20 × 2 × 4 × 4 = 640 litros. Unos baldes por semana pueden salvar a un árbol que dará sombra por décadas."}},{"slug":"plantas-3.s4.p9.v2","orden":9,"grupo":"plantas-3.s4.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un árbol joven necesita 30 litros de agua una vez por semana durante 5 meses de verano (4 semanas por mes). ¿Cuántos litros necesita en total?","unidad":"litros","decimales":0},"solucion":{"valor":600,"tolerancia":12,"explicacion":"30 × 1 × 5 × 4 = 600 litros. Unos baldes por semana pueden salvar a un árbol que dará sombra por décadas."}},{"slug":"plantas-3.s4.p9.v3","orden":9,"grupo":"plantas-3.s4.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un árbol joven necesita 40 litros de agua 2 veces por semana durante 3 meses de verano (4 semanas por mes). ¿Cuántos litros necesita en total?","unidad":"litros","decimales":0},"solucion":{"valor":960,"tolerancia":19.2,"explicacion":"40 × 2 × 3 × 4 = 960 litros. Unos baldes por semana pueden salvar a un árbol que dará sombra por décadas."}},{"slug":"plantas-3.s4.p10","orden":10,"grupo":"plantas-3.s4.p10","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"El árbol de tu vereda tiene una rama grande seca que cuelga sobre la calle. ¿Qué conviene hacer?","opciones":[{"id":"o1","texto":"Avisar al municipio para que la retiren"},{"id":"o2","texto":"Cortar vos todas las ramas del árbol"},{"id":"o3","texto":"Esperar a que se caiga sola"},{"id":"o4","texto":"Sacar el árbol entero"}]},"solucion":{"clave":["o1"],"explicacion":"Una rama peligrosa se retira de forma segura, sin castigar al árbol entero.","por_opcion":{"o3":"Una rama grande seca es un riesgo: conviene avisar pronto."}}},{"slug":"plantas-3.s4.p11","orden":11,"grupo":"plantas-3.s4.p11","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con su solución.","izquierda":[{"id":"a1","texto":"Árbol joven marchito en enero"},{"id":"a2","texto":"Rama seca sobre la calle"},{"id":"a3","texto":"Cazuela llena de basura"},{"id":"a4","texto":"Vereda sin árbol"}],"derecha":[{"id":"b1","texto":"Riego regular"},{"id":"b2","texto":"Aviso al municipio para retirarla"},{"id":"b3","texto":"Limpiarla y dejar suelo suelto"},{"id":"b4","texto":"Pedir una reposición"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Muchos problemas del arbolado se resuelven con cuidado y un buen reclamo."}},{"slug":"plantas-3.s4.p12","orden":12,"grupo":"plantas-3.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo de un grupo vecinal y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Regá los árboles jóvenes en verano."},{"id":"s2","texto":"Podá todo el árbol cada otoño para que no tenga tantas hojas."},{"id":"s3","texto":"Si ves una rama peligrosa, avisá al municipio."},{"id":"s4","texto":"El desmoche hace que el árbol sea más seguro."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Cuidar el arbolado es sobre todo no dañarlo.","por_opcion":{"s2":"Las podas excesivas debilitan al árbol.","s4":"Lo vuelve más débil y peligroso."}}},{"slug":"plantas-3.s4.p13","orden":13,"grupo":"plantas-3.s4.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un árbol joven necesita {{0}} los primeros años; cortar todas sus ramas dejando muñones es un {{1}}; y una buena poda es {{2}}.","banco":[{"id":"w1","texto":"riego"},{"id":"w2","texto":"desmoche"},{"id":"w3","texto":"mínima"},{"id":"w4","texto":"sombra"},{"id":"w5","texto":"injerto"},{"id":"w6","texto":"total"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas clave para cuidar el arbolado de la ciudad."}},{"slug":"plantas-3.s4.p14","orden":14,"grupo":"plantas-3.s4.p14","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá durante cuántos años conviene regar regularmente un árbol recién plantado.","min":0,"max":20,"paso":1,"unidad":"años","escala":"lineal"},"solucion":{"valor":3,"banda":"lineal","explicacion":"Unos dos o tres años, hasta que las raíces se establecen. Después, suele arreglarse solo con la lluvia."}}]},{"slug":"plantas-3.s5","orden":5,"tipo":"leccion","titulo_es":"Ciudades más verdes","bajada_es":"Árboles, techos verdes, jardines de lluvia, plazas cercanas y corredores: el verde como infraestructura.","minutos":11,"pasos":[{"slug":"plantas-3.s5.p1","orden":1,"grupo":"plantas-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una regla para medir el verde","cuerpo":["Especialistas en bosques urbanos propusieron una regla simple: cada persona debería poder ver al menos 3 árboles desde su casa, cada barrio debería tener al menos un 30 % de su superficie cubierta por copas de árboles, y cada persona debería vivir a no más de 300 metros de un parque o plaza. Se la conoce como la regla 3-30-300."],"destacado":{"valor":"3-30-300","texto":"3 árboles a la vista, 30 % de copas en el barrio y una plaza a menos de 300 metros."}},"solucion":{}},{"slug":"plantas-3.s5.p2","orden":2,"grupo":"plantas-3.s5.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada número de la regla 3-30-300 con su significado.","izquierda":[{"id":"a1","texto":"3"},{"id":"a2","texto":"30"},{"id":"a3","texto":"300"}],"derecha":[{"id":"b1","texto":"Árboles visibles desde cada casa"},{"id":"b2","texto":"Porcentaje del barrio cubierto por copas"},{"id":"b3","texto":"Metros máximos hasta un parque o plaza"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Una regla fácil de recordar para evaluar el verde de un barrio."}},{"slug":"plantas-3.s5.p3","orden":3,"grupo":"plantas-3.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio de 100 hectáreas tiene 12 hectáreas cubiertas por copas de árboles. ¿Qué porcentaje de cobertura tiene? ¿Cumple el 30 %?","unidad":"%","decimales":0},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"12 ÷ 100 × 100 = 12 %. No llega al 30 %: le falta verde."}},{"slug":"plantas-3.s5.p3.v2","orden":3,"grupo":"plantas-3.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio de 80 hectáreas tiene 20 hectáreas cubiertas por copas de árboles. ¿Qué porcentaje de cobertura tiene? ¿Cumple el 30 %?","unidad":"%","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"20 ÷ 80 × 100 = 25 %. No llega al 30 %: le falta verde."}},{"slug":"plantas-3.s5.p3.v3","orden":3,"grupo":"plantas-3.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio de 50 hectáreas tiene 8 hectáreas cubiertas por copas de árboles. ¿Qué porcentaje de cobertura tiene? ¿Cumple el 30 %?","unidad":"%","decimales":0},"solucion":{"valor":16,"tolerancia":0.5,"explicacion":"8 ÷ 50 × 100 = 16 %. No llega al 30 %: le falta verde."}},{"slug":"plantas-3.s5.p4","orden":4,"grupo":"plantas-3.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Más allá de los árboles","cuerpo":["Hay otras formas de sumar verde: techos verdes, con plantas sobre las cubiertas, que aíslan del calor y retienen lluvia; jardines de lluvia, canteros más bajos que reciben el agua de techos y veredas; muros verdes; y huertas comunitarias. Todas suman sombra, frescura, infiltración y biodiversidad."]},"solucion":{}},{"slug":"plantas-3.s5.p5","orden":5,"grupo":"plantas-3.s5.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta infraestructura verde ayuda sobre todo con el calor o con la lluvia?","grupos":[{"id":"g1","nombre":"Calor"},{"id":"g2","nombre":"Lluvia"}],"items":[{"id":"i1","texto":"Árboles en las veredas"},{"id":"i2","texto":"Jardín de lluvia en una esquina"},{"id":"i3","texto":"Techo pintado de blanco con plantas"},{"id":"i4","texto":"Pavimento permeable en un estacionamiento"},{"id":"i5","texto":"Muro verde en una fachada al sol"},{"id":"i6","texto":"Cantero corrido que recibe el agua de la vereda"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Muchas soluciones ayudan con las dos cosas a la vez."}},{"slug":"plantas-3.s5.p6","orden":6,"grupo":"plantas-3.s5.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un jardín de lluvia reduce anegamientos.","items":[{"id":"i1","texto":"Llueve fuerte en la ciudad"},{"id":"i2","texto":"El agua de techos y veredas se dirige a un cantero bajo"},{"id":"i3","texto":"El cantero con plantas y suelo suelto la retiene"},{"id":"i4","texto":"El agua se infiltra de a poco"},{"id":"i5","texto":"Llega menos agua de golpe a los desagües"},{"id":"i6","texto":"El jardín de lluvia envía el agua al desagüe más rápido"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una solución basada en la naturaleza que trabaja con el agua, como viste en la rama de Agua."}},{"slug":"plantas-3.s5.p7","orden":7,"grupo":"plantas-3.s5.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un techo verde puede ayudar a que una casa se caliente menos en verano.","razones":[{"id":"r1","texto":"Porque aíslan y refrescan con la transpiración"},{"id":"r2","texto":"Porque las plantas calientan los techos"},{"id":"r3","texto":"Porque los techos verdes no tienen plantas"}]},"solucion":{"valor":true,"explicacion":"Las plantas y la tierra aíslan y transpiran, y bajan la temperatura del techo y del interior. Además retienen parte de la lluvia.","clave":["r1"]}},{"slug":"plantas-3.s5.p8","orden":8,"grupo":"plantas-3.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Verde para todos","cuerpo":["El verde urbano suele estar distribuido de forma desigual: hay barrios con plazas y arbolado abundante y otros casi sin árboles. Plantar donde más falta, sumar plazas en barrios densos y cuidar el arbolado existente son formas de justicia ambiental: el derecho a la sombra y a la naturaleza cerca de casa."]},"solucion":{}},{"slug":"plantas-3.s5.p9","orden":9,"grupo":"plantas-3.s5.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una ciudad tiene presupuesto para plantar 1.000 árboles. ¿Dónde conviene priorizar?","opciones":[{"id":"o1","texto":"En los barrios más calurosos y con menos árboles"},{"id":"o2","texto":"En los barrios que ya tienen mucho arbolado"},{"id":"o3","texto":"Donde se vean mejor para la foto"},{"id":"o4","texto":"En la plaza principal, aunque ya esté llena"}]},"solucion":{"clave":["o1"],"explicacion":"Donde falta verde, cada árbol hace más diferencia en salud y temperatura.","por_opcion":{"o3":"El impacto en salud y calor es mayor donde falta verde."}}},{"slug":"plantas-3.s5.p10","orden":10,"grupo":"plantas-3.s5.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones suman verde a una ciudad? Marcá todas.","opciones":[{"id":"o1","texto":"Plantar árboles donde faltan"},{"id":"o2","texto":"Techos verdes en edificios públicos"},{"id":"o3","texto":"Jardines de lluvia en esquinas"},{"id":"o4","texto":"Nuevas plazas en barrios densos"},{"id":"o5","texto":"Asfaltar los canteros de las avenidas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Muchas herramientas que se combinan en un plan de verde urbano."}},{"slug":"plantas-3.s5.p11","orden":11,"grupo":"plantas-3.s5.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos barrios por su prioridad para recibir árboles, de más a menos.","items":[{"id":"i1","texto":"Barrio denso, caluroso y con 5 % de copas"},{"id":"i2","texto":"Barrio con 15 % de copas y una plaza lejos"},{"id":"i3","texto":"Barrio con 25 % de copas y plaza cerca"},{"id":"i4","texto":"Barrio con 40 % de copas y un parque"}],"extremos":["Más prioridad","Menos prioridad"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Priorizar donde más falta es eficaz y es justo.","valores":{"i1":"la mayor","i2":"alta","i3":"media","i4":"la menor"}}},{"slug":"plantas-3.s5.p12","orden":12,"grupo":"plantas-3.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan municipal y marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Plantaremos primero en los barrios con menos arbolado."},{"id":"s2","texto":"Reemplazaremos la plaza de tierra por una plaza seca de cemento para que sea más fácil de limpiar."},{"id":"s3","texto":"Haremos jardines de lluvia en las esquinas que se anegan."},{"id":"s4","texto":"Mediremos la cobertura de copas de cada barrio."}]},"solucion":{"clave":["s2"],"explicacion":"Un buen plan de verde urbano mide, prioriza y elige soluciones que trabajan con la naturaleza.","por_opcion":{"s2":"Una plaza seca se calienta mucho y pierde los beneficios del verde."}}},{"slug":"plantas-3.s5.p13","orden":13,"grupo":"plantas-3.s5.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La regla {{0}} propone árboles a la vista, copas en el barrio y una plaza cerca; los jardines de {{1}} ayudan a infiltrar agua; y priorizar donde falta verde es {{2}} ambiental.","banco":[{"id":"w1","texto":"3-30-300"},{"id":"w2","texto":"lluvia"},{"id":"w3","texto":"justicia"},{"id":"w4","texto":"1-10-100"},{"id":"w5","texto":"sol"},{"id":"w6","texto":"estética"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para diseñar ciudades más verdes y más justas."}},{"slug":"plantas-3.s5.p14","orden":14,"grupo":"plantas-3.s5.p14","tipo":"estimar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá a cuántos metros de distancia máxima debería tener cada persona una plaza o parque, según la regla 3-30-300.","min":50,"max":3000,"paso":50,"unidad":"metros","escala":"lineal"},"solucion":{"valor":300,"banda":"lineal","explicacion":"300 metros: unas tres cuadras, una distancia caminable en pocos minutos."}}]},{"slug":"plantas-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: verde urbano","bajada_es":"Isla de calor, servicios del arbolado, elección de especies, cuidados y ciudades verdes, mezclados.","minutos":8,"pasos":[{"slug":"plantas-3.s6.p1","orden":1,"grupo":"plantas-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Verde urbano». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"plantas-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la cuadra más caliente","bajada_es":"Una cuadra de un barrio denso es la más calurosa de la ciudad según un mapa satelital. Armá con los vecinos el plan para refrescarla.","minutos":10,"pasos":[{"slug":"plantas-3.s7.p1","orden":1,"grupo":"plantas-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La cuadra","cuerpo":["La cuadra tiene 100 metros de largo y veredas de 3 metros a cada lado, con cables de un solo lado. Hay 2 árboles en toda la cuadra. Las casas tienen techos de membrana negra. En una ola de calor, la superficie de la vereda al sol llegó a 58 °C y la temperatura nocturna no bajó de 29 °C.","El municipio ofrece plantar árboles nativos, y los vecinos pueden pintar techos. La esquina se anega con cada tormenta."]},"solucion":{}},{"slug":"plantas-3.s7.p2","orden":2,"grupo":"plantas-3.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se planta un árbol cada 8 metros en cada vereda, ¿cuántos árboles entran en las dos veredas de la cuadra? (100 ÷ 8, redondeado hacia abajo, por 2)","unidad":"árboles","decimales":0,"contexto":"Cuadra de 100 m; un árbol cada 8 m en cada una de las dos veredas."},"solucion":{"valor":24,"tolerancia":0.5,"explicacion":"100 ÷ 8 = 12,5, o sea 12 por vereda; × 2 = 24 árboles, contra los 2 que hay hoy."}},{"slug":"plantas-3.s7.p3","orden":3,"grupo":"plantas-3.s7.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tamaño de árbol conviene en cada vereda?","grupos":[{"id":"g1","nombre":"Porte chico o mediano"},{"id":"g2","nombre":"Porte mediano a grande"}],"items":[{"id":"i1","texto":"Vereda con cables"},{"id":"i2","texto":"Vereda sin cables"},{"id":"i3","texto":"Patio chico de una casa de la cuadra"},{"id":"i4","texto":"Plaza de la esquina"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Cada vereda tiene su tamaño de árbol según los cables y el espacio."}},{"slug":"plantas-3.s7.p4","orden":4,"grupo":"plantas-3.s7.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la sombra baja 20 °C la temperatura de la vereda, ¿qué temperatura tendría a la sombra la vereda que llegó a 58 °C?","unidad":"°C","decimales":0,"contexto":"Vereda al sol a 58 °C; la sombra la baja 20 °C."},"solucion":{"valor":38,"tolerancia":0.76,"explicacion":"58 − 20 = 38 °C: una diferencia enorme para quien camina o espera el colectivo."}},{"slug":"plantas-3.s7.p5","orden":5,"grupo":"plantas-3.s7.p5","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas por rapidez de efecto, de más rápida a más lenta.","items":[{"id":"i1","texto":"Pintar los techos de blanco"},{"id":"i2","texto":"Jardín de lluvia en la esquina"},{"id":"i3","texto":"Plantar 24 árboles nativos"},{"id":"i4","texto":"Árboles adultos con copas amplias"}],"extremos":["Más rápida","Más lenta"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo rápido alivia ya; los árboles son la inversión que más rinde a largo plazo.","valores":{"i1":"días","i2":"semanas","i3":"años hasta dar mucha sombra","i4":"una década o más"}}},{"slug":"plantas-3.s7.p6","orden":6,"grupo":"plantas-3.s7.p6","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería incluir el plan de la cuadra? Marcá todo.","opciones":[{"id":"o1","texto":"Árboles nativos del tamaño adecuado para cada vereda"},{"id":"o2","texto":"Cazuelas amplias o canteros corridos"},{"id":"o3","texto":"Techos claros"},{"id":"o4","texto":"Un jardín de lluvia en la esquina que se anega"},{"id":"o5","texto":"Asfaltar las cazuelas para que no junten basura"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Sombra, techos claros, suelo vivo y manejo del agua: todo lo de la unidad en una cuadra."}},{"slug":"plantas-3.s7.p7","orden":7,"grupo":"plantas-3.s7.p7","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué hace falta para que los 24 árboles lleguen a adultos?","opciones":[{"id":"o1","texto":"Riego regular los primeros años y cuidado vecinal"},{"id":"o2","texto":"Podarlos fuerte todos los años"},{"id":"o3","texto":"Nada: una vez plantados, crecen solos"},{"id":"o4","texto":"Plantarlos en cazuelas mínimas para no molestar"}]},"solucion":{"clave":["o1"],"explicacion":"Plantar es el comienzo; regar y cuidar los primeros años es lo que asegura la sombra futura.","por_opcion":{"o3":"Los primeros años son críticos: sin riego, muchos mueren."}}},{"slug":"plantas-3.s7.p8","orden":8,"grupo":"plantas-3.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Los vecinos escriben su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Pediremos 24 árboles nativos y cazuelas amplias."},{"id":"s2","texto":"Del lado de los cables plantaremos árboles de porte grande."},{"id":"s3","texto":"Organizaremos turnos de riego en verano."},{"id":"s4","texto":"Cuando crezcan, los desmocharemos para que no den tanta sombra."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan de cuadra combina elección correcta, cuidado y paciencia.","por_opcion":{"s2":"Del lado de los cables conviene porte chico o mediano.","s4":"El desmoche los debilita; y la sombra es justamente el objetivo."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"plantas-4","rama":"plantas","orden":4,"nivel":2,"titulo_es":"La huerta","bajada_es":"Un cantero, unas macetas o un rincón del patio alcanzan para empezar. Cómo elegir el lugar, cuidar el suelo, sembrar, asociar cultivos y guardar tus propias semillas.","objetivos_es":["Elegir y preparar un lugar para la huerta","Mantener un suelo vivo con compost y cobertura","Sembrar, trasplantar y regar según cada cultivo","Planificar asociaciones y rotaciones por familias de plantas","Cosechar, guardar semillas e intercambiarlas"],"repasa":["plantas-1","residuos-3","aire-suelo-2","alimentacion-4"],"requiere_tronco":2,"fuentes":["inta","fao-agroecologia","fao-suelos","ipbes-polinizadores"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"plantas-4.s1","orden":1,"tipo":"leccion","titulo_es":"Empezar una huerta","bajada_es":"Sol, agua y suelo: cómo elegir el lugar y qué hacer si no tenés patio.","minutos":9,"pasos":[{"slug":"plantas-4.s1.p1","orden":1,"grupo":"plantas-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que necesita una huerta","cuerpo":["La mayoría de las hortalizas necesita al menos unas 6 horas de sol directo por día, agua cerca para regar y un suelo suelto y rico en materia orgánica. Por eso, antes de sembrar, conviene observar el lugar durante un día: dónde da el sol, desde qué hora y hasta cuándo.","Algunas hojas, como la lechuga o la acelga, toleran algo de media sombra; los frutos, como el tomate o el zapallo, necesitan mucho sol."],"destacado":{"valor":"≈ 6 horas","texto":"de sol directo por día necesitan la mayoría de las hortalizas."}},"solucion":{}},{"slug":"plantas-4.s1.p2","orden":2,"grupo":"plantas-4.s1.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué cultivo conviene para cada lugar?","grupos":[{"id":"g1","nombre":"Pleno sol (6 horas o más)"},{"id":"g2","nombre":"Media sombra (3 a 5 horas)"}],"items":[{"id":"i1","texto":"Tomate"},{"id":"i2","texto":"Lechuga"},{"id":"i3","texto":"Zapallo"},{"id":"i4","texto":"Acelga"},{"id":"i5","texto":"Pimiento"},{"id":"i6","texto":"Perejil"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los frutos necesitan mucha energía del sol; las hojas se arreglan con menos."}},{"slug":"plantas-4.s1.p3","orden":3,"grupo":"plantas-4.s1.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tenés un patio donde el sol da solo dos horas por la mañana. ¿Qué conviene cultivar?","opciones":[{"id":"o1","texto":"Aromáticas de sombra y algunas hojas"},{"id":"o2","texto":"Tomates y zapallos grandes de verano"},{"id":"o3","texto":"Sandías y melones para el verano"},{"id":"o4","texto":"Choclos para una cosecha grande"}]},"solucion":{"clave":["o1"],"explicacion":"Con poco sol, conviene apostar a cultivos que lo toleran. Y buscar otro rincón más soleado para los frutos.","por_opcion":{"o3":"Necesitan muchísimo sol y calor."}}},{"slug":"plantas-4.s1.p4","orden":4,"grupo":"plantas-4.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Sin patio","cuerpo":["Sin patio también se puede: en macetas, cajones o bolsas de cultivo en balcones y terrazas soleadas. Las macetas tienen que tener buen drenaje y tamaño suficiente: un tomate necesita un recipiente grande, de al menos 20 a 30 litros; las aromáticas y las lechugas se arreglan con menos.","Los canteros elevados son una buena opción cuando el suelo es malo o está contaminado: se rellenan con tierra buena y compost, y son más cómodos para trabajar."]},"solucion":{}},{"slug":"plantas-4.s1.p5","orden":5,"grupo":"plantas-4.s1.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada cultivo con un recipiente adecuado.","izquierda":[{"id":"a1","texto":"Tomate"},{"id":"a2","texto":"Lechuga"},{"id":"a3","texto":"Albahaca"},{"id":"a4","texto":"Zapallo"}],"derecha":[{"id":"b1","texto":"Maceta grande de 20 a 30 litros o más"},{"id":"b2","texto":"Jardinera ancha y poco profunda"},{"id":"b3","texto":"Maceta chica o mediana"},{"id":"b4","texto":"Cantero amplio en el suelo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada cultivo tiene su espacio. Una maceta chica limita a una planta grande."}},{"slug":"plantas-4.s1.p6","orden":6,"grupo":"plantas-4.s1.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Cualquier maceta chica alcanza para un tomate, porque es una sola planta.","razones":[{"id":"r1","texto":"Porque necesita mucho espacio para raíces, agua y nutrientes"},{"id":"r2","texto":"Porque los tomates no tienen raíces"},{"id":"r3","texto":"Porque las macetas grandes enferman a los tomates"}]},"solucion":{"valor":false,"explicacion":"El tomate desarrolla muchas raíces y necesita mucha agua y nutrientes: en una maceta chica crece poco y da pocos frutos.","clave":["r1"]}},{"slug":"plantas-4.s1.p7","orden":7,"grupo":"plantas-4.s1.p7","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo elegir el lugar de la huerta.","items":[{"id":"i1","texto":"Observar durante un día dónde da el sol"},{"id":"i2","texto":"Elegir el lugar con más horas de sol directo"},{"id":"i3","texto":"Verificar que haya agua cerca para regar"},{"id":"i4","texto":"Revisar el suelo o preparar un cantero"},{"id":"i5","texto":"Decidir qué cultivar según el sol disponible"},{"id":"i6","texto":"Sembrar primero y ver dónde da el sol después"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Observar antes de hacer: el método de la ciencia aplicado a la huerta."}},{"slug":"plantas-4.s1.p8","orden":8,"grupo":"plantas-4.s1.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué necesita una huerta para funcionar bien? Marcá todo.","opciones":[{"id":"o1","texto":"Horas de sol directo"},{"id":"o2","texto":"Agua cerca para regar"},{"id":"o3","texto":"Suelo suelto y con materia orgánica"},{"id":"o4","texto":"Buen drenaje"},{"id":"o5","texto":"Sombra total todo el día"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Sol, agua, suelo y drenaje: las cuatro bases."}},{"slug":"plantas-4.s1.p9","orden":9,"grupo":"plantas-4.s1.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un rincón del patio, el sol directo llega a las 9 y se va a las 15. ¿Cuántas horas de sol directo recibe? ¿Alcanza para tomates?","unidad":"horas","decimales":0},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"15 − 9 = 6 horas. Alcanza para tomates y otros frutos."}},{"slug":"plantas-4.s1.p9.v2","orden":9,"grupo":"plantas-4.s1.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un rincón del patio, el sol directo llega a las 10 y se va a las 17. ¿Cuántas horas de sol directo recibe? ¿Alcanza para tomates?","unidad":"horas","decimales":0},"solucion":{"valor":7,"tolerancia":0.5,"explicacion":"17 − 10 = 7 horas. Alcanza para tomates y otros frutos."}},{"slug":"plantas-4.s1.p9.v3","orden":9,"grupo":"plantas-4.s1.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un rincón del patio, el sol directo llega a las 8 y se va a las 12. ¿Cuántas horas de sol directo recibe? ¿Alcanza para tomates?","unidad":"horas","decimales":0},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"12 − 8 = 4 horas. No alcanza para frutos exigentes: mejor hojas y aromáticas."}},{"slug":"plantas-4.s1.p10","orden":10,"grupo":"plantas-4.s1.p10","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos cultivos por cuánto sol necesitan, de más a menos.","items":[{"id":"i1","texto":"Sandía"},{"id":"i2","texto":"Tomate"},{"id":"i3","texto":"Lechuga"},{"id":"i4","texto":"Menta"}],"extremos":["Más sol","Menos sol"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Saber cuánto sol pide cada cultivo evita frustraciones.","valores":{"i1":"mucho sol y calor","i2":"pleno sol","i3":"tolera media sombra","i4":"se arregla con poca luz"}}},{"slug":"plantas-4.s1.p11","orden":11,"grupo":"plantas-4.s1.p11","tipo":"detectar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos para empezar y marcá los equivocados.","segmentos":[{"id":"s1","texto":"Observá dónde da el sol antes de armar la huerta."},{"id":"s2","texto":"Los tomates crecen igual de bien en un rincón sin sol."},{"id":"s3","texto":"Si el suelo es malo, podés hacer un cantero elevado."},{"id":"s4","texto":"Las macetas no necesitan agujeros si regás poco."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Empezar bien evita la mayoría de los problemas.","por_opcion":{"s2":"Necesitan unas 6 horas de sol directo o más.","s4":"Sin drenaje, el agua se acumula y las raíces se ahogan."}}},{"slug":"plantas-4.s1.p12","orden":12,"grupo":"plantas-4.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La mayoría de las hortalizas necesita unas {{0}} horas de sol; las macetas necesitan buen {{1}}; y si el suelo es malo conviene un cantero {{2}}.","banco":[{"id":"w1","texto":"6"},{"id":"w2","texto":"drenaje"},{"id":"w3","texto":"elevado"},{"id":"w4","texto":"2"},{"id":"w5","texto":"color"},{"id":"w6","texto":"hundido"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres bases para empezar una huerta en cualquier lugar."}}]},{"slug":"plantas-4.s2","orden":2,"tipo":"leccion","titulo_es":"El suelo de la huerta","bajada_es":"Compost, cobertura y no dar vuelta la tierra: cómo tener un suelo vivo y fértil.","minutos":11,"pasos":[{"slug":"plantas-4.s2.p1","orden":1,"grupo":"plantas-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Alimentar el suelo, no la planta","cuerpo":["En la huerta agroecológica se dice que hay que alimentar al suelo, no a la planta. Un suelo con materia orgánica y vida retiene agua, tiene nutrientes disponibles y sostiene raíces sanas, como viste en la rama de Aire y Suelo. La forma más simple de lograrlo es sumar compost cada temporada."]},"solucion":{}},{"slug":"plantas-4.s2.p2","orden":2,"grupo":"plantas-4.s2.p2","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el compost mejora la huerta.","items":[{"id":"i1","texto":"Se agrega compost a la superficie del cantero"},{"id":"i2","texto":"Las lombrices y microbios lo incorporan al suelo"},{"id":"i3","texto":"Aumenta la materia orgánica"},{"id":"i4","texto":"El suelo retiene más agua y nutrientes"},{"id":"i5","texto":"Las plantas crecen más sanas"},{"id":"i6","texto":"El compost reemplaza la necesidad de sol"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El compost de tu casa cierra el ciclo: de la cocina al suelo y del suelo a la cocina."}},{"slug":"plantas-4.s2.p3","orden":3,"grupo":"plantas-4.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cobertura: el suelo nunca desnudo","cuerpo":["Cubrir el suelo con una capa de hojas secas, paja o pasto seco —el mulch o acolchado— protege de la erosión, conserva la humedad, reduce las malezas, modera la temperatura y alimenta a la vida del suelo a medida que se descompone.","Un suelo desnudo, en cambio, se seca rápido, se endurece y pierde vida."]},"solucion":{}},{"slug":"plantas-4.s2.p4","orden":4,"grupo":"plantas-4.s2.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué beneficios tiene cubrir el suelo con mulch? Marcá todos.","opciones":[{"id":"o1","texto":"Conserva la humedad"},{"id":"o2","texto":"Reduce las malezas"},{"id":"o3","texto":"Protege de la erosión"},{"id":"o4","texto":"Alimenta la vida del suelo"},{"id":"o5","texto":"Evita que llegue el sol a las hojas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La cobertura cubre el suelo, no las plantas."}},{"slug":"plantas-4.s2.p5","orden":5,"grupo":"plantas-4.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un cantero necesita 20 litros de riego por día sin cobertura. Si el mulch reduce la evaporación y el riego necesario un 40 %, ¿cuántos litros por día hacen falta con mulch?","unidad":"litros","decimales":1},"solucion":{"valor":12,"tolerancia":0.24,"explicacion":"20 × 0,6 = 12 litros por día. Menos agua y menos trabajo con una capa de hojas secas."}},{"slug":"plantas-4.s2.p5.v2","orden":5,"grupo":"plantas-4.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un cantero necesita 30 litros de riego por día sin cobertura. Si el mulch reduce la evaporación y el riego necesario un 50 %, ¿cuántos litros por día hacen falta con mulch?","unidad":"litros","decimales":1},"solucion":{"valor":15,"tolerancia":0.3,"explicacion":"30 × 0,5 = 15 litros por día. Menos agua y menos trabajo con una capa de hojas secas."}},{"slug":"plantas-4.s2.p5.v3","orden":5,"grupo":"plantas-4.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un cantero necesita 15 litros de riego por día sin cobertura. Si el mulch reduce la evaporación y el riego necesario un 30 %, ¿cuántos litros por día hacen falta con mulch?","unidad":"litros","decimales":1},"solucion":{"valor":10.5,"tolerancia":0.21,"explicacion":"15 × 0,7 = 10,5 litros por día. Menos agua y menos trabajo con una capa de hojas secas."}},{"slug":"plantas-4.s2.p6","orden":6,"grupo":"plantas-4.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"No dar vuelta la tierra","cuerpo":["Dar vuelta la tierra con pala todos los años rompe la estructura del suelo, entierra la capa fértil de arriba y destruye las redes de hongos y las galerías de lombrices. En la huerta agroecológica se prefiere aflojar con una horquilla sin dar vuelta, y agregar compost por arriba."]},"solucion":{}},{"slug":"plantas-4.s2.p7","orden":7,"grupo":"plantas-4.s2.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Dar vuelta toda la tierra con pala cada año es la mejor forma de preparar la huerta.","razones":[{"id":"r1","texto":"Porque rompe la estructura y la vida del suelo"},{"id":"r2","texto":"Porque la pala agrega nutrientes"},{"id":"r3","texto":"Porque el suelo necesita estar desnudo"}]},"solucion":{"valor":false,"explicacion":"Rompe la estructura del suelo y la vida que hay en él. Es mejor aflojar sin dar vuelta y sumar compost por arriba.","clave":["r1"]}},{"slug":"plantas-4.s2.p8","orden":8,"grupo":"plantas-4.s2.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada práctica con su efecto sobre el suelo.","izquierda":[{"id":"a1","texto":"Agregar compost"},{"id":"a2","texto":"Cubrir con mulch"},{"id":"a3","texto":"Aflojar con horquilla"},{"id":"a4","texto":"Dejar el suelo desnudo"}],"derecha":[{"id":"b1","texto":"Suma materia orgánica y vida"},{"id":"b2","texto":"Conserva humedad y protege"},{"id":"b3","texto":"Airea sin romper la estructura"},{"id":"b4","texto":"Se seca, se endurece y pierde vida"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada práctica suma o resta vida al suelo."}},{"slug":"plantas-4.s2.p9","orden":9,"grupo":"plantas-4.s2.p9","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En verano el cantero se seca cada día y aparecen muchas malezas. ¿Qué conviene hacer primero?","opciones":[{"id":"o1","texto":"Cubrir el suelo con una capa de mulch"},{"id":"o2","texto":"Regar tres veces por día"},{"id":"o3","texto":"Dar vuelta toda la tierra con pala"},{"id":"o4","texto":"Dejar el suelo desnudo al sol para que se endurezca"}]},"solucion":{"clave":["o1"],"explicacion":"El mulch resuelve las dos cosas a la vez: conserva humedad y frena malezas.","por_opcion":{"o3":"Rompe el suelo y trae más semillas de malezas a la superficie."}}},{"slug":"plantas-4.s2.p10","orden":10,"grupo":"plantas-4.s2.p10","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta práctica cuida el suelo o lo daña?","grupos":[{"id":"g1","nombre":"Lo cuida"},{"id":"g2","nombre":"Lo daña"}],"items":[{"id":"i1","texto":"Compost cada temporada"},{"id":"i2","texto":"Pisar los canteros"},{"id":"i3","texto":"Cobertura de hojas secas"},{"id":"i4","texto":"Dejar el suelo desnudo"},{"id":"i5","texto":"Rotar cultivos"},{"id":"i6","texto":"Quemar los restos de la cosecha"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Un suelo vivo se construye con años de buenas prácticas."}},{"slug":"plantas-4.s2.p11","orden":11,"grupo":"plantas-4.s2.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas coberturas por cuánto tardan en descomponerse, de más rápido a más lento.","items":[{"id":"i1","texto":"Pasto recién cortado seco"},{"id":"i2","texto":"Hojas secas"},{"id":"i3","texto":"Paja"},{"id":"i4","texto":"Chips de madera"}],"extremos":["Más rápido","Más lento"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las coberturas que duran más protegen más tiempo; las que se descomponen rápido alimentan más rápido.","valores":{"i1":"semanas","i2":"meses","i3":"varios meses","i4":"uno o dos años"}}},{"slug":"plantas-4.s2.p12","orden":12,"grupo":"plantas-4.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Agregá compost al cantero cada temporada."},{"id":"s2","texto":"Quemá los restos de la cosecha para limpiar el cantero."},{"id":"s3","texto":"Cubrí el suelo con hojas secas."},{"id":"s4","texto":"Si ves lombrices, sacalas porque comen las raíces."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Cuidar el suelo es la base de cualquier huerta.","por_opcion":{"s2":"Se pierde materia orgánica: mejor compostarlos o dejarlos como cobertura.","s4":"Las lombrices mejoran el suelo; no comen raíces sanas."}}},{"slug":"plantas-4.s2.p13","orden":13,"grupo":"plantas-4.s2.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En la huerta conviene alimentar al {{0}}; cubrirlo con {{1}} conserva la humedad; y es mejor {{2}} la tierra que darla vuelta.","banco":[{"id":"w1","texto":"suelo"},{"id":"w2","texto":"mulch"},{"id":"w3","texto":"aflojar"},{"id":"w4","texto":"sol"},{"id":"w5","texto":"plástico"},{"id":"w6","texto":"quemar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para un suelo vivo en la huerta."}},{"slug":"plantas-4.s2.p14","orden":14,"grupo":"plantas-4.s2.p14","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos centímetros de espesor conviene que tenga la capa de mulch de hojas secas en un cantero.","min":1,"max":30,"paso":1,"unidad":"cm","escala":"lineal"},"solucion":{"valor":7,"banda":"lineal","explicacion":"Unos 5 a 10 cm: suficiente para conservar humedad y frenar malezas sin asfixiar el suelo."}}]},{"slug":"plantas-4.s3","orden":3,"tipo":"leccion","titulo_es":"Sembrar y trasplantar","bajada_es":"Semillas, almácigos, profundidad, calendario y riego: cómo arrancar cada cultivo.","minutos":11,"pasos":[{"slug":"plantas-4.s3.p1","orden":1,"grupo":"plantas-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Siembra directa o almácigo","cuerpo":["Algunos cultivos se siembran directamente en el lugar definitivo, como la zanahoria, el rabanito, la arveja o el zapallo. Otros conviene sembrarlos primero en almácigos —bandejas o macetitas— y trasplantarlos cuando tienen algunas hojas, como el tomate, la lechuga o el morrón.","La regla general para la profundidad: enterrar la semilla dos o tres veces su tamaño. Las semillas muy chicas, como las de lechuga, van casi en superficie."]},"solucion":{}},{"slug":"plantas-4.s3.p2","orden":2,"grupo":"plantas-4.s3.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Siembra directa o almácigo y trasplante?","grupos":[{"id":"g1","nombre":"Siembra directa"},{"id":"g2","nombre":"Almácigo y trasplante"}],"items":[{"id":"i1","texto":"Zanahoria"},{"id":"i2","texto":"Tomate"},{"id":"i3","texto":"Rabanito"},{"id":"i4","texto":"Lechuga"},{"id":"i5","texto":"Arveja"},{"id":"i6","texto":"Morrón"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las raíces que no toleran moverse, como la zanahoria, van directo. Las que se trasplantan bien, a almácigo."}},{"slug":"plantas-4.s3.p3","orden":3,"grupo":"plantas-4.s3.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una semilla mide 5 mm. Si se entierra a unas 2 a 3 veces su tamaño, ¿cuál es la profundidad máxima recomendada, en mm?","unidad":"mm","decimales":0},"solucion":{"valor":15,"tolerancia":0.5,"explicacion":"5 × 3 = 15 mm como máximo. Enterrarla demasiado le hace gastar su reserva antes de llegar a la luz."}},{"slug":"plantas-4.s3.p3.v2","orden":3,"grupo":"plantas-4.s3.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una semilla mide 10 mm. Si se entierra a unas 2 a 3 veces su tamaño, ¿cuál es la profundidad máxima recomendada, en mm?","unidad":"mm","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"10 × 3 = 30 mm como máximo. Enterrarla demasiado le hace gastar su reserva antes de llegar a la luz."}},{"slug":"plantas-4.s3.p3.v3","orden":3,"grupo":"plantas-4.s3.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una semilla mide 3 mm. Si se entierra a unas 2 a 3 veces su tamaño, ¿cuál es la profundidad máxima recomendada, en mm?","unidad":"mm","decimales":0},"solucion":{"valor":9,"tolerancia":0.5,"explicacion":"3 × 3 = 9 mm como máximo. Enterrarla demasiado le hace gastar su reserva antes de llegar a la luz."}},{"slug":"plantas-4.s3.p4","orden":4,"grupo":"plantas-4.s3.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Cuanto más profundo se entierra una semilla, mejor germina.","razones":[{"id":"r1","texto":"Porque puede gastar su reserva antes de llegar a la luz"},{"id":"r2","texto":"Porque las semillas necesitan oscuridad total para crecer"},{"id":"r3","texto":"Porque la profundidad no importa"}]},"solucion":{"valor":false,"explicacion":"Si queda muy profunda, gasta su reserva de alimento antes de llegar a la luz y puede no emerger. La regla es dos o tres veces su tamaño.","clave":["r1"]}},{"slug":"plantas-4.s3.p5","orden":5,"grupo":"plantas-4.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El calendario","cuerpo":["Cada cultivo tiene su época de siembra según la temperatura y la región. En la región pampeana, por ejemplo, el tomate, el zapallo y el choclo se siembran en primavera, cuando pasan las heladas; las habas, las arvejas, la acelga y la lechuga de invierno se siembran a fines del verano y en otoño. Los calendarios de siembra regionales, como los del INTA, ayudan a planificar."]},"solucion":{}},{"slug":"plantas-4.s3.p6","orden":6,"grupo":"plantas-4.s3.p6","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada cultivo con su época típica de siembra en la región pampeana.","izquierda":[{"id":"a1","texto":"Tomate"},{"id":"a2","texto":"Habas"},{"id":"a3","texto":"Zapallo"},{"id":"a4","texto":"Acelga de invierno"}],"derecha":[{"id":"b1","texto":"Primavera, después de las heladas"},{"id":"b2","texto":"Otoño"},{"id":"b3","texto":"Primavera"},{"id":"b4","texto":"Fines del verano y otoño"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Sembrar en la época justa es la mitad del éxito."}},{"slug":"plantas-4.s3.p7","orden":7,"grupo":"plantas-4.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Trasplantar y regar","cuerpo":["Al trasplantar conviene hacerlo a la tarde o en un día nublado, regar bien antes y después, y cuidar el pan de tierra para no romper las raíces. Los primeros días la planta puede decaer: es normal mientras se adapta.","En general, conviene regar temprano o al atardecer, en la base de la planta y no sobre las hojas, y hacerlo profundo y menos seguido en lugar de poquito todos los días, para que las raíces crezcan hacia abajo."]},"solucion":{}},{"slug":"plantas-4.s3.p8","orden":8,"grupo":"plantas-4.s3.p8","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para trasplantar un plantín de tomate.","items":[{"id":"i1","texto":"Regar el almácigo un rato antes"},{"id":"i2","texto":"Hacer un hoyo en el cantero, a la tarde"},{"id":"i3","texto":"Sacar el plantín con su pan de tierra"},{"id":"i4","texto":"Colocarlo en el hoyo y cubrir con tierra"},{"id":"i5","texto":"Regar bien la base"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cuidar las raíces y evitar el sol fuerte ayuda a que el plantín se adapte."}},{"slug":"plantas-4.s3.p9","orden":9,"grupo":"plantas-4.s3.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es la mejor forma de regar la huerta en verano?","opciones":[{"id":"o1","texto":"Profundo, en la base y temprano o al atardecer"},{"id":"o2","texto":"Un poquito cada hora, sobre las hojas, al mediodía"},{"id":"o3","texto":"Solo cuando las plantas estén completamente marchitas"},{"id":"o4","texto":"Inundar el cantero una vez por mes"}]},"solucion":{"clave":["o1"],"explicacion":"Riego profundo y en la base: raíces más hondas y menos hongos en las hojas.","por_opcion":{"o3":"Esperar a que se marchiten las estresa y baja la cosecha."}}},{"slug":"plantas-4.s3.p10","orden":10,"grupo":"plantas-4.s3.p10","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué conviene regar profundo y menos seguido.","items":[{"id":"i1","texto":"Se riega bien y profundo cada dos o tres días"},{"id":"i2","texto":"El agua llega a las capas más bajas del suelo"},{"id":"i3","texto":"Las raíces crecen hacia abajo buscándola"},{"id":"i4","texto":"La planta resiste mejor los días de calor"},{"id":"i5","texto":"Las raíces dejan de necesitar agua"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un riego superficial y diario acostumbra a las raíces a quedarse arriba, donde el suelo se seca rápido."}},{"slug":"plantas-4.s3.p11","orden":11,"grupo":"plantas-4.s3.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a que un trasplante salga bien? Marcá todo.","opciones":[{"id":"o1","texto":"Hacerlo a la tarde o en un día nublado"},{"id":"o2","texto":"Regar antes y después"},{"id":"o3","texto":"Cuidar el pan de tierra"},{"id":"o4","texto":"Proteger del sol fuerte los primeros días"},{"id":"o5","texto":"Sacudir las raíces para quitarles toda la tierra"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Menos estrés para las raíces, mejor arranque."}},{"slug":"plantas-4.s3.p12","orden":12,"grupo":"plantas-4.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este calendario casero y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Tomates: sembrar en almácigo a fines del invierno y trasplantar en primavera."},{"id":"s2","texto":"Zapallo: sembrar en pleno invierno, con heladas."},{"id":"s3","texto":"Habas: sembrar en otoño."},{"id":"s4","texto":"Zanahoria: sembrar en almácigo y trasplantar."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Cada cultivo tiene su forma de siembra y su época.","por_opcion":{"s2":"El zapallo es sensible al frío: se siembra en primavera.","s4":"La zanahoria se siembra directo: su raíz no tolera el trasplante."}}},{"slug":"plantas-4.s3.p13","orden":13,"grupo":"plantas-4.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una semilla se entierra a dos o tres veces su {{0}}; los tomates se siembran en {{1}}; y conviene regar en la {{2}} de la planta.","banco":[{"id":"w1","texto":"tamaño"},{"id":"w2","texto":"almácigo"},{"id":"w3","texto":"base"},{"id":"w4","texto":"peso"},{"id":"w5","texto":"maceta de vidrio"},{"id":"w6","texto":"hoja"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres reglas prácticas para sembrar y regar bien."}},{"slug":"plantas-4.s3.p14","orden":14,"grupo":"plantas-4.s3.p14","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos días suele tardar en germinar una semilla de lechuga con buena temperatura y humedad.","min":1,"max":60,"paso":1,"unidad":"días","escala":"lineal"},"solucion":{"valor":7,"banda":"lineal","explicacion":"Entre unos 4 y 10 días. Otras semillas, como el perejil, pueden tardar varias semanas."}}]},{"slug":"plantas-4.s4","orden":4,"tipo":"leccion","titulo_es":"Asociar y rotar","bajada_es":"Familias de plantas, cultivos que se ayudan, flores y aromáticas, y por qué no repetir lo mismo en el mismo lugar.","minutos":11,"pasos":[{"slug":"plantas-4.s4.p1","orden":1,"grupo":"plantas-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Familias de hortalizas","cuerpo":["Las hortalizas se agrupan en familias botánicas con necesidades y plagas parecidas. Las solanáceas: tomate, papa, morrón, berenjena. Las crucíferas: repollo, brócoli, coliflor, rúcula, rabanito. Las leguminosas: arveja, haba, poroto. Las cucurbitáceas: zapallo, zapallito, pepino, melón. Las liliáceas o aliáceas: cebolla, ajo, puerro."]},"solucion":{}},{"slug":"plantas-4.s4.p2","orden":2,"grupo":"plantas-4.s4.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿A qué familia pertenece cada hortaliza?","grupos":[{"id":"g1","nombre":"Solanáceas"},{"id":"g2","nombre":"Crucíferas"},{"id":"g3","nombre":"Leguminosas"},{"id":"g4","nombre":"Cucurbitáceas"}],"items":[{"id":"i1","texto":"Tomate"},{"id":"i2","texto":"Brócoli"},{"id":"i3","texto":"Arveja"},{"id":"i4","texto":"Zapallo"},{"id":"i5","texto":"Berenjena"},{"id":"i6","texto":"Rúcula"},{"id":"i7","texto":"Haba"},{"id":"i8","texto":"Pepino"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g4","i5":"g1","i6":"g2","i7":"g3","i8":"g4"},"explicacion":"Conocer las familias es la base para rotar bien."}},{"slug":"plantas-4.s4.p3","orden":3,"grupo":"plantas-4.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Rotar","cuerpo":["Rotar es no plantar la misma familia en el mismo lugar temporada tras temporada. Así se cortan los ciclos de plagas y enfermedades que atacan a esa familia y se equilibra el uso de nutrientes. Una rotación simple: después de una leguminosa (que deja nitrógeno) va una planta exigente de hojas o frutos; después, raíces; y después, otra vez leguminosas."]},"solucion":{}},{"slug":"plantas-4.s4.p4","orden":4,"grupo":"plantas-4.s4.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué rotar corta plagas.","items":[{"id":"i1","texto":"Una plaga de la papa pasa el invierno en el suelo"},{"id":"i2","texto":"En primavera, en ese lugar hay arvejas y no papas"},{"id":"i3","texto":"La plaga no encuentra a su planta"},{"id":"i4","texto":"Su población baja"},{"id":"i5","texto":"Al volver las papas años después, hay menos plaga"},{"id":"i6","texto":"Las arvejas atraen a la plaga de la papa"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La rotación es el control de plagas más barato que existe."}},{"slug":"plantas-4.s4.p5","orden":5,"grupo":"plantas-4.s4.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Plantar tomates en el mismo lugar todos los años aumenta el riesgo de enfermedades del tomate.","razones":[{"id":"r1","texto":"Porque se acumulan plagas y enfermedades de esa familia"},{"id":"r2","texto":"Porque los tomates agotan el sol del lugar"},{"id":"r3","texto":"Porque la rotación no tiene efectos"}]},"solucion":{"valor":true,"explicacion":"Las plagas y enfermedades de las solanáceas se acumulan en ese suelo. Rotar familias reduce el riesgo.","clave":["r1"]}},{"slug":"plantas-4.s4.p6","orden":6,"grupo":"plantas-4.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Asociaciones que se ayudan","cuerpo":["Algunas plantas se benefician creciendo juntas: la milpa de maíz, poroto y zapallo; la albahaca junto al tomate, que atrae polinizadores; la lechuga entre cultivos más altos que le dan algo de sombra; las cebollas y ajos intercalados, cuyo aroma confunde a algunas plagas. También ayudan las flores, como caléndulas y copetes, que atraen insectos benéficos."]},"solucion":{}},{"slug":"plantas-4.s4.p7","orden":7,"grupo":"plantas-4.s4.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada asociación con su beneficio.","izquierda":[{"id":"a1","texto":"Maíz, poroto y zapallo"},{"id":"a2","texto":"Tomate y albahaca"},{"id":"a3","texto":"Lechuga entre plantas altas"},{"id":"a4","texto":"Flores en los bordes"}],"derecha":[{"id":"b1","texto":"El maíz sostiene, el poroto aporta nitrógeno, el zapallo cubre"},{"id":"b2","texto":"La albahaca atrae polinizadores"},{"id":"b3","texto":"Recibe algo de sombra en verano"},{"id":"b4","texto":"Atraen insectos benéficos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"La diversidad en la huerta trabaja como un equipo."}},{"slug":"plantas-4.s4.p8","orden":8,"grupo":"plantas-4.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una huerta tiene 4 canteros y rota 4 grupos de cultivos, pasando cada grupo al cantero siguiente cada temporada. ¿Cuántas temporadas pasan hasta que un grupo vuelve al mismo cantero?","unidad":"temporadas","decimales":0},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"Con 4 canteros y 4 grupos, cada grupo vuelve a su cantero después de 4 temporadas. Más grupos en la rotación, más tiempo sin repetir."}},{"slug":"plantas-4.s4.p8.v2","orden":8,"grupo":"plantas-4.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una huerta tiene 3 canteros y rota 3 grupos de cultivos, pasando cada grupo al cantero siguiente cada temporada. ¿Cuántas temporadas pasan hasta que un grupo vuelve al mismo cantero?","unidad":"temporadas","decimales":0},"solucion":{"valor":3,"tolerancia":0.5,"explicacion":"Con 3 canteros y 3 grupos, cada grupo vuelve a su cantero después de 3 temporadas. Más grupos en la rotación, más tiempo sin repetir."}},{"slug":"plantas-4.s4.p8.v3","orden":8,"grupo":"plantas-4.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una huerta tiene 5 canteros y rota 5 grupos de cultivos, pasando cada grupo al cantero siguiente cada temporada. ¿Cuántas temporadas pasan hasta que un grupo vuelve al mismo cantero?","unidad":"temporadas","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"Con 5 canteros y 5 grupos, cada grupo vuelve a su cantero después de 5 temporadas. Más grupos en la rotación, más tiempo sin repetir."}},{"slug":"plantas-4.s4.p9","orden":9,"grupo":"plantas-4.s4.p9","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená una rotación simple en un cantero, empezando por las leguminosas.","items":[{"id":"i1","texto":"Leguminosas, como arvejas o habas"},{"id":"i2","texto":"Hojas exigentes, como acelga o repollo"},{"id":"i3","texto":"Frutos, como tomate o zapallo"},{"id":"i4","texto":"Raíces, como zanahoria o remolacha"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las leguminosas dejan nitrógeno para las exigentes; las raíces cierran el ciclo antes de volver a empezar."}},{"slug":"plantas-4.s4.p10","orden":10,"grupo":"plantas-4.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué aporta la diversidad a la huerta? Marcá todo.","opciones":[{"id":"o1","texto":"Menos plagas por familia"},{"id":"o2","texto":"Más polinizadores"},{"id":"o3","texto":"Mejor uso del espacio y del suelo"},{"id":"o4","texto":"Cosecha más variada"},{"id":"o5","texto":"Más necesidad de plaguicidas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Una huerta diversa es más estable y más productiva."}},{"slug":"plantas-4.s4.p11","orden":11,"grupo":"plantas-4.s4.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un cantero hubo papas el año pasado. ¿Qué conviene plantar este año?","opciones":[{"id":"o1","texto":"Arvejas o habas"},{"id":"o2","texto":"Tomates de otra variedad"},{"id":"o3","texto":"Berenjenas, que son distintas"},{"id":"o4","texto":"Más papas para aprovechar el suelo"}]},"solucion":{"clave":["o1"],"explicacion":"Tomate, berenjena y papa son solanáceas: después de papas conviene otra familia, como las leguminosas.","por_opcion":{"o3":"Son de la misma familia que la papa: conviene cambiar de familia."}}},{"slug":"plantas-4.s4.p12","orden":12,"grupo":"plantas-4.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan de huerta y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Este año pongo arvejas donde hubo tomates."},{"id":"s2","texto":"Pongo tomates donde hubo papas, porque son distintos."},{"id":"s3","texto":"Siembro caléndulas en los bordes."},{"id":"s4","texto":"Planto toda la huerta de lechuga para que sea más fácil."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Rotar por familias y diversificar: dos reglas de oro.","por_opcion":{"s2":"Son de la misma familia: las solanáceas.","s4":"Un monocultivo concentra plagas y reduce la diversidad."}}},{"slug":"plantas-4.s4.p13","orden":13,"grupo":"plantas-4.s4.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"No repetir la misma familia en el mismo lugar es {{0}}; el tomate y la papa son {{1}}; y las {{2}} dejan nitrógeno en el suelo.","banco":[{"id":"w1","texto":"rotar"},{"id":"w2","texto":"solanáceas"},{"id":"w3","texto":"leguminosas"},{"id":"w4","texto":"podar"},{"id":"w5","texto":"crucíferas"},{"id":"w6","texto":"aromáticas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las reglas de asociar y rotar, en una línea."}},{"slug":"plantas-4.s4.p14","orden":14,"grupo":"plantas-4.s4.p14","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas huertas de menor a mayor diversidad.","items":[{"id":"i1","texto":"Un solo cantero de lechuga"},{"id":"i2","texto":"Dos cultivos de la misma familia"},{"id":"i3","texto":"Cuatro familias rotando"},{"id":"i4","texto":"Cuatro familias, aromáticas y flores en los bordes"}],"extremos":["Menor","Mayor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Más diversidad, más estabilidad y menos plagas.","valores":{"i1":"mínima","i2":"baja","i3":"media","i4":"alta"}}}]},{"slug":"plantas-4.s5","orden":5,"tipo":"leccion","titulo_es":"Cosechar, guardar semillas y compartir","bajada_es":"Cuándo cosechar, cómo guardar semillas propias y por qué los intercambios cuidan la diversidad.","minutos":11,"pasos":[{"slug":"plantas-4.s5.p1","orden":1,"grupo":"plantas-4.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cosechar en su punto","cuerpo":["Cada cultivo tiene su punto de cosecha: las hojas se cosechan de a poco, sacando las externas para que la planta siga produciendo; los frutos, cuando alcanzan su color; las raíces, cuando llegan al tamaño esperado. Cosechar seguido estimula a muchas plantas, como el zapallito o las chauchas, a seguir dando."]},"solucion":{}},{"slug":"plantas-4.s5.p2","orden":2,"grupo":"plantas-4.s5.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cómo conviene cosechar la acelga para que siga produciendo?","opciones":[{"id":"o1","texto":"Sacando las hojas externas de a poco"},{"id":"o2","texto":"Arrancando la planta entera"},{"id":"o3","texto":"Cortando todas las hojas al ras de una sola vez"},{"id":"o4","texto":"Esperando a que florezca"}]},"solucion":{"clave":["o1"],"explicacion":"Cosechar de afuera hacia adentro permite comer acelga durante meses.","por_opcion":{"o3":"La planta se debilita; mejor cosechar las externas y dejar crecer el centro."}}},{"slug":"plantas-4.s5.p3","orden":3,"grupo":"plantas-4.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Guardar semillas","cuerpo":["Muchas semillas se pueden guardar de una temporada a otra: se dejan madurar algunos frutos o plantas hasta el final, se sacan las semillas, se secan bien a la sombra y se guardan en frascos o sobres en un lugar fresco y seco, con el nombre y la fecha.","Las variedades de polinización abierta dan hijos parecidos a los padres; las semillas de híbridos comerciales, en cambio, suelen dar plantas distintas y menos predecibles. Por eso conviene guardar semillas de variedades de polinización abierta."]},"solucion":{}},{"slug":"plantas-4.s5.p4","orden":4,"grupo":"plantas-4.s5.p4","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para guardar semillas de tomate.","items":[{"id":"i1","texto":"Elegir los mejores frutos de plantas sanas"},{"id":"i2","texto":"Dejarlos madurar bien"},{"id":"i3","texto":"Sacar las semillas y lavarlas"},{"id":"i4","texto":"Secarlas a la sombra"},{"id":"i5","texto":"Guardarlas en un frasco rotulado en un lugar fresco y seco"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Elegir lo mejor, secar bien y rotular: así se guarda una semilla."}},{"slug":"plantas-4.s5.p5","orden":5,"grupo":"plantas-4.s5.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las semillas de un tomate híbrido comercial dan siempre plantas iguales a la planta madre.","razones":[{"id":"r1","texto":"Porque los híbridos no mantienen sus características en la descendencia"},{"id":"r2","texto":"Porque los híbridos no tienen semillas"},{"id":"r3","texto":"Porque todas las semillas son iguales"}]},"solucion":{"valor":false,"explicacion":"Las semillas de híbridos suelen dar plantas distintas y poco predecibles. Para guardar semilla conviene usar variedades de polinización abierta.","clave":["r1"]}},{"slug":"plantas-4.s5.p6","orden":6,"grupo":"plantas-4.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Intercambiar y cuidar la diversidad","cuerpo":["Las ferias de intercambio de semillas y las casas de semillas comunitarias permiten que circulen variedades locales, adaptadas a cada región y a sus gustos. Esa diversidad es un tesoro: variedades de maíz, poroto, zapallo o papa que las comunidades seleccionaron durante generaciones, y que pueden ser clave frente a nuevas plagas o climas.","En Argentina, programas públicos y organizaciones distribuyen semillas y acompañan huertas familiares, escolares y comunitarias desde hace décadas."]},"solucion":{}},{"slug":"plantas-4.s5.p7","orden":7,"grupo":"plantas-4.s5.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Por qué es valioso intercambiar semillas locales? Marcá todo.","opciones":[{"id":"o1","texto":"Mantienen variedades adaptadas a la región"},{"id":"o2","texto":"Conservan diversidad genética"},{"id":"o3","texto":"Fortalecen el vínculo entre quienes cultivan"},{"id":"o4","texto":"Reducen la dependencia de comprar semillas cada año"},{"id":"o5","texto":"Hacen que todas las huertas tengan la misma variedad"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La diversidad de semillas es un seguro, como viste en la rama de Animales con la diversidad genética."}},{"slug":"plantas-4.s5.p8","orden":8,"grupo":"plantas-4.s5.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Polinización abierta"},{"id":"a2","texto":"Híbrido comercial"},{"id":"a3","texto":"Casa de semillas"},{"id":"a4","texto":"Variedad local"}],"derecha":[{"id":"b1","texto":"Variedad cuyas semillas dan plantas parecidas a los padres"},{"id":"b2","texto":"Cruza cuyas semillas dan plantas poco predecibles"},{"id":"b3","texto":"Espacio comunitario para guardar e intercambiar semillas"},{"id":"b4","texto":"Semilla seleccionada durante años en una región"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro conceptos para entender el mundo de las semillas."}},{"slug":"plantas-4.s5.p9","orden":9,"grupo":"plantas-4.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"De cada tomate maduro se sacan unas 150 semillas. Si guardás semillas de 3 tomates, ¿cuántas semillas obtenés?","unidad":"semillas","decimales":0},"solucion":{"valor":450,"tolerancia":9,"explicacion":"3 × 150 = 450 semillas: muchas más de las que necesita una huerta familiar. El resto se puede intercambiar."}},{"slug":"plantas-4.s5.p9.v2","orden":9,"grupo":"plantas-4.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"De cada tomate maduro se sacan unas 120 semillas. Si guardás semillas de 5 tomates, ¿cuántas semillas obtenés?","unidad":"semillas","decimales":0},"solucion":{"valor":600,"tolerancia":12,"explicacion":"5 × 120 = 600 semillas: muchas más de las que necesita una huerta familiar. El resto se puede intercambiar."}},{"slug":"plantas-4.s5.p9.v3","orden":9,"grupo":"plantas-4.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"De cada tomate maduro se sacan unas 200 semillas. Si guardás semillas de 2 tomates, ¿cuántas semillas obtenés?","unidad":"semillas","decimales":0},"solucion":{"valor":400,"tolerancia":8,"explicacion":"2 × 200 = 400 semillas: muchas más de las que necesita una huerta familiar. El resto se puede intercambiar."}},{"slug":"plantas-4.s5.p10","orden":10,"grupo":"plantas-4.s5.p10","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una variedad local se conserva.","items":[{"id":"i1","texto":"Una familia cultiva un zapallo local desde hace años"},{"id":"i2","texto":"Guarda las semillas de los mejores frutos"},{"id":"i3","texto":"Las lleva a una feria de intercambio"},{"id":"i4","texto":"Otras familias las cultivan y también las guardan"},{"id":"i5","texto":"La variedad sigue viva y se adapta"},{"id":"i6","texto":"La variedad se conserva sola sin que nadie la siembre"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Las variedades locales se conservan usándolas. Una semilla guardada en un cajón para siempre se pierde."}},{"slug":"plantas-4.s5.p11","orden":11,"grupo":"plantas-4.s5.p11","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta práctica ayuda a conservar la diversidad de semillas?","grupos":[{"id":"g1","nombre":"Ayuda"},{"id":"g2","nombre":"No ayuda"}],"items":[{"id":"i1","texto":"Guardar semillas de variedades locales"},{"id":"i2","texto":"Guardar semillas húmedas en una bolsa cerrada"},{"id":"i3","texto":"Participar de ferias de intercambio"},{"id":"i4","texto":"Plantar siempre una sola variedad comprada"},{"id":"i5","texto":"Rotular las semillas con nombre y fecha"},{"id":"i6","texto":"Tirar las semillas de los mejores frutos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Guardar bien, rotular y compartir mantienen viva la diversidad."}},{"slug":"plantas-4.s5.p12","orden":12,"grupo":"plantas-4.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo de una feria y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Guardá las semillas bien secas, en frascos rotulados."},{"id":"s2","texto":"Guardá las semillas húmedas para que no se sequen."},{"id":"s3","texto":"Elegí semillas de plantas sanas y fuertes."},{"id":"s4","texto":"Las semillas de híbridos comerciales son las mejores para guardar."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Guardar semillas es fácil si se respetan algunas reglas.","por_opcion":{"s2":"Húmedas se pudren o germinan antes de tiempo.","s4":"Conviene guardar variedades de polinización abierta."}}},{"slug":"plantas-4.s5.p13","orden":13,"grupo":"plantas-4.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para guardar semillas conviene usar variedades de polinización {{0}}; hay que secarlas bien y guardarlas {{1}}; y las ferias de {{2}} cuidan la diversidad.","banco":[{"id":"w1","texto":"abierta"},{"id":"w2","texto":"rotuladas"},{"id":"w3","texto":"intercambio"},{"id":"w4","texto":"cerrada"},{"id":"w5","texto":"húmedas"},{"id":"w6","texto":"venta"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para guardar y compartir semillas."}}]},{"slug":"plantas-4.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: la huerta","bajada_es":"Lugar, suelo, siembra, asociaciones y semillas, mezclados.","minutos":8,"pasos":[{"slug":"plantas-4.s6.p1","orden":1,"grupo":"plantas-4.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «La huerta». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"plantas-4.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la huerta de la escuela","bajada_es":"Una escuela de la región pampeana arma su huerta en marzo. Con los datos, planificá los canteros y el año.","minutos":10,"pasos":[{"slug":"plantas-4.s7.p1","orden":1,"grupo":"plantas-4.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La escuela","cuerpo":["La escuela tiene un patio donde un sector recibe sol de 9 a 17 en verano y otro solo hasta las 12. Hay una canilla cerca. El suelo del patio está compactado y lleno de escombros. Quieren armar 4 canteros elevados de 1 × 3 metros y empezar en marzo.","La cocina del comedor genera restos de verduras, y en otoño caen muchas hojas de los árboles."]},"solucion":{}},{"slug":"plantas-4.s7.p2","orden":2,"grupo":"plantas-4.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas horas de sol recibe en verano el sector más soleado?","unidad":"horas","decimales":0,"contexto":"Sol de 9 a 17 en el sector más soleado."},"solucion":{"valor":8,"tolerancia":0.5,"explicacion":"De 9 a 17 son 8 horas: suficiente para frutos como el tomate en primavera y verano."}},{"slug":"plantas-4.s7.p3","orden":3,"grupo":"plantas-4.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos metros cuadrados de cultivo suman los 4 canteros de 1 × 3 m?","unidad":"m²","decimales":0,"contexto":"4 canteros de 1 × 3 metros."},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"4 × (1 × 3) = 12 m² de canteros: espacio para varias familias de cultivos."}},{"slug":"plantas-4.s7.p4","orden":4,"grupo":"plantas-4.s7.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Como el suelo está compactado y con escombros, ¿qué conviene?","opciones":[{"id":"o1","texto":"Canteros elevados con tierra y compost"},{"id":"o2","texto":"Sembrar directo sobre el suelo compactado"},{"id":"o3","texto":"Esperar a que el suelo se arregle solo"},{"id":"o4","texto":"Sembrar en el sector sin sol"}]},"solucion":{"clave":["o1"],"explicacion":"El cantero elevado resuelve el problema del suelo desde el primer día.","por_opcion":{"o3":"Un suelo con escombros no se recupera solo en poco tiempo."}}},{"slug":"plantas-4.s7.p5","orden":5,"grupo":"plantas-4.s7.p5","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué conviene sembrar en marzo en la región pampeana?","grupos":[{"id":"g1","nombre":"Conviene en marzo"},{"id":"g2","nombre":"Conviene esperar a la primavera"}],"items":[{"id":"i1","texto":"Habas"},{"id":"i2","texto":"Tomate"},{"id":"i3","texto":"Arvejas"},{"id":"i4","texto":"Zapallo"},{"id":"i5","texto":"Acelga"},{"id":"i6","texto":"Lechuga de invierno"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g1"},"explicacion":"Marzo es tiempo de cultivos de otoño-invierno. Los de verano esperan a que pasen las heladas."}},{"slug":"plantas-4.s7.p6","orden":6,"grupo":"plantas-4.s7.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué recursos de la escuela sirven para la huerta? Marcá todos.","opciones":[{"id":"o1","texto":"Restos de verduras del comedor para compostar"},{"id":"o2","texto":"Hojas secas de otoño para cobertura"},{"id":"o3","texto":"La canilla cercana"},{"id":"o4","texto":"El sector con sol de 9 a 17"},{"id":"o5","texto":"Los escombros del patio como relleno de los canteros"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La escuela ya tiene casi todo: compost, cobertura, agua y sol."}},{"slug":"plantas-4.s7.p7","orden":7,"grupo":"plantas-4.s7.p7","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el plan de la huerta escolar.","items":[{"id":"i1","texto":"Armar una compostera con los restos del comedor"},{"id":"i2","texto":"Construir los canteros elevados en el sector soleado"},{"id":"i3","texto":"Rellenarlos con tierra y compost"},{"id":"i4","texto":"Sembrar habas, arvejas y hojas de otoño"},{"id":"i5","texto":"Cubrir con hojas secas y organizar turnos de riego"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Suelo primero, siembra de estación y cuidado compartido."}},{"slug":"plantas-4.s7.p8","orden":8,"grupo":"plantas-4.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La escuela escribe su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Los canteros van en el sector con sol de 9 a 17."},{"id":"s2","texto":"En marzo sembraremos tomates y zapallos para cosechar en invierno."},{"id":"s3","texto":"Usaremos las hojas del otoño como cobertura."},{"id":"s4","texto":"Rellenaremos los canteros con los escombros del patio."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan combina lugar, estación, suelo y cuidado.","por_opcion":{"s2":"Son cultivos de verano: se siembran en primavera, después de las heladas.","s4":"Hace falta tierra buena y compost: los escombros no sirven."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"plantas-5","rama":"plantas","orden":5,"nivel":3,"titulo_es":"Bosques nativos","bajada_es":"Selva misionera, yungas, monte chaqueño, espinal y bosque andino: lo que hacen los bosques, cómo los protege la ley, por qué se queman y cómo usarlos sin destruirlos.","objetivos_es":["Reconocer las grandes regiones forestales de Argentina y sus rasgos","Explicar los servicios que brindan los bosques nativos","Analizar el ordenamiento territorial, el fondo y los resultados de la Ley de Bosques","Explicar las causas de los incendios forestales y las herramientas para prevenirlos","Distinguir el uso sostenible del bosque del desmonte encubierto"],"repasa":["plantas-2","animales-4","alimentacion-5","aire-suelo-2"],"requiere_tronco":3,"fuentes":["ley-bosques-26331","chequeado-fondo-bosques","farn-bosques-fondo","global-forest-watch","snmf-origen","chequeado-incendios","ley-27604-fuego","nasa-firms","parques-nacionales"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"plantas-5.s1","orden":1,"tipo":"leccion","titulo_es":"Los bosques de Argentina","bajada_es":"Seis grandes regiones forestales, muy distintas entre sí, y lo que las hace únicas.","minutos":11,"pasos":[{"slug":"plantas-5.s1.p1","orden":1,"grupo":"plantas-5.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Seis regiones","cuerpo":["Argentina tiene bosques muy distintos. La selva paranaense, en Misiones, es parte del Bosque Atlántico, uno de los más biodiversos del planeta. Las yungas, en las laderas del noroeste, son selvas de montaña con nubes y lluvias abundantes. El parque chaqueño es la región forestal más extensa del país, con quebrachos, algarrobos y palos santos. El espinal forma un arco de algarrobos, caldenes y ñandubays alrededor de la llanura pampeana. El monte es un arbustal de zonas secas del oeste. Y el bosque andino patagónico tiene lengas, coihues, cipreses y alerces a lo largo de la cordillera."]},"solucion":{}},{"slug":"plantas-5.s1.p2","orden":2,"grupo":"plantas-5.s1.p2","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada región forestal con un árbol característico.","izquierda":[{"id":"a1","texto":"Parque chaqueño"},{"id":"a2","texto":"Bosque andino patagónico"},{"id":"a3","texto":"Espinal"},{"id":"a4","texto":"Yungas"},{"id":"a5","texto":"Selva paranaense"}],"derecha":[{"id":"b1","texto":"Quebracho colorado"},{"id":"b2","texto":"Lenga"},{"id":"b3","texto":"Caldén"},{"id":"b4","texto":"Cedro salteño"},{"id":"b5","texto":"Palo rosa"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Cada región tiene especies propias: por eso perder una región es perder algo irreemplazable."}},{"slug":"plantas-5.s1.p3","orden":3,"grupo":"plantas-5.s1.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿En qué región forestal está cada rasgo?","grupos":[{"id":"g1","nombre":"Selva paranaense"},{"id":"g2","nombre":"Yungas"},{"id":"g3","nombre":"Bosque andino patagónico"}],"items":[{"id":"i1","texto":"Parte del Bosque Atlántico, muy biodiverso"},{"id":"i2","texto":"Selva de montaña con nubes"},{"id":"i3","texto":"Bosques de lenga y coihue"},{"id":"i4","texto":"Selva subtropical de Misiones"},{"id":"i5","texto":"Laderas del noroeste"},{"id":"i6","texto":"Alerces milenarios"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada bosque responde a su clima y su relieve."}},{"slug":"plantas-5.s1.p4","orden":4,"grupo":"plantas-5.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El más extenso y el más amenazado","cuerpo":["El parque chaqueño, que se extiende por Santiago del Estero, Chaco, Formosa, Salta y otras provincias, es la región forestal más extensa de Argentina. También es la que más bosque perdió en las últimas décadas: la mayor parte del desmonte del país ocurrió allí, para ampliar la agricultura y la ganadería. En su interior viven comunidades indígenas y criollas que dependen del bosque para vivir."]},"solucion":{}},{"slug":"plantas-5.s1.p5","orden":5,"grupo":"plantas-5.s1.p5","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué región forestal de Argentina perdió más bosque en las últimas décadas?","opciones":[{"id":"o1","texto":"El parque chaqueño"},{"id":"o2","texto":"El bosque andino patagónico"},{"id":"o3","texto":"La selva paranaense, porque es la más extensa"},{"id":"o4","texto":"El monte de las zonas secas"}]},"solucion":{"clave":["o1"],"explicacion":"La expansión agropecuaria concentró el desmonte en el Chaco.","por_opcion":{"o3":"La más extensa es la chaqueña, y es la que más perdió."}}},{"slug":"plantas-5.s1.p6","orden":6,"grupo":"plantas-5.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Árboles que viven siglos","cuerpo":["Algunos árboles argentinos viven muchísimo. Los alerces de la cordillera patagónica pueden superar los 2.000 años: el Parque Nacional Los Alerces protege algunos de los más antiguos. Un quebracho colorado puede tardar más de un siglo en alcanzar un tronco grande. Por eso, un bosque maduro no se reemplaza plantando árboles: su estructura, su suelo y sus especies llevan siglos en formarse."]},"solucion":{}},{"slug":"plantas-5.s1.p7","orden":7,"grupo":"plantas-5.s1.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un bosque nativo maduro se puede reemplazar en pocos años plantando árboles nuevos.","razones":[{"id":"r1","texto":"Porque su estructura y su red de especies llevan siglos"},{"id":"r2","texto":"Porque los bosques no tienen árboles viejos"},{"id":"r3","texto":"Porque plantar árboles no sirve para nada"}]},"solucion":{"valor":false,"explicacion":"Un bosque maduro tiene árboles de siglos, un suelo desarrollado y una red de especies que no se reconstruye en pocos años. Plantar ayuda, pero no reemplaza lo perdido.","clave":["r1"]}},{"slug":"plantas-5.s1.p8","orden":8,"grupo":"plantas-5.s1.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un alerce tiene 2.600 años. ¿Cuántas veces más vivió que una persona de 80 años? Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"Alerce de 2600 años; persona de 80 años."},"solucion":{"valor":32.5,"tolerancia":0.1,"explicacion":"2.600 ÷ 80 ≈ 32,5 vidas humanas. Un árbol así no se reemplaza plantando otro."}},{"slug":"plantas-5.s1.p8.v2","orden":8,"grupo":"plantas-5.s1.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un alerce tiene 1.500 años. ¿Cuántas veces más vivió que una persona de 75 años? Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"Alerce de 1500 años; persona de 75 años."},"solucion":{"valor":20,"tolerancia":0.1,"explicacion":"1.500 ÷ 75 ≈ 20 vidas humanas. Un árbol así no se reemplaza plantando otro."}},{"slug":"plantas-5.s1.p8.v3","orden":8,"grupo":"plantas-5.s1.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un alerce tiene 800 años. ¿Cuántas veces más vivió que una persona de 80 años? Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"Alerce de 800 años; persona de 80 años."},"solucion":{"valor":10,"tolerancia":0.1,"explicacion":"800 ÷ 80 ≈ 10 vidas humanas. Un árbol así no se reemplaza plantando otro."}},{"slug":"plantas-5.s1.p9","orden":9,"grupo":"plantas-5.s1.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estos bosques de norte a sur.","items":[{"id":"i1","texto":"Yungas de Jujuy"},{"id":"i2","texto":"Espinal del norte de Córdoba"},{"id":"i3","texto":"Caldenal de La Pampa"},{"id":"i4","texto":"Bosque andino de Tierra del Fuego"}],"extremos":["Más al norte","Más al sur"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"De las selvas de montaña de la frontera norte a los bosques fríos del extremo sur."}},{"slug":"plantas-5.s1.p10","orden":10,"grupo":"plantas-5.s1.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué árboles son nativos de Argentina? Marcá todos.","opciones":[{"id":"o1","texto":"Quebracho colorado"},{"id":"o2","texto":"Algarrobo"},{"id":"o3","texto":"Lenga"},{"id":"o4","texto":"Palo borracho"},{"id":"o5","texto":"Eucalipto"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El eucalipto es originario de Australia: se planta mucho, pero no es nativo."}},{"slug":"plantas-5.s1.p11","orden":11,"grupo":"plantas-5.s1.p11","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos años pueden superar algunos alerces de la cordillera patagónica.","min":50,"max":100000,"paso":1,"unidad":"años","escala":"log"},"solucion":{"valor":2000,"banda":"log","explicacion":"Más de 2.000 años: están entre los seres vivos más longevos del planeta."}},{"slug":"plantas-5.s1.p12","orden":12,"grupo":"plantas-5.s1.p12","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El palo rosa es un árbol de la selva paranaense.","razones":[{"id":"r1","texto":"Porque es un árbol característico de la selva misionera"},{"id":"r2","texto":"Porque crece solo en la estepa patagónica"},{"id":"r3","texto":"Porque es una especie exótica de Australia"}]},"solucion":{"valor":true,"explicacion":"Es uno de los grandes árboles de la selva misionera, muy explotado por su madera y hoy protegido.","clave":["r1"]}},{"slug":"plantas-5.s1.p13","orden":13,"grupo":"plantas-5.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La selva paranaense es parte del Bosque Atlántico."},{"id":"s2","texto":"El parque chaqueño es la región forestal más chica del país."},{"id":"s3","texto":"Algunos alerces patagónicos superan los 2.000 años."},{"id":"s4","texto":"Las yungas son bosques de la estepa patagónica."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer los bosques del país es el primer paso para defenderlos.","por_opcion":{"s2":"Es la más extensa, y también la que más bosque perdió.","s4":"Son selvas de montaña del noroeste."}}},{"slug":"plantas-5.s1.p14","orden":14,"grupo":"plantas-5.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La región forestal más extensa del país es el parque {{0}}; las selvas de montaña del noroeste son las {{1}}; y el árbol más longevo de la cordillera es el {{2}}.","banco":[{"id":"w1","texto":"chaqueño"},{"id":"w2","texto":"yungas"},{"id":"w3","texto":"alerce"},{"id":"w4","texto":"pampeano"},{"id":"w5","texto":"marismas"},{"id":"w6","texto":"eucalipto"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos clave de los bosques argentinos."}}]},{"slug":"plantas-5.s2","orden":2,"tipo":"leccion","titulo_es":"Lo que hacen los bosques","bajada_es":"Agua, suelo, clima, biodiversidad, alimentos y culturas: los servicios de los bosques nativos.","minutos":10,"pasos":[{"slug":"plantas-5.s2.p1","orden":1,"grupo":"plantas-5.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Servicios ecosistémicos","cuerpo":["Los bosques nativos prestan servicios de los que dependen muchas personas, aunque no siempre se vean. Regulan el agua: las yungas, por ejemplo, retienen las lluvias en sus laderas y alimentan ríos que abastecen ciudades y riegos del noroeste. Protegen el suelo de la erosión. Guardan carbono en sus troncos, raíces y suelos. Albergan gran parte de la biodiversidad del país. Y dan alimentos, medicinas, leña, madera y materiales a comunidades que viven en ellos o cerca."]},"solucion":{}},{"slug":"plantas-5.s2.p2","orden":2,"grupo":"plantas-5.s2.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tipo de servicio es cada uno?","grupos":[{"id":"g1","nombre":"Regulación"},{"id":"g2","nombre":"Provisión"},{"id":"g3","nombre":"Cultural"}],"items":[{"id":"i1","texto":"Retener lluvias y alimentar ríos"},{"id":"i2","texto":"Miel del monte"},{"id":"i3","texto":"Lugares sagrados de comunidades indígenas"},{"id":"i4","texto":"Proteger el suelo de la erosión"},{"id":"i5","texto":"Harina de algarroba"},{"id":"i6","texto":"Paisajes para el turismo de naturaleza"},{"id":"i7","texto":"Guardar carbono"},{"id":"i8","texto":"Madera con manejo sostenible"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g1","i8":"g2"},"explicacion":"Los servicios de regulación suelen ser los más invisibles y los más valiosos."}},{"slug":"plantas-5.s2.p3","orden":3,"grupo":"plantas-5.s2.p3","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un bosque de montaña regula el agua.","items":[{"id":"i1","texto":"Llueve sobre las laderas con bosque"},{"id":"i2","texto":"Las hojas, el mantillo y las raíces frenan el agua"},{"id":"i3","texto":"El agua se infiltra en el suelo"},{"id":"i4","texto":"Se libera de a poco hacia los arroyos"},{"id":"i5","texto":"Los ríos tienen agua más pareja y menos crecidas violentas"},{"id":"i6","texto":"El bosque hace que el agua corra más rápido ladera abajo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Sin bosque, la lluvia corre de golpe: más crecidas en lluvias y menos agua en la seca."}},{"slug":"plantas-5.s2.p4","orden":4,"grupo":"plantas-5.s2.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué puede pasar aguas abajo si se desmonta una ladera de yungas?","opciones":[{"id":"o1","texto":"Más crecidas violentas y más arrastre de sedimentos"},{"id":"o2","texto":"Más agua limpia y pareja todo el año"},{"id":"o3","texto":"Nada, porque el bosque no tiene relación con el agua"},{"id":"o4","texto":"Menos lluvias en toda la región"}]},"solucion":{"clave":["o1"],"explicacion":"La pérdida de bosque en las cuencas altas puede aumentar el riesgo de aluviones y erosión.","por_opcion":{"o3":"El bosque retiene y regula el agua de lluvia."}}},{"slug":"plantas-5.s2.p5","orden":5,"grupo":"plantas-5.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Comunidades del bosque","cuerpo":["En los bosques argentinos viven comunidades indígenas y criollas cuyo modo de vida depende del monte: recolectan frutos como la algarroba y el chañar, miel, fibras, plantas medicinales; crían animales; pescan y cazan. Para ellas el bosque no es solo un recurso: es territorio, cultura y memoria. Por eso los desmontes suelen generar conflictos con estas comunidades, que muchas veces no fueron consultadas."]},"solucion":{}},{"slug":"plantas-5.s2.p6","orden":6,"grupo":"plantas-5.s2.p6","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué obtienen del monte chaqueño muchas comunidades que viven en él? Marcá todo.","opciones":[{"id":"o1","texto":"Frutos como la algarroba y el chañar"},{"id":"o2","texto":"Miel silvestre"},{"id":"o3","texto":"Fibras y plantas medicinales"},{"id":"o4","texto":"Leña y materiales para construir"},{"id":"o5","texto":"Nada, porque el monte no tiene recursos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El bosque en pie sostiene economías y culturas enteras."}},{"slug":"plantas-5.s2.p7","orden":7,"grupo":"plantas-5.s2.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un bosque guarda en promedio 100 toneladas de carbono por hectárea entre troncos, raíces y suelo, ¿cuántas toneladas de carbono guardan 1.000 hectáreas?","unidad":"toneladas de carbono","decimales":0,"contexto":"1000 ha; 100 t de carbono por hectárea."},"solucion":{"valor":100000,"tolerancia":2000,"explicacion":"1.000 × 100 = 100.000 toneladas de carbono. Si se desmonta y se quema, gran parte se libera como CO₂. Valores de ejemplo."}},{"slug":"plantas-5.s2.p7.v2","orden":7,"grupo":"plantas-5.s2.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un bosque guarda en promedio 80 toneladas de carbono por hectárea entre troncos, raíces y suelo, ¿cuántas toneladas de carbono guardan 5.000 hectáreas?","unidad":"toneladas de carbono","decimales":0,"contexto":"5000 ha; 80 t de carbono por hectárea."},"solucion":{"valor":400000,"tolerancia":8000,"explicacion":"5.000 × 80 = 400.000 toneladas de carbono. Si se desmonta y se quema, gran parte se libera como CO₂. Valores de ejemplo."}},{"slug":"plantas-5.s2.p7.v3","orden":7,"grupo":"plantas-5.s2.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un bosque guarda en promedio 150 toneladas de carbono por hectárea entre troncos, raíces y suelo, ¿cuántas toneladas de carbono guardan 200 hectáreas?","unidad":"toneladas de carbono","decimales":0,"contexto":"200 ha; 150 t de carbono por hectárea."},"solucion":{"valor":30000,"tolerancia":600,"explicacion":"200 × 150 = 30.000 toneladas de carbono. Si se desmonta y se quema, gran parte se libera como CO₂. Valores de ejemplo."}},{"slug":"plantas-5.s2.p8","orden":8,"grupo":"plantas-5.s2.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cada tonelada de carbono equivale a unas 3,67 toneladas de CO₂. ¿Cuántas toneladas de CO₂ equivalen a 100 toneladas de carbono? Redondeá al entero.","unidad":"t de CO₂","decimales":0,"contexto":"100 t de carbono; factor 3,67."},"solucion":{"valor":367,"tolerancia":1,"explicacion":"100 × 3,67 ≈ 367 t de CO₂. El oxígeno que se une al carbono al quemarse agrega peso: lo viste con la nafta."}},{"slug":"plantas-5.s2.p8.v2","orden":8,"grupo":"plantas-5.s2.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cada tonelada de carbono equivale a unas 3,67 toneladas de CO₂. ¿Cuántas toneladas de CO₂ equivalen a 80 toneladas de carbono? Redondeá al entero.","unidad":"t de CO₂","decimales":0,"contexto":"80 t de carbono; factor 3,67."},"solucion":{"valor":294,"tolerancia":1,"explicacion":"80 × 3,67 ≈ 294 t de CO₂. El oxígeno que se une al carbono al quemarse agrega peso: lo viste con la nafta."}},{"slug":"plantas-5.s2.p8.v3","orden":8,"grupo":"plantas-5.s2.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cada tonelada de carbono equivale a unas 3,67 toneladas de CO₂. ¿Cuántas toneladas de CO₂ equivalen a 150 toneladas de carbono? Redondeá al entero.","unidad":"t de CO₂","decimales":0,"contexto":"150 t de carbono; factor 3,67."},"solucion":{"valor":551,"tolerancia":1,"explicacion":"150 × 3,67 ≈ 551 t de CO₂. El oxígeno que se une al carbono al quemarse agrega peso: lo viste con la nafta."}},{"slug":"plantas-5.s2.p9","orden":9,"grupo":"plantas-5.s2.p9","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Quién se beneficia del carbono que guarda un bosque del Chaco?","opciones":[{"id":"o1","texto":"Todo el planeta, porque el clima es uno solo"},{"id":"o2","texto":"Solo el dueño del campo donde está el bosque"},{"id":"o3","texto":"Nadie, porque el carbono no tiene efectos"},{"id":"o4","texto":"Solo las ciudades más cercanas al bosque"}]},"solucion":{"clave":["o1"],"explicacion":"Algunos servicios del bosque son locales; el del carbono es global.","por_opcion":{"o3":"El carbono liberado calienta el clima de todos."}}},{"slug":"plantas-5.s2.p10","orden":10,"grupo":"plantas-5.s2.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada servicio con quién se beneficia.","izquierda":[{"id":"a1","texto":"Regulación del agua de las yungas"},{"id":"a2","texto":"Carbono guardado"},{"id":"a3","texto":"Frutos del monte"},{"id":"a4","texto":"Hábitat del yaguareté"}],"derecha":[{"id":"b1","texto":"Ciudades y riegos del noroeste"},{"id":"b2","texto":"Todo el planeta"},{"id":"b3","texto":"Comunidades que viven en el bosque"},{"id":"b4","texto":"La biodiversidad del país"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Los beneficios del bosque llegan a escalas muy distintas: del hogar al planeta."}},{"slug":"plantas-5.s2.p11","orden":11,"grupo":"plantas-5.s2.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un bosque solo tiene valor cuando se lo tala y se vende su madera.","razones":[{"id":"r1","texto":"Porque en pie presta muchos servicios que se pierden al talarlo"},{"id":"r2","texto":"Porque la madera no tiene ningún valor"},{"id":"r3","texto":"Porque los bosques no prestan servicios"}]},"solucion":{"valor":false,"explicacion":"El bosque en pie regula el agua, protege el suelo, guarda carbono, sostiene la biodiversidad y a comunidades enteras. Muchos de esos valores se pierden al talarlo.","clave":["r1"]}},{"slug":"plantas-5.s2.p12","orden":12,"grupo":"plantas-5.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Las yungas ayudan a regular el agua de los ríos del noroeste."},{"id":"s2","texto":"Desmontar una ladera reduce las crecidas."},{"id":"s3","texto":"Muchas comunidades obtienen alimentos y medicinas del monte."},{"id":"s4","texto":"El carbono de un bosque está solo en las hojas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El bosque trabaja para nosotros de muchas maneras invisibles.","por_opcion":{"s2":"Suele aumentarlas: el agua corre más rápido y arrastra suelo.","s4":"Está en troncos, raíces y, en gran parte, en el suelo."}}},{"slug":"plantas-5.s2.p13","orden":13,"grupo":"plantas-5.s2.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los beneficios que da la naturaleza se llaman servicios {{0}}; el bosque de montaña frena el agua y reduce las {{1}}; y la harina de {{2}} es un alimento del monte.","banco":[{"id":"w1","texto":"ecosistémicos"},{"id":"w2","texto":"crecidas"},{"id":"w3","texto":"algarroba"},{"id":"w4","texto":"publicitarios"},{"id":"w5","texto":"sequías"},{"id":"w6","texto":"soja"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre lo que hacen los bosques nativos."}}]},{"slug":"plantas-5.s3","orden":3,"tipo":"leccion","titulo_es":"La Ley de Bosques en profundidad","bajada_es":"Ordenamiento participativo, compensaciones, un fondo que nunca llegó completo y lo que cambió desde 2007.","minutos":12,"pasos":[{"slug":"plantas-5.s3.p1","orden":1,"grupo":"plantas-5.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El ordenamiento","cuerpo":["La Ley 26.331, de 2007, obligó a cada provincia a hacer su Ordenamiento Territorial de Bosques Nativos, con participación de la sociedad, y a clasificar sus bosques en tres categorías. Rojo: muy alto valor de conservación, no se transforma. Amarillo: valor medio, se permite un uso sostenible, pero no el desmonte. Verde: bajo valor, puede transformarse con evaluación de impacto ambiental y audiencia pública. En la mayoría de las provincias, la mayor parte del bosque quedó en categoría amarilla. Los ordenamientos deben actualizarse periódicamente."]},"solucion":{}},{"slug":"plantas-5.s3.p2","orden":2,"grupo":"plantas-5.s3.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué se permite en cada categoría del ordenamiento?","grupos":[{"id":"g1","nombre":"Roja"},{"id":"g2","nombre":"Amarilla"},{"id":"g3","nombre":"Verde"}],"items":[{"id":"i1","texto":"Investigación científica"},{"id":"i2","texto":"Aprovechamiento sostenible de madera"},{"id":"i3","texto":"Desmonte con evaluación de impacto y audiencia pública"},{"id":"i4","texto":"Conservación estricta"},{"id":"i5","texto":"Turismo y recolección de frutos"},{"id":"i6","texto":"Ganadería integrada al bosque"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g2"},"explicacion":"La ley no prohíbe todo: ordena qué se puede hacer y dónde."}},{"slug":"plantas-5.s3.p3","orden":3,"grupo":"plantas-5.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El fondo","cuerpo":["La ley creó el Fondo Nacional para el Enriquecimiento y la Conservación de los Bosques Nativos, para compensar a quienes conservan bosques y fortalecer los controles provinciales. Según la ley, debe recibir al menos el 0,3 % del presupuesto nacional, más el 2 % de las retenciones a las exportaciones agropecuarias y forestales. Pero, según análisis de Chequeado y de organizaciones como FARN, ningún gobierno cumplió ese monto desde 2007: en los últimos presupuestos se asignó apenas alrededor del 3 al 4 % de lo que manda la ley."],"destacado":{"valor":"≈ 3 %","texto":"de lo que establece la ley recibió el fondo de bosques en presupuestos recientes, según Chequeado y FARN."}},"solucion":{}},{"slug":"plantas-5.s3.p4","orden":4,"grupo":"plantas-5.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si por ley el fondo de bosques debería recibir 600 mil millones de pesos y recibe 18 mil millones, ¿qué porcentaje de lo establecido recibe? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"18 de 600 mil millones."},"solucion":{"valor":3,"tolerancia":1,"explicacion":"18 ÷ 600 × 100 ≈ 3 %. Con tan poco, las compensaciones a quienes conservan y los controles se debilitan. Valores de ejemplo, del orden de los presupuestos recientes."}},{"slug":"plantas-5.s3.p4.v2","orden":4,"grupo":"plantas-5.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si por ley el fondo de bosques debería recibir 500 mil millones de pesos y recibe 20 mil millones, ¿qué porcentaje de lo establecido recibe? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"20 de 500 mil millones."},"solucion":{"valor":4,"tolerancia":1,"explicacion":"20 ÷ 500 × 100 ≈ 4 %. Con tan poco, las compensaciones a quienes conservan y los controles se debilitan. Valores de ejemplo, del orden de los presupuestos recientes."}},{"slug":"plantas-5.s3.p4.v3","orden":4,"grupo":"plantas-5.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si por ley el fondo de bosques debería recibir 800 mil millones de pesos y recibe 28 mil millones, ¿qué porcentaje de lo establecido recibe? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"28 de 800 mil millones."},"solucion":{"valor":4,"tolerancia":1,"explicacion":"28 ÷ 800 × 100 ≈ 4 %. Con tan poco, las compensaciones a quienes conservan y los controles se debilitan. Valores de ejemplo, del orden de los presupuestos recientes."}},{"slug":"plantas-5.s3.p5","orden":5,"grupo":"plantas-5.s3.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el desfinanciamiento debilita la ley.","items":[{"id":"i1","texto":"El fondo recibe mucho menos de lo que manda la ley"},{"id":"i2","texto":"Las compensaciones a quienes conservan son muy bajas"},{"id":"i3","texto":"Conservar deja de ser atractivo frente a desmontar"},{"id":"i4","texto":"Las provincias tienen menos recursos para controlar"},{"id":"i5","texto":"Crece el riesgo de desmontes, incluso ilegales"},{"id":"i6","texto":"Con menos fondos, los controles mejoran"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una ley sin presupuesto pierde gran parte de su fuerza."}},{"slug":"plantas-5.s3.p6","orden":6,"grupo":"plantas-5.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que cambió","cuerpo":["Después de la sanción de la ley, el ritmo de desmonte bajó respecto de los años previos, pero no se detuvo. Una parte de la pérdida siguió ocurriendo en zonas rojas y amarillas, donde el desmonte está prohibido, y los incendios también causaron pérdidas. El monitoreo satelital permite detectar esos desmontes casi en tiempo real; el desafío es que los controles y las sanciones funcionen."]},"solucion":{}},{"slug":"plantas-5.s3.p7","orden":7,"grupo":"plantas-5.s3.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Desde que existe la Ley de Bosques, no hubo más desmontes en zonas rojas o amarillas.","razones":[{"id":"r1","texto":"Porque hubo desmontes ilegales en zonas prohibidas"},{"id":"r2","texto":"Porque la ley permite desmontar en rojo"},{"id":"r3","texto":"Porque los satélites no pueden ver bosques"}]},"solucion":{"valor":false,"explicacion":"Siguieron ocurriendo desmontes, algunos ilegales, en zonas donde la ley los prohíbe. El monitoreo satelital los detecta; el problema es el control y la sanción.","clave":["r1"]}},{"slug":"plantas-5.s3.p8","orden":8,"grupo":"plantas-5.s3.p8","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué herramienta permite detectar un desmonte casi en tiempo real?","opciones":[{"id":"o1","texto":"El monitoreo con imágenes satelitales"},{"id":"o2","texto":"Una encuesta anual a los productores"},{"id":"o3","texto":"El censo nacional de población"},{"id":"o4","texto":"Las declaraciones juradas de los propietarios"}]},"solucion":{"clave":["o1"],"explicacion":"Lo viste en la rama digital: los satélites cambiaron la forma de vigilar los bosques.","por_opcion":{"o3":"No mide bosques."}}},{"slug":"plantas-5.s3.p9","orden":9,"grupo":"plantas-5.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Participación y actualización","cuerpo":["Los ordenamientos deben hacerse con participación de comunidades, productores, científicos y organizaciones, y actualizarse cada cierto tiempo. En esas actualizaciones hay tensiones: algunos sectores piden pasar zonas de amarillo a verde para poder desmontar. La ley establece el principio de no regresión: las actualizaciones no deberían disminuir la protección sin fundamentos sólidos."]},"solucion":{}},{"slug":"plantas-5.s3.p10","orden":10,"grupo":"plantas-5.s3.p10","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una provincia propone pasar muchas zonas de amarillo a verde en su actualización. ¿Qué principio ambiental entra en juego?","opciones":[{"id":"o1","texto":"El de no regresión en la protección"},{"id":"o2","texto":"El de libre comercio internacional"},{"id":"o3","texto":"El de propiedad intelectual"},{"id":"o4","texto":"El de prioridad del turismo"}]},"solucion":{"clave":["o1"],"explicacion":"Bajar la protección sin fundamentos contradice el objetivo de la ley.","por_opcion":{"o3":"No tiene relación con los bosques."}}},{"slug":"plantas-5.s3.p11","orden":11,"grupo":"plantas-5.s3.p11","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las categorías de la Ley de Bosques de mayor a menor protección.","items":[{"id":"i1","texto":"Roja"},{"id":"i2","texto":"Amarilla"},{"id":"i3","texto":"Verde"}],"extremos":["Más protección","Menos protección"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"Del bosque intocable al que puede cambiar de uso con controles.","valores":{"i1":"no se transforma","i2":"uso sostenible, sin desmonte","i3":"puede transformarse con evaluación"}}},{"slug":"plantas-5.s3.p12","orden":12,"grupo":"plantas-5.s3.p12","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada elemento de la ley con su función.","izquierda":[{"id":"a1","texto":"Ordenamiento territorial"},{"id":"a2","texto":"Fondo Nacional"},{"id":"a3","texto":"Audiencia pública"},{"id":"a4","texto":"Monitoreo satelital"}],"derecha":[{"id":"b1","texto":"Clasificar los bosques en tres categorías"},{"id":"b2","texto":"Compensar a quienes conservan y fortalecer controles"},{"id":"b3","texto":"Escuchar a la sociedad antes de un desmonte en zona verde"},{"id":"b4","texto":"Detectar desmontes"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada herramienta cumple un papel; si una falla, la ley se debilita."}},{"slug":"plantas-5.s3.p13","orden":13,"grupo":"plantas-5.s3.p13","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué haría más efectiva la Ley de Bosques? Marcá todo.","opciones":[{"id":"o1","texto":"Financiar el fondo como manda la ley"},{"id":"o2","texto":"Sancionar los desmontes ilegales detectados"},{"id":"o3","texto":"Actualizar los ordenamientos con participación real"},{"id":"o4","texto":"Apoyar el uso sostenible del bosque en zona amarilla"},{"id":"o5","texto":"Pasar todo el bosque a categoría verde"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Presupuesto, control, participación y alternativas productivas: la ley necesita todo eso."}},{"slug":"plantas-5.s3.p14","orden":14,"grupo":"plantas-5.s3.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este resumen y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La Ley 26.331 es de 2007."},{"id":"s2","texto":"El fondo de bosques recibió siempre el 100 % de lo que manda la ley."},{"id":"s3","texto":"En zona verde se puede desmontar con evaluación de impacto y audiencia pública."},{"id":"s4","texto":"Las actualizaciones pueden bajar la protección sin ninguna justificación."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La ley es una herramienta poderosa, con deudas pendientes en su aplicación.","por_opcion":{"s2":"Ningún gobierno cumplió: en presupuestos recientes, alrededor del 3 %.","s4":"Rige el principio de no regresión."}}},{"slug":"plantas-5.s3.p15","orden":15,"grupo":"plantas-5.s3.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La Ley de Bosques ordena los bosques en rojo, amarillo y {{0}}; su fondo debería recibir al menos el {{1}} % del presupuesto nacional; y bajar la protección sin fundamentos contradice el principio de no {{2}}.","banco":[{"id":"w1","texto":"verde"},{"id":"w2","texto":"0,3"},{"id":"w3","texto":"regresión"},{"id":"w4","texto":"azul"},{"id":"w5","texto":"30"},{"id":"w6","texto":"retorno"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de la Ley de Bosques en profundidad."}}]},{"slug":"plantas-5.s4","orden":4,"tipo":"leccion","titulo_es":"Fuego en el bosque","bajada_es":"Por qué se queman los bosques, qué dice la ley sobre las tierras incendiadas y cómo se previene.","minutos":11,"pasos":[{"slug":"plantas-5.s4.p1","orden":1,"grupo":"plantas-5.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El origen del fuego","cuerpo":["Según el Servicio Nacional de Manejo del Fuego, alrededor del 95 % de los incendios forestales y rurales en Argentina son causados por las personas: fogatas mal apagadas, quemas de basura o de pastizales que se descontrolan, colillas, chispas de máquinas o incendios intencionales. Las condiciones climáticas —sequía, calor y viento— determinan cuánto se propaga un incendio, y con el calentamiento esas condiciones se vuelven más frecuentes."],"destacado":{"valor":"≈ 95 %","texto":"de los incendios forestales y rurales en Argentina son de origen humano, según el Servicio Nacional de Manejo del Fuego."}},"solucion":{}},{"slug":"plantas-5.s4.p2","orden":2,"grupo":"plantas-5.s4.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿El factor influye en que el fuego empiece o en cuánto se propaga?","grupos":[{"id":"g1","nombre":"En que empiece"},{"id":"g2","nombre":"En cuánto se propaga"}],"items":[{"id":"i1","texto":"Una fogata mal apagada"},{"id":"i2","texto":"Una sequía prolongada"},{"id":"i3","texto":"Una quema de pastizales"},{"id":"i4","texto":"Viento fuerte"},{"id":"i5","texto":"Una colilla tirada al costado de la ruta"},{"id":"i6","texto":"Temperaturas muy altas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Casi siempre alguien enciende el fuego; el clima decide cuán grande se vuelve."}},{"slug":"plantas-5.s4.p3","orden":3,"grupo":"plantas-5.s4.p3","tipo":"estimar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de los incendios forestales y rurales en Argentina tiene origen humano.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":95,"banda":"lineal","explicacion":"Alrededor del 95 %. Por eso la prevención es tan eficaz: la mayoría de los incendios podría evitarse."}},{"slug":"plantas-5.s4.p4","orden":4,"grupo":"plantas-5.s4.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el calentamiento agrava los incendios.","items":[{"id":"i1","texto":"Suben las temperaturas y se alargan las sequías"},{"id":"i2","texto":"La vegetación se seca más"},{"id":"i3","texto":"Hay más combustible seco disponible"},{"id":"i4","texto":"Un fuego iniciado se propaga más rápido"},{"id":"i5","texto":"Los incendios son más grandes y difíciles de controlar"},{"id":"i6","texto":"El calor humedece la vegetación"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El clima no enciende el fuego, pero multiplica su poder."}},{"slug":"plantas-5.s4.p5","orden":5,"grupo":"plantas-5.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La ley después del fuego","cuerpo":["Para evitar que los incendios se usen para cambiar el uso de la tierra, en 2020 la Ley 27.604 modificó la Ley de Manejo del Fuego. Estableció que en bosques nativos o implantados, áreas naturales protegidas y humedales afectados por incendios no se puede modificar el uso que tenían antes del fuego durante 60 años; y en zonas agrícolas, praderas, pastizales y áreas de interfase, durante 30 años."]},"solucion":{}},{"slug":"plantas-5.s4.p6","orden":6,"grupo":"plantas-5.s4.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué busca prohibir la Ley 27.604 en las tierras incendiadas?","opciones":[{"id":"o1","texto":"Cambiar el uso que tenían antes del incendio"},{"id":"o2","texto":"Volver a plantar árboles nativos"},{"id":"o3","texto":"Que los bomberos entren a apagar el fuego"},{"id":"o4","texto":"Que se estudie la biodiversidad del lugar"}]},"solucion":{"clave":["o1"],"explicacion":"Si quemar no permite cambiar el uso, desaparece el incentivo a provocar incendios para lotear o desmontar.","por_opcion":{"o3":"Al contrario: busca proteger las tierras, no impedir apagar el fuego."}}},{"slug":"plantas-5.s4.p7","orden":7,"grupo":"plantas-5.s4.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué plazo fija la ley para cada tipo de tierra incendiada?","grupos":[{"id":"g1","nombre":"60 años"},{"id":"g2","nombre":"30 años"}],"items":[{"id":"i1","texto":"Bosque nativo"},{"id":"i2","texto":"Pastizal"},{"id":"i3","texto":"Humedal"},{"id":"i4","texto":"Zona agrícola"},{"id":"i5","texto":"Área natural protegida"},{"id":"i6","texto":"Área de interfase"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los plazos largos buscan que la tierra quemada pueda restaurarse, y quitan el incentivo a quemar."}},{"slug":"plantas-5.s4.p8","orden":8,"grupo":"plantas-5.s4.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un bosque nativo se incendió en 2021, ¿hasta qué año no se podría cambiar su uso, según el plazo de 60 años?","unidad":"año","decimales":0,"contexto":"Incendio en 2021; plazo de 60 años."},"solucion":{"valor":2081,"tolerancia":41.62,"explicacion":"2021 + 60 = 2081. Un plazo tan largo le quita todo sentido económico a quemar un bosque para cambiarle el uso."}},{"slug":"plantas-5.s4.p8.v2","orden":8,"grupo":"plantas-5.s4.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un bosque nativo se incendió en 2025, ¿hasta qué año no se podría cambiar su uso, según el plazo de 60 años?","unidad":"año","decimales":0,"contexto":"Incendio en 2025; plazo de 60 años."},"solucion":{"valor":2085,"tolerancia":41.7,"explicacion":"2025 + 60 = 2085. Un plazo tan largo le quita todo sentido económico a quemar un bosque para cambiarle el uso."}},{"slug":"plantas-5.s4.p8.v3","orden":8,"grupo":"plantas-5.s4.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un bosque nativo se incendió en 2023, ¿hasta qué año no se podría cambiar su uso, según el plazo de 60 años?","unidad":"año","decimales":0,"contexto":"Incendio en 2023; plazo de 60 años."},"solucion":{"valor":2083,"tolerancia":41.660000000000004,"explicacion":"2023 + 60 = 2083. Un plazo tan largo le quita todo sentido económico a quemar un bosque para cambiarle el uso."}},{"slug":"plantas-5.s4.p9","orden":9,"grupo":"plantas-5.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Prevenir","cuerpo":["La prevención combina educación (no hacer fuego en días de riesgo, apagar bien las fogatas), manejo del combustible (cortafuegos, limpieza de la vegetación seca cerca de las casas), alerta temprana con índices de peligro y detección satelital de focos, brigadas preparadas y control de las quemas. En las zonas de interfase, donde las casas están mezcladas con el bosque, preparar las viviendas y sus alrededores salva vidas."]},"solucion":{}},{"slug":"plantas-5.s4.p10","orden":10,"grupo":"plantas-5.s4.p10","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conviene hacer con una fogata antes de irse de un camping?","opciones":[{"id":"o1","texto":"Apagarla con agua y tierra hasta que no quede calor"},{"id":"o2","texto":"Dejarla con poca leña para que se apague sola"},{"id":"o3","texto":"Taparla solo con hojas secas"},{"id":"o4","texto":"Dejarla encendida si no hay viento"}]},"solucion":{"clave":["o1"],"explicacion":"Muchas fogatas \"apagadas\" conservan brasas que se reavivan horas después.","por_opcion":{"o3":"Las hojas secas son combustible: pueden reavivarla."}}},{"slug":"plantas-5.s4.p11","orden":11,"grupo":"plantas-5.s4.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas previenen incendios forestales o reducen su daño? Marcá todas.","opciones":[{"id":"o1","texto":"No hacer fuego en días de alto riesgo"},{"id":"o2","texto":"Cortafuegos y limpieza de vegetación seca cerca de las casas"},{"id":"o3","texto":"Detección satelital de focos"},{"id":"o4","texto":"Brigadas capacitadas y equipadas"},{"id":"o5","texto":"Quemar pastizales en días de viento"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La mayor parte de los incendios se puede evitar; el resto se puede limitar con preparación."}},{"slug":"plantas-5.s4.p12","orden":12,"grupo":"plantas-5.s4.p12","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas acciones frente al fuego según su momento, de la más anticipada a la más tardía.","items":[{"id":"i1","texto":"Educar y controlar las quemas antes de la temporada"},{"id":"i2","texto":"Detectar un foco con satélites"},{"id":"i3","texto":"Enviar brigadas al incendio"},{"id":"i4","texto":"Restaurar el bosque quemado"}],"extremos":["Más anticipada","Más tardía"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada etapa importa, pero la prevención es la más barata y efectiva.","valores":{"i1":"prevención","i2":"detección","i3":"combate","i4":"recuperación"}}},{"slug":"plantas-5.s4.p13","orden":13,"grupo":"plantas-5.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este volante de temporada de incendios y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La mayoría de los incendios forestales los provocan personas."},{"id":"s2","texto":"Una fogata se apaga sola si se deja de alimentar."},{"id":"s3","texto":"En días de viento y calor, no hay que hacer fuego al aire libre."},{"id":"s4","texto":"Después de un incendio, el bosque se puede lotear al año siguiente."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Prevenir incendios es una responsabilidad de cada persona y de todo el sistema.","por_opcion":{"s2":"Hay que apagarla con agua y tierra hasta que no quede calor.","s4":"La ley prohíbe cambiar su uso durante 60 años."}}},{"slug":"plantas-5.s4.p14","orden":14,"grupo":"plantas-5.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Alrededor del {{0}} % de los incendios forestales tiene origen humano; en un bosque nativo quemado no se puede cambiar el uso durante {{1}} años; y las zonas donde las casas se mezclan con el bosque se llaman de {{2}}.","banco":[{"id":"w1","texto":"95"},{"id":"w2","texto":"60"},{"id":"w3","texto":"interfase"},{"id":"w4","texto":"5"},{"id":"w5","texto":"6"},{"id":"w6","texto":"reserva"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves sobre el fuego en los bosques."}}]},{"slug":"plantas-5.s5","orden":5,"tipo":"leccion","titulo_es":"Usar el bosque sin destruirlo","bajada_es":"Manejo forestal sostenible, productos no madereros, turismo y el riesgo del desmonte disfrazado.","minutos":11,"pasos":[{"slug":"plantas-5.s5.p1","orden":1,"grupo":"plantas-5.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Manejo forestal sostenible","cuerpo":["Usar el bosque sin destruirlo es posible. El manejo forestal sostenible saca madera sin superar lo que el bosque puede reponer: se extraen algunos árboles seleccionados, se dejan los árboles semilleros y los renovales, se respetan los tiempos de recuperación, se protegen arroyos y especies amenazadas, y se planifica a largo plazo. Existen certificaciones independientes, como la del Consejo de Administración Forestal (FSC), que verifican ese manejo."]},"solucion":{}},{"slug":"plantas-5.s5.p2","orden":2,"grupo":"plantas-5.s5.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta práctica corresponde a un manejo sostenible o a una sobreexplotación?","grupos":[{"id":"g1","nombre":"Manejo sostenible"},{"id":"g2","nombre":"Sobreexplotación"}],"items":[{"id":"i1","texto":"Extraer solo algunos árboles seleccionados"},{"id":"i2","texto":"Talar todos los árboles grandes a la vez"},{"id":"i3","texto":"Dejar los árboles semilleros"},{"id":"i4","texto":"Sacar madera cada año del mismo lote"},{"id":"i5","texto":"Respetar los tiempos de recuperación"},{"id":"i6","texto":"Talar junto a los arroyos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Lo que se saca no puede superar lo que el bosque repone."}},{"slug":"plantas-5.s5.p3","orden":3,"grupo":"plantas-5.s5.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un bosque de 1.000 hectáreas crece 2 m³ de madera por hectárea por año, ¿cuántos m³ por año se podrían extraer como máximo sin achicar el bosque?","unidad":"m³ por año","decimales":0,"contexto":"1000 ha; crecimiento de 2 m³ por hectárea por año."},"solucion":{"valor":2000,"tolerancia":40,"explicacion":"1.000 × 2 = 2.000 m³ por año. Extraer más que el crecimiento empobrece el bosque. Lo viste con los recursos renovables en el tronco."}},{"slug":"plantas-5.s5.p3.v2","orden":3,"grupo":"plantas-5.s5.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un bosque de 500 hectáreas crece 1,5 m³ de madera por hectárea por año, ¿cuántos m³ por año se podrían extraer como máximo sin achicar el bosque?","unidad":"m³ por año","decimales":0,"contexto":"500 ha; crecimiento de 1.5 m³ por hectárea por año."},"solucion":{"valor":750,"tolerancia":15,"explicacion":"500 × 1,5 = 750 m³ por año. Extraer más que el crecimiento empobrece el bosque. Lo viste con los recursos renovables en el tronco."}},{"slug":"plantas-5.s5.p3.v3","orden":3,"grupo":"plantas-5.s5.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un bosque de 2.000 hectáreas crece 1 m³ de madera por hectárea por año, ¿cuántos m³ por año se podrían extraer como máximo sin achicar el bosque?","unidad":"m³ por año","decimales":0,"contexto":"2000 ha; crecimiento de 1 m³ por hectárea por año."},"solucion":{"valor":2000,"tolerancia":40,"explicacion":"2.000 × 1 = 2.000 m³ por año. Extraer más que el crecimiento empobrece el bosque. Lo viste con los recursos renovables en el tronco."}},{"slug":"plantas-5.s5.p4","orden":4,"grupo":"plantas-5.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Más allá de la madera","cuerpo":["Los productos forestales no madereros —miel, frutos como la algarroba o el chañar, hongos, resinas, fibras, plantas medicinales, semillas— pueden generar ingresos sin talar árboles. El turismo de naturaleza y el avistaje de aves también dan valor al bosque en pie. Cuando el bosque vivo genera ingresos para quienes lo cuidan, conservarlo se vuelve una opción económica, no solo un deber."]},"solucion":{}},{"slug":"plantas-5.s5.p5","orden":5,"grupo":"plantas-5.s5.p5","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué productos o actividades dan valor al bosque en pie? Marcá todos.","opciones":[{"id":"o1","texto":"Miel del monte"},{"id":"o2","texto":"Harina de algarroba"},{"id":"o3","texto":"Turismo de avistaje de aves"},{"id":"o4","texto":"Semillas nativas para restauración"},{"id":"o5","texto":"Carbón vegetal de desmontes totales"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El bosque en pie puede ser una fuente de trabajo y de ingresos."}},{"slug":"plantas-5.s5.p6","orden":6,"grupo":"plantas-5.s5.p6","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo los ingresos del bosque en pie ayudan a conservarlo.","items":[{"id":"i1","texto":"Una comunidad vende miel y harina de algarroba del monte"},{"id":"i2","texto":"Obtiene ingresos del bosque vivo"},{"id":"i3","texto":"El bosque vale más en pie que desmontado"},{"id":"i4","texto":"La comunidad lo cuida y denuncia los desmontes"},{"id":"i5","texto":"El bosque se conserva"},{"id":"i6","texto":"Los ingresos del monte obligan a desmontarlo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Conservar es más fácil cuando conservar paga."}},{"slug":"plantas-5.s5.p7","orden":7,"grupo":"plantas-5.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El desmonte disfrazado","cuerpo":["En zona amarilla se permite el uso sostenible, pero a veces se presentan como \"manejo\" prácticas que en la realidad eliminan el bosque: se rola todo el sotobosque, se sacan casi todos los árboles y se dejan pocos aislados para siembra de pasturas. Lo viste con la ganadería en el bosque. Para distinguirlo hay que mirar la estructura que queda: si el bosque puede seguir regenerándose o se convirtió en un pastizal con árboles sueltos."]},"solucion":{}},{"slug":"plantas-5.s5.p8","orden":8,"grupo":"plantas-5.s5.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cómo se distingue un manejo sostenible de un desmonte disfrazado?","opciones":[{"id":"o1","texto":"Mirando si queda un bosque que puede regenerarse"},{"id":"o2","texto":"Leyendo el nombre que tiene el proyecto"},{"id":"o3","texto":"Contando cuántas vacas entraron"},{"id":"o4","texto":"Mirando el color de los carteles del campo"}]},"solucion":{"clave":["o1"],"explicacion":"Los nombres pueden engañar; la estructura del bosque, no.","por_opcion":{"o3":"Importa, pero lo decisivo es la estructura del bosque que queda."}}},{"slug":"plantas-5.s5.p9","orden":9,"grupo":"plantas-5.s5.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un proyecto se llama \"manejo sostenible\", seguro conserva el bosque.","razones":[{"id":"r1","texto":"Porque hay que verificar qué bosque queda en el terreno"},{"id":"r2","texto":"Porque ningún manejo es sostenible"},{"id":"r3","texto":"Porque el nombre obliga a conservar"}]},"solucion":{"valor":false,"explicacion":"Hay que verificar en el terreno y con imágenes satelitales qué estructura queda. Algunos proyectos con ese nombre funcionaron como desmontes disfrazados.","clave":["r1"]}},{"slug":"plantas-5.s5.p10","orden":10,"grupo":"plantas-5.s5.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con lo que verifica.","izquierda":[{"id":"a1","texto":"Certificación FSC"},{"id":"a2","texto":"Imágenes satelitales"},{"id":"a3","texto":"Inventario forestal"},{"id":"a4","texto":"Plan de manejo aprobado"}],"derecha":[{"id":"b1","texto":"Que el manejo forestal sea responsable"},{"id":"b2","texto":"Cuánta cobertura de bosque queda"},{"id":"b3","texto":"Qué árboles y cuántos hay"},{"id":"b4","texto":"Qué se puede extraer y cuándo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Verificar el manejo protege al bosque y a quienes lo hacen bien."}},{"slug":"plantas-5.s5.p11","orden":11,"grupo":"plantas-5.s5.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un bosque que genera ingresos estando en pie tiene más chances de conservarse.","razones":[{"id":"r1","texto":"Porque conservar pasa a ser una opción económica"},{"id":"r2","texto":"Porque los ingresos obligan a desmontar"},{"id":"r3","texto":"Porque un bosque en pie nunca genera ingresos"}]},"solucion":{"valor":true,"explicacion":"Cuando conservar da trabajo e ingresos a quienes viven del bosque, cuidarlo se vuelve una opción económica y no solo un deber.","clave":["r1"]}},{"slug":"plantas-5.s5.p12","orden":12,"grupo":"plantas-5.s5.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos usos de un bosque en zona amarilla, del más compatible con la conservación al menos.","items":[{"id":"i1","texto":"Recolección de frutos y miel"},{"id":"i2","texto":"Aprovechamiento selectivo de madera con plan"},{"id":"i3","texto":"Ganadería integrada con carga moderada"},{"id":"i4","texto":"Rolado total del sotobosque para pasturas"}],"extremos":["Más compatible","Menos compatible"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los usos que mantienen la estructura del bosque son los que permite la zona amarilla.","valores":{"i1":"muy compatible","i2":"compatible","i3":"compatible si se controla","i4":"incompatible"}}},{"slug":"plantas-5.s5.p13","orden":13,"grupo":"plantas-5.s5.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este proyecto para una zona amarilla y marcá lo que no corresponde.","segmentos":[{"id":"s1","texto":"Extraeremos solo árboles seleccionados según el plan de manejo."},{"id":"s2","texto":"Rolaremos todo el sotobosque y dejaremos diez árboles por hectárea."},{"id":"s3","texto":"Venderemos miel y harina de algarroba."},{"id":"s4","texto":"Talaremos junto al arroyo porque los árboles son más grandes."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen proyecto en zona amarilla produce y conserva a la vez.","por_opcion":{"s2":"Eso elimina el bosque: es un desmonte disfrazado.","s4":"Las márgenes de arroyos deben protegerse."}}},{"slug":"plantas-5.s5.p14","orden":14,"grupo":"plantas-5.s5.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Sacar madera sin superar lo que el bosque repone es un manejo {{0}}; la miel y los frutos del monte son productos no {{1}}; y una certificación independiente de manejo forestal es la {{2}}.","banco":[{"id":"w1","texto":"sostenible"},{"id":"w2","texto":"madereros"},{"id":"w3","texto":"FSC"},{"id":"w4","texto":"intensivo"},{"id":"w5","texto":"comestibles"},{"id":"w6","texto":"ISO"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para usar el bosque sin destruirlo."}}]},{"slug":"plantas-5.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: bosques nativos","bajada_es":"Regiones forestales, servicios, Ley de Bosques, fuego y uso sostenible, mezclados.","minutos":8,"pasos":[{"slug":"plantas-5.s6.p1","orden":1,"grupo":"plantas-5.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Bosques nativos». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"plantas-5.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la actualización del ordenamiento","bajada_es":"Una provincia chaqueña actualiza su Ordenamiento Territorial de Bosques Nativos. Evaluá las propuestas con los datos.","minutos":10,"pasos":[{"slug":"plantas-5.s7.p1","orden":1,"grupo":"plantas-5.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["La provincia tiene 4 millones de hectáreas de bosque nativo: 600.000 en rojo, 2.800.000 en amarillo y 600.000 en verde. En los últimos cinco años, el monitoreo satelital detectó 50.000 hectáreas desmontadas en zonas amarillas, donde está prohibido. Un grupo de productores propone pasar 500.000 hectáreas de amarillo a verde. Comunidades indígenas del norte de la provincia piden que sus territorios pasen a rojo. El fondo de bosques le transfiere a la provincia solo una fracción de lo que debería."]},"solucion":{}},{"slug":"plantas-5.s7.p2","orden":2,"grupo":"plantas-5.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Qué porcentaje del bosque de la provincia está en categoría amarilla?","unidad":"%","decimales":0,"contexto":"2,8 millones de 4 millones de hectáreas."},"solucion":{"valor":70,"tolerancia":1.4000000000000001,"explicacion":"2.800.000 ÷ 4.000.000 × 100 = 70 %. Como en muchas provincias, la mayor parte del bosque quedó en amarillo."}},{"slug":"plantas-5.s7.p3","orden":3,"grupo":"plantas-5.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se aprobara el pase de 500.000 hectáreas de amarillo a verde, ¿cuántas hectáreas quedarían en verde?","unidad":"hectáreas","decimales":0,"contexto":"600.000 ha en verde; se suman 500.000."},"solucion":{"valor":1100000,"tolerancia":22000,"explicacion":"600.000 + 500.000 = 1.100.000 hectáreas en verde, casi el doble: una fuerte baja de la protección."}},{"slug":"plantas-5.s7.p4","orden":4,"grupo":"plantas-5.s7.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué principio pone en cuestión la propuesta de pasar 500.000 hectáreas a verde?","opciones":[{"id":"o1","texto":"El de no regresión en la protección ambiental"},{"id":"o2","texto":"El de libre tránsito entre provincias"},{"id":"o3","texto":"El de la propiedad privada de la tierra"},{"id":"o4","texto":"El de igualdad ante los impuestos"}]},"solucion":{"clave":["o1"],"explicacion":"Bajar la protección sin fundamentos sólidos va contra la lógica de la ley.","por_opcion":{"o3":"La ley regula el uso de la tierra, no quién es dueño."}}},{"slug":"plantas-5.s7.p5","orden":5,"grupo":"plantas-5.s7.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería considerar la actualización? Marcá todo.","opciones":[{"id":"o1","texto":"Los desmontes ilegales detectados en zona amarilla"},{"id":"o2","texto":"Los pedidos de las comunidades indígenas sobre sus territorios"},{"id":"o3","texto":"La conectividad entre bosques para la fauna"},{"id":"o4","texto":"Una audiencia pública con participación real"},{"id":"o5","texto":"Solo la opinión del sector que quiere desmontar"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Una actualización legítima mira datos, derechos y participación."}},{"slug":"plantas-5.s7.p6","orden":6,"grupo":"plantas-5.s7.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se desmontaron ilegalmente 50.000 hectáreas en 5 años, ¿cuántas hectáreas por año fueron en promedio?","unidad":"hectáreas por año","decimales":0,"contexto":"50000 ha desmontadas en 5 años."},"solucion":{"valor":10000,"tolerancia":200,"explicacion":"50.000 ÷ 5 = 10.000 hectáreas por año de desmonte ilegal: un dato que exige reforzar controles y sanciones."}},{"slug":"plantas-5.s7.p6.v2","orden":6,"grupo":"plantas-5.s7.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En 5 años se detectaron 50.000 hectáreas desmontadas en zona amarilla. ¿Cuál es el promedio anual?","unidad":"hectáreas por año","decimales":0,"contexto":"50000 ha desmontadas en 5 años."},"solucion":{"valor":10000,"tolerancia":200,"explicacion":"50.000 ÷ 5 = 10.000 hectáreas por año de desmonte ilegal: un dato que exige reforzar controles y sanciones."}},{"slug":"plantas-5.s7.p6.v3","orden":6,"grupo":"plantas-5.s7.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas hectáreas por año se desmontaron en promedio, si fueron 50.000 en 5 años?","unidad":"hectáreas por año","decimales":0,"contexto":"50000 ha desmontadas en 5 años."},"solucion":{"valor":10000,"tolerancia":200,"explicacion":"50.000 ÷ 5 = 10.000 hectáreas por año de desmonte ilegal: un dato que exige reforzar controles y sanciones."}},{"slug":"plantas-5.s7.p7","orden":7,"grupo":"plantas-5.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como hubo desmontes ilegales en zona amarilla, lo lógico es pasar esas zonas a verde para \"regularizarlos\".","razones":[{"id":"r1","texto":"Porque premiaría la ilegalidad en lugar de sancionarla"},{"id":"r2","texto":"Porque en zona verde no se puede producir"},{"id":"r3","texto":"Porque los desmontes ilegales no existen"}]},"solucion":{"valor":false,"explicacion":"Eso premiaría la ilegalidad y bajaría la protección. Lo que corresponde es sancionar, exigir restauración y reforzar los controles.","clave":["r1"]}},{"slug":"plantas-5.s7.p8","orden":8,"grupo":"plantas-5.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La provincia redacta su propuesta. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Haremos audiencias públicas en el norte y el sur de la provincia."},{"id":"s2","texto":"Pasaremos a verde las zonas desmontadas ilegalmente para regularizarlas."},{"id":"s3","texto":"Evaluaremos pasar a rojo los territorios que piden las comunidades indígenas."},{"id":"s4","texto":"No usaremos el monitoreo satelital porque es caro."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una actualización del ordenamiento es una decisión de largo plazo: tiene que basarse en datos, derechos y participación.","por_opcion":{"s2":"Premia la ilegalidad: hay que sancionar y restaurar.","s4":"Es la herramienta clave para detectar desmontes, y hay datos públicos."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"plantas-6","rama":"plantas","orden":6,"nivel":3,"titulo_es":"Restaurar ecosistemas","bajada_es":"Dejar que el bosque vuelva, ayudar con viveros de nativas, sacar invasoras y no plantar árboles donde no van: cómo se recupera un ecosistema dañado y cómo saber si funciona.","objetivos_es":["Distinguir restauración ecológica, rehabilitación y forestación","Explicar la regeneración natural y la sucesión ecológica","Planificar acciones de restauración activa con especies nativas","Evaluar por qué plantar árboles no siempre es restaurar","Diseñar el monitoreo de una restauración y sostenerla en el tiempo"],"repasa":["plantas-2","plantas-5","animales-3","aire-suelo-2"],"requiere_tronco":3,"fuentes":["decenio-restauracion","cdb-meta-2","ser-estandares","rewilding-argentina","plantas-nativas","ecorregiones-pba","reserva-costanera-sur","ipbes-global"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"plantas-6.s1","orden":1,"tipo":"leccion","titulo_es":"Qué es restaurar","bajada_es":"Recuperar un ecosistema dañado no es lo mismo que plantar cualquier cosa: la idea de ecosistema de referencia.","minutos":11,"pasos":[{"slug":"plantas-6.s1.p1","orden":1,"grupo":"plantas-6.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una definición","cuerpo":["La restauración ecológica es el proceso de ayudar a que se recupere un ecosistema que fue degradado, dañado o destruido. No se trata de \"embellecer\" un lugar, sino de recuperar sus especies nativas, su estructura (cómo se organizan las plantas en capas), sus funciones (ciclos de agua y nutrientes, polinización, dispersión de semillas) y su capacidad de sostenerse solo. Para saber hacia dónde ir se usa un ecosistema de referencia: cómo era, o cómo es hoy en un lugar parecido y bien conservado."]},"solucion":{}},{"slug":"plantas-6.s1.p2","orden":2,"grupo":"plantas-6.s1.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué busca recuperar una restauración ecológica? Marcá todo.","opciones":[{"id":"o1","texto":"Las especies nativas del lugar"},{"id":"o2","texto":"La estructura en capas de la vegetación"},{"id":"o3","texto":"Funciones como la polinización y los ciclos del agua"},{"id":"o4","texto":"La capacidad de sostenerse sin ayuda permanente"},{"id":"o5","texto":"Un jardín con especies ornamentales de todo el mundo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Restaurar es recuperar un ecosistema que funcione solo, no decorar un terreno."}},{"slug":"plantas-6.s1.p3","orden":3,"grupo":"plantas-6.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres palabras parecidas","cuerpo":["Conviene distinguir tres ideas. Restaurar es recuperar el ecosistema nativo, con sus especies y funciones. Rehabilitar es recuperar algunas funciones —por ejemplo, frenar la erosión o mejorar el suelo— sin volver necesariamente al ecosistema original. Y forestar es plantar árboles donde antes no había bosque, a menudo especies exóticas como pinos o eucaliptos para producir madera: puede ser una actividad económica legítima, pero no es restauración."]},"solucion":{}},{"slug":"plantas-6.s1.p4","orden":4,"grupo":"plantas-6.s1.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es restauración, rehabilitación o forestación?","grupos":[{"id":"g1","nombre":"Restauración"},{"id":"g2","nombre":"Rehabilitación"},{"id":"g3","nombre":"Forestación"}],"items":[{"id":"i1","texto":"Recuperar un bosque de algarrobos con especies nativas del lugar"},{"id":"i2","texto":"Cubrir un talud con pasturas para frenar la erosión"},{"id":"i3","texto":"Plantar pinos en un pastizal para producir madera"},{"id":"i4","texto":"Devolver a un humedal su régimen de agua y sus plantas nativas"},{"id":"i5","texto":"Mejorar el suelo de una cantera abandonada"},{"id":"i6","texto":"Plantar eucaliptos en un campo agrícola"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Las tres pueden ser útiles, pero solo la primera recupera el ecosistema nativo."}},{"slug":"plantas-6.s1.p5","orden":5,"grupo":"plantas-6.s1.p5","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es un ecosistema de referencia?","opciones":[{"id":"o1","texto":"El modelo de cómo debería ser el ecosistema recuperado"},{"id":"o2","texto":"Cualquier parque bonito de otra ciudad"},{"id":"o3","texto":"El ecosistema más degradado de la región"},{"id":"o4","texto":"Un jardín botánico con especies de todo el mundo"}]},"solucion":{"clave":["o1"],"explicacion":"Sin una referencia clara, no se sabe hacia dónde restaurar ni cómo medir el avance.","por_opcion":{"o3":"Es al revés: se busca un lugar bien conservado y parecido."}}},{"slug":"plantas-6.s1.p6","orden":6,"grupo":"plantas-6.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un compromiso mundial","cuerpo":["La ONU declaró 2021–2030 como el Decenio de las Naciones Unidas sobre la Restauración de los Ecosistemas. Y en el Marco Mundial de Biodiversidad, los países acordaron que, para 2030, al menos el 30 % de las áreas degradadas de tierra, aguas continentales y mares estén bajo restauración efectiva."]},"solucion":{}},{"slug":"plantas-6.s1.p7","orden":7,"grupo":"plantas-6.s1.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una provincia tiene 1.000.000 hectáreas degradadas y quiere cumplir la meta de restaurar al menos el 30 %, ¿cuántas hectáreas tiene que poner bajo restauración efectiva?","unidad":"hectáreas","decimales":0,"contexto":"1000000 ha degradadas; meta del 30 %."},"solucion":{"valor":300000,"tolerancia":6000,"explicacion":"1.000.000 × 30 % = 300.000 hectáreas. Una meta ambiciosa: por eso conviene empezar por lo más valioso y lo más fácil de recuperar."}},{"slug":"plantas-6.s1.p7.v2","orden":7,"grupo":"plantas-6.s1.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una provincia tiene 400.000 hectáreas degradadas y quiere cumplir la meta de restaurar al menos el 30 %, ¿cuántas hectáreas tiene que poner bajo restauración efectiva?","unidad":"hectáreas","decimales":0,"contexto":"400000 ha degradadas; meta del 30 %."},"solucion":{"valor":120000,"tolerancia":2400,"explicacion":"400.000 × 30 % = 120.000 hectáreas. Una meta ambiciosa: por eso conviene empezar por lo más valioso y lo más fácil de recuperar."}},{"slug":"plantas-6.s1.p7.v3","orden":7,"grupo":"plantas-6.s1.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una provincia tiene 250.000 hectáreas degradadas y quiere cumplir la meta de restaurar al menos el 30 %, ¿cuántas hectáreas tiene que poner bajo restauración efectiva?","unidad":"hectáreas","decimales":0,"contexto":"250000 ha degradadas; meta del 30 %."},"solucion":{"valor":75000,"tolerancia":1500,"explicacion":"250.000 × 30 % = 75.000 hectáreas. Una meta ambiciosa: por eso conviene empezar por lo más valioso y lo más fácil de recuperar."}},{"slug":"plantas-6.s1.p8","orden":8,"grupo":"plantas-6.s1.p8","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de las áreas degradadas se comprometieron los países a poner bajo restauración efectiva para 2030.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":30,"banda":"lineal","explicacion":"Al menos el 30 %, según la Meta 2 del Marco Mundial de Biodiversidad acordado en 2022."}},{"slug":"plantas-6.s1.p9","orden":9,"grupo":"plantas-6.s1.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Plantar pinos en un pastizal natural es una forma de restauración ecológica.","razones":[{"id":"r1","texto":"Porque es forestación exótica en un ecosistema que no era bosque"},{"id":"r2","texto":"Porque los pinos son nativos de los pastizales"},{"id":"r3","texto":"Porque los pastizales no se pueden restaurar"}]},"solucion":{"valor":false,"explicacion":"Es forestación con especies exóticas en un ecosistema que no era un bosque. Puede incluso dañar al pastizal y a su fauna. Restaurar un pastizal es recuperar sus pastos y plantas nativas.","clave":["r1"]}},{"slug":"plantas-6.s1.p10","orden":10,"grupo":"plantas-6.s1.p10","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Restauración"},{"id":"a2","texto":"Rehabilitación"},{"id":"a3","texto":"Forestación"},{"id":"a4","texto":"Ecosistema de referencia"}],"derecha":[{"id":"b1","texto":"Recuperar el ecosistema nativo y sus funciones"},{"id":"b2","texto":"Recuperar algunas funciones, como frenar la erosión"},{"id":"b3","texto":"Plantar árboles donde no había bosque"},{"id":"b4","texto":"El modelo hacia el que se restaura"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Usar bien estas palabras evita confundir proyectos muy distintos."}},{"slug":"plantas-6.s1.p11","orden":11,"grupo":"plantas-6.s1.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá los pasos para empezar una restauración.","items":[{"id":"i1","texto":"Diagnosticar qué se degradó y por qué"},{"id":"i2","texto":"Elegir un ecosistema de referencia"},{"id":"i3","texto":"Frenar las causas de la degradación"},{"id":"i4","texto":"Definir las acciones de recuperación"},{"id":"i5","texto":"Planificar cómo se va a medir el avance"},{"id":"i6","texto":"Plantar lo que haya en el vivero sin diagnóstico"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Sin frenar la causa, cualquier restauración se pierde."}},{"slug":"plantas-6.s1.p12","orden":12,"grupo":"plantas-6.s1.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas intervenciones de la más cercana a una restauración ecológica a la más lejana.","items":[{"id":"i1","texto":"Recuperar un bosque con especies nativas y su fauna"},{"id":"i2","texto":"Frenar la erosión con pasturas en una ladera"},{"id":"i3","texto":"Plantar árboles ornamentales exóticos en una plaza"},{"id":"i4","texto":"Plantar pinos en un pastizal natural"}],"extremos":["Más cerca","Más lejos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto más se recupera el ecosistema nativo, más cerca se está de restaurar.","valores":{"i1":"restauración","i2":"rehabilitación","i3":"paisajismo","i4":"reemplazo del ecosistema"}}},{"slug":"plantas-6.s1.p13","orden":13,"grupo":"plantas-6.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este proyecto y marcá lo que no es restauración.","segmentos":[{"id":"s1","texto":"Recuperaremos el bosque ribereño con especies nativas del lugar."},{"id":"s2","texto":"Plantaremos palmeras exóticas porque se ven lindas."},{"id":"s3","texto":"Usaremos como referencia un bosque bien conservado cercano."},{"id":"s4","texto":"Forestaremos un humedal con eucaliptos para \"restaurarlo\"."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El nombre del proyecto no alcanza: hay que ver qué se recupera.","por_opcion":{"s2":"No recupera el ecosistema nativo: es paisajismo.","s4":"Los eucaliptos secan el humedal: es lo contrario de restaurar."}}},{"slug":"plantas-6.s1.p14","orden":14,"grupo":"plantas-6.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Recuperar el ecosistema nativo y sus funciones es {{0}}; plantar árboles donde no había bosque es {{1}}; y el modelo hacia el que se restaura es el ecosistema de {{2}}.","banco":[{"id":"w1","texto":"restaurar"},{"id":"w2","texto":"forestar"},{"id":"w3","texto":"referencia"},{"id":"w4","texto":"decorar"},{"id":"w5","texto":"desmontar"},{"id":"w6","texto":"moda"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos para hablar de restauración con precisión."}}]},{"slug":"plantas-6.s2","orden":2,"tipo":"leccion","titulo_es":"Dejar que la naturaleza haga","bajada_es":"La regeneración natural, la sucesión ecológica y cuándo alcanza con sacar el disturbio.","minutos":11,"pasos":[{"slug":"plantas-6.s2.p1","orden":1,"grupo":"plantas-6.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La sucesión","cuerpo":["Cuando un ecosistema se deja de perturbar, se recupera en etapas: primero llegan plantas pioneras, que crecen rápido al sol; después arbustos y árboles que dan sombra; y con el tiempo, especies que necesitan un ambiente más estable. Esa secuencia se llama sucesión ecológica. En muchos lugares, la mejor restauración es dejar que ocurra: se llama regeneración natural o restauración pasiva."]},"solucion":{}},{"slug":"plantas-6.s2.p2","orden":2,"grupo":"plantas-6.s2.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas típicas de la sucesión en un campo abandonado que vuelve a ser bosque.","items":[{"id":"i1","texto":"Pastos y hierbas pioneras que crecen al sol"},{"id":"i2","texto":"Arbustos que colonizan y dan algo de sombra"},{"id":"i3","texto":"Árboles de crecimiento rápido"},{"id":"i4","texto":"Árboles de crecimiento lento que forman el bosque maduro"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada etapa prepara el terreno para la siguiente: sombra, suelo y humedad."}},{"slug":"plantas-6.s2.p3","orden":3,"grupo":"plantas-6.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuándo alcanza con esperar","cuerpo":["La regeneración natural funciona mejor cuando se cumplen tres condiciones: que se haya frenado lo que causaba el daño (el sobrepastoreo, el fuego repetido, la tala, las especies invasoras), que haya fuentes de semillas cerca (un bosque vecino, árboles aislados que atraen aves) y que el suelo no esté demasiado degradado. Si falta alguna, hace falta ayudar."]},"solucion":{}},{"slug":"plantas-6.s2.p4","orden":4,"grupo":"plantas-6.s2.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué condiciones favorecen la regeneración natural? Marcá todas.","opciones":[{"id":"o1","texto":"Que se haya frenado el sobrepastoreo o la tala"},{"id":"o2","texto":"Que haya un bosque cercano que aporte semillas"},{"id":"o3","texto":"Que el suelo conserve algo de su materia orgánica"},{"id":"o4","texto":"Que siga el fuego todos los años"},{"id":"o5","texto":"Que las especies invasoras cubran todo"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Sin la causa del daño y con semillas cerca, la naturaleza suele recuperarse sola."}},{"slug":"plantas-6.s2.p5","orden":5,"grupo":"plantas-6.s2.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un árbol aislado ayuda a recuperar el bosque.","items":[{"id":"i1","texto":"Un árbol quedó en pie en un campo abandonado"},{"id":"i2","texto":"Las aves se posan en él"},{"id":"i3","texto":"Dejan caer semillas de frutos que comieron en otros lugares"},{"id":"i4","texto":"Debajo del árbol germinan nuevas plantas"},{"id":"i5","texto":"Se forma una isla de bosque que se expande"},{"id":"i6","texto":"Las aves se comen todas las plantas nuevas"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Por eso a veces se dejan o se plantan árboles \"núcleo\" que atraen fauna dispersora."}},{"slug":"plantas-6.s2.p6","orden":6,"grupo":"plantas-6.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un ejemplo en la ciudad","cuerpo":["La Reserva Ecológica Costanera Sur, en la Ciudad de Buenos Aires, nació sobre terrenos ganados al Río de la Plata con escombros. Dejados sin intervenir, esos terrenos fueron colonizados por plantas que llegaron con el viento, el agua y las aves, y se formaron lagunas, pajonales y bosques de ribera que hoy albergan cientos de especies de aves. Es un ejemplo de cuánto puede hacer la naturaleza cuando se la deja."]},"solucion":{}},{"slug":"plantas-6.s2.p7","orden":7,"grupo":"plantas-6.s2.p7","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué muestra el caso de la Reserva Ecológica Costanera Sur?","opciones":[{"id":"o1","texto":"Que la naturaleza puede colonizar sola un terreno"},{"id":"o2","texto":"Que solo se puede restaurar con escombros"},{"id":"o3","texto":"Que las aves no llegan a las ciudades"},{"id":"o4","texto":"Que los ríos no transportan semillas"}]},"solucion":{"clave":["o1"],"explicacion":"Viento, agua y aves son grandes \"jardineros\" cuando se les da la oportunidad.","por_opcion":{"o3":"Llegaron cientos de especies de aves."}}},{"slug":"plantas-6.s2.p8","orden":8,"grupo":"plantas-6.s2.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta situación permite la regeneración natural o necesita ayuda?","grupos":[{"id":"g1","nombre":"Alcanza con regeneración natural"},{"id":"g2","nombre":"Necesita ayuda"}],"items":[{"id":"i1","texto":"Campo con ganado retirado junto a un bosque sano"},{"id":"i2","texto":"Ladera sin suelo por erosión severa"},{"id":"i3","texto":"Bosque talado hace poco con muchos renovales"},{"id":"i4","texto":"Terreno invadido por ligustro sin nativas cerca"},{"id":"i5","texto":"Zona sin semillas en muchos kilómetros"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Diagnosticar bien ahorra esfuerzo: no hace falta plantar donde la naturaleza puede sola."}},{"slug":"plantas-6.s2.p9","orden":9,"grupo":"plantas-6.s2.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Restaurar 100 hectáreas por regeneración natural (con alambrado y control) cuesta 200 dólares por hectárea; plantando, 3.000. ¿Cuántos dólares se ahorran usando regeneración natural donde es posible?","unidad":"dólares","decimales":0,"contexto":"100 ha; 200 y 3000 dólares por hectárea."},"solucion":{"valor":280000,"tolerancia":5600,"explicacion":"100 × (3.000 − 200) = 280.000 dólares. Valores de ejemplo: cuando se puede, dejar que la naturaleza trabaje es mucho más barato."}},{"slug":"plantas-6.s2.p9.v2","orden":9,"grupo":"plantas-6.s2.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Restaurar 50 hectáreas por regeneración natural (con alambrado y control) cuesta 150 dólares por hectárea; plantando, 2.500. ¿Cuántos dólares se ahorran usando regeneración natural donde es posible?","unidad":"dólares","decimales":0,"contexto":"50 ha; 150 y 2500 dólares por hectárea."},"solucion":{"valor":117500,"tolerancia":2350,"explicacion":"50 × (2.500 − 150) = 117.500 dólares. Valores de ejemplo: cuando se puede, dejar que la naturaleza trabaje es mucho más barato."}},{"slug":"plantas-6.s2.p9.v3","orden":9,"grupo":"plantas-6.s2.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Restaurar 200 hectáreas por regeneración natural (con alambrado y control) cuesta 300 dólares por hectárea; plantando, 4.000. ¿Cuántos dólares se ahorran usando regeneración natural donde es posible?","unidad":"dólares","decimales":0,"contexto":"200 ha; 300 y 4000 dólares por hectárea."},"solucion":{"valor":740000,"tolerancia":14800,"explicacion":"200 × (4.000 − 300) = 740.000 dólares. Valores de ejemplo: cuando se puede, dejar que la naturaleza trabaje es mucho más barato."}},{"slug":"plantas-6.s2.p10","orden":10,"grupo":"plantas-6.s2.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La regeneración natural significa no hacer absolutamente nada.","razones":[{"id":"r1","texto":"Porque hay que frenar las causas del daño y vigilar"},{"id":"r2","texto":"Porque la naturaleza nunca se recupera sola"},{"id":"r3","texto":"Porque requiere plantar miles de árboles"}]},"solucion":{"valor":false,"explicacion":"Implica frenar las causas del daño —cercar el ganado, controlar el fuego y las invasoras— y vigilar el avance. Es pasiva en lo que se planta, no en la gestión.","clave":["r1"]}},{"slug":"plantas-6.s2.p11","orden":11,"grupo":"plantas-6.s2.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un árbol aislado en un campo abandonado puede acelerar la llegada del bosque.","razones":[{"id":"r1","texto":"Porque atrae aves que traen semillas y crea un núcleo"},{"id":"r2","texto":"Porque los árboles aislados impiden que crezca nada"},{"id":"r3","texto":"Porque las aves no comen frutos"}]},"solucion":{"valor":true,"explicacion":"Atrae aves que traen semillas, da sombra y mejora el suelo debajo: se forma un núcleo de bosque que se expande.","clave":["r1"]}},{"slug":"plantas-6.s2.p12","orden":12,"grupo":"plantas-6.s2.p12","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada disturbio con cómo se frena.","izquierda":[{"id":"a1","texto":"Sobrepastoreo"},{"id":"a2","texto":"Fuego repetido"},{"id":"a3","texto":"Especies invasoras"},{"id":"a4","texto":"Tala"}],"derecha":[{"id":"b1","texto":"Alambrado o manejo del ganado"},{"id":"b2","texto":"Cortafuegos y control de quemas"},{"id":"b3","texto":"Control y extracción"},{"id":"b4","texto":"Protección y vigilancia"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Frenar el disturbio es el primer paso de cualquier restauración."}},{"slug":"plantas-6.s2.p13","orden":13,"grupo":"plantas-6.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Retiraremos el ganado de la ladera para que se regenere."},{"id":"s2","texto":"Dejaremos que el ganado siga entrando mientras esperamos que crezca el bosque."},{"id":"s3","texto":"Dejaremos los árboles aislados que atraen aves."},{"id":"s4","texto":"No vigilaremos nada porque la regeneración es automática."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La regeneración natural funciona cuando se gestiona bien.","por_opcion":{"s2":"El ganado se come los renovales: hay que frenar el disturbio.","s4":"Hay que controlar invasoras, fuego y avance."}}},{"slug":"plantas-6.s2.p14","orden":14,"grupo":"plantas-6.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La secuencia de etapas por la que se recupera un ecosistema es la {{0}} ecológica; dejar que el ecosistema se recupere solo es la regeneración {{1}}; y las primeras plantas que colonizan son las {{2}}.","banco":[{"id":"w1","texto":"sucesión"},{"id":"w2","texto":"natural"},{"id":"w3","texto":"pioneras"},{"id":"w4","texto":"rotación"},{"id":"w5","texto":"artificial"},{"id":"w6","texto":"ornamentales"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de la recuperación natural de los ecosistemas."}}]},{"slug":"plantas-6.s3","orden":3,"tipo":"leccion","titulo_es":"Ayudar a recuperar","bajada_es":"Viveros de nativas, siembra, plantación, control de invasoras y reintroducción de fauna: la restauración activa.","minutos":12,"pasos":[{"slug":"plantas-6.s3.p1","orden":1,"grupo":"plantas-6.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Restauración activa","cuerpo":["Cuando la naturaleza no puede sola, se la ayuda. La restauración activa puede incluir: producir plantas nativas en viveros a partir de semillas locales, sembrar o plantar, mejorar el suelo, controlar especies invasoras, devolverle al lugar su régimen de agua (en un humedal drenado, por ejemplo) y reintroducir animales que cumplen funciones clave, como dispersar semillas o controlar herbívoros."]},"solucion":{}},{"slug":"plantas-6.s3.p2","orden":2,"grupo":"plantas-6.s3.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una acción de restauración pasiva o activa?","grupos":[{"id":"g1","nombre":"Pasiva"},{"id":"g2","nombre":"Activa"}],"items":[{"id":"i1","texto":"Alambrar para que no entre el ganado"},{"id":"i2","texto":"Plantar nativas producidas en un vivero"},{"id":"i3","texto":"Dejar que el bosque vecino aporte semillas"},{"id":"i4","texto":"Sembrar semillas de pastos nativos"},{"id":"i5","texto":"Reintroducir un animal que dispersa semillas"},{"id":"i6","texto":"Tapar un canal para que un humedal recupere su agua"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2","i6":"g2"},"explicacion":"Muchas restauraciones combinan las dos: lo pasivo donde alcanza y lo activo donde hace falta."}},{"slug":"plantas-6.s3.p3","orden":3,"grupo":"plantas-6.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Semillas locales","cuerpo":["Para restaurar conviene usar semillas de la misma región: las plantas de origen local están adaptadas al clima, al suelo y a las plagas del lugar, y conservan la diversidad genética local. Por eso son tan importantes los viveros de nativas y los bancos de semillas regionales, y la recolección responsable de semillas, sin agotar las plantas madres."]},"solucion":{}},{"slug":"plantas-6.s3.p4","orden":4,"grupo":"plantas-6.s3.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene usar semillas de origen local para restaurar?","opciones":[{"id":"o1","texto":"Están adaptadas al clima y al suelo del lugar"},{"id":"o2","texto":"Porque son las más baratas del mercado"},{"id":"o3","texto":"Porque crecen más rápido que cualquier exótica"},{"id":"o4","texto":"Porque no necesitan agua nunca"}]},"solucion":{"clave":["o1"],"explicacion":"Una planta adaptada al lugar tiene más chances de sobrevivir y de integrarse al ecosistema.","por_opcion":{"o3":"No siempre crecen más rápido; su ventaja es la adaptación."}}},{"slug":"plantas-6.s3.p5","orden":5,"grupo":"plantas-6.s3.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se plantan 1.000 plantines nativos y a los dos años sobrevive el 60 %. ¿Cuántos plantines sobreviven?","unidad":"plantines","decimales":0,"contexto":"1000 plantines; supervivencia del 60 %."},"solucion":{"valor":600,"tolerancia":12,"explicacion":"1.000 × 60 % = 600 plantines. La supervivencia es un indicador clave: riego inicial, protección y especies adecuadas la mejoran."}},{"slug":"plantas-6.s3.p5.v2","orden":5,"grupo":"plantas-6.s3.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se plantan 2.500 plantines nativos y a los dos años sobrevive el 70 %. ¿Cuántos plantines sobreviven?","unidad":"plantines","decimales":0,"contexto":"2500 plantines; supervivencia del 70 %."},"solucion":{"valor":1750,"tolerancia":35,"explicacion":"2.500 × 70 % = 1.750 plantines. La supervivencia es un indicador clave: riego inicial, protección y especies adecuadas la mejoran."}},{"slug":"plantas-6.s3.p5.v3","orden":5,"grupo":"plantas-6.s3.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se plantan 800 plantines nativos y a los dos años sobrevive el 50 %. ¿Cuántos plantines sobreviven?","unidad":"plantines","decimales":0,"contexto":"800 plantines; supervivencia del 50 %."},"solucion":{"valor":400,"tolerancia":8,"explicacion":"800 × 50 % = 400 plantines. La supervivencia es un indicador clave: riego inicial, protección y especies adecuadas la mejoran."}},{"slug":"plantas-6.s3.p6","orden":6,"grupo":"plantas-6.s3.p6","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para producir plantas nativas en un vivero.","items":[{"id":"i1","texto":"Recolectar semillas maduras de plantas madres locales"},{"id":"i2","texto":"Limpiar y guardar las semillas registrando su origen"},{"id":"i3","texto":"Sembrar en almácigos"},{"id":"i4","texto":"Pasar los plantines a macetas y endurecerlos al sol"},{"id":"i5","texto":"Plantar en el sitio en la época adecuada"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un buen vivero cuida el origen, la calidad y el momento de plantación."}},{"slug":"plantas-6.s3.p7","orden":7,"grupo":"plantas-6.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Sacar las invasoras","cuerpo":["En muchos lugares, restaurar empieza por controlar especies invasoras: ligustros y acacias negras en los bosques ribereños del centro del país, pinos que se expanden en pastizales y estepas, o rosa mosqueta en la Patagonia. Lo viste en la unidad de nativas e invasoras. El control debe ser sostenido, porque las invasoras rebrotan y sus semillas quedan en el suelo por años."]},"solucion":{}},{"slug":"plantas-6.s3.p8","orden":8,"grupo":"plantas-6.s3.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la secuencia para recuperar un bosque ribereño invadido por ligustro.","items":[{"id":"i1","texto":"Relevar dónde está el ligustro y qué nativas quedan"},{"id":"i2","texto":"Cortar y controlar los ligustros adultos"},{"id":"i3","texto":"Plantar nativas para cubrir los claros"},{"id":"i4","texto":"Arrancar los rebrotes y plántulas de ligustro cada año"},{"id":"i5","texto":"Monitorear hasta que las nativas dominen"},{"id":"i6","texto":"Cortar una vez y olvidarse del lugar"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Sin control sostenido, las invasoras vuelven a ganar el espacio."}},{"slug":"plantas-6.s3.p9","orden":9,"grupo":"plantas-6.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Devolver la fauna","cuerpo":["Algunas restauraciones incluyen reintroducir animales. En los Esteros del Iberá, un programa de reintroducciones devolvió especies que habían desaparecido, como el oso hormiguero, el pecarí de collar, el guacamayo rojo y el yaguareté. Esos animales no son un adorno: cumplen funciones, como dispersar semillas o regular las poblaciones de otros animales. A esta forma de restaurar se la suele llamar renaturalización o rewilding."]},"solucion":{}},{"slug":"plantas-6.s3.p10","orden":10,"grupo":"plantas-6.s3.p10","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada animal con una función que cumple en el ecosistema.","izquierda":[{"id":"a1","texto":"Guacamayo rojo"},{"id":"a2","texto":"Yaguareté"},{"id":"a3","texto":"Oso hormiguero"},{"id":"a4","texto":"Pecarí de collar"}],"derecha":[{"id":"b1","texto":"Dispersa semillas de palmeras y árboles"},{"id":"b2","texto":"Regula las poblaciones de herbívoros"},{"id":"b3","texto":"Controla poblaciones de hormigas y termitas"},{"id":"b4","texto":"Remueve el suelo y dispersa semillas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Devolver animales es devolver funciones que el ecosistema había perdido."}},{"slug":"plantas-6.s3.p11","orden":11,"grupo":"plantas-6.s3.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones son parte de una restauración activa? Marcá todas.","opciones":[{"id":"o1","texto":"Producir plantas nativas en viveros"},{"id":"o2","texto":"Controlar especies invasoras"},{"id":"o3","texto":"Recuperar el régimen de agua de un humedal"},{"id":"o4","texto":"Reintroducir fauna que cumple funciones"},{"id":"o5","texto":"Plantar especies exóticas porque crecen rápido"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Todas buscan recuperar especies y funciones nativas."}},{"slug":"plantas-6.s3.p12","orden":12,"grupo":"plantas-6.s3.p12","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Para restaurar, conviene usar la especie que crezca más rápido, aunque sea exótica.","razones":[{"id":"r1","texto":"Porque pueden volverse invasoras y no restauran el ecosistema"},{"id":"r2","texto":"Porque las nativas nunca crecen"},{"id":"r3","texto":"Porque la velocidad es lo único que importa"}]},"solucion":{"valor":false,"explicacion":"Las exóticas pueden volverse invasoras y no cumplen las funciones del ecosistema nativo. La restauración usa especies nativas, idealmente de origen local.","clave":["r1"]}},{"slug":"plantas-6.s3.p13","orden":13,"grupo":"plantas-6.s3.p13","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos orígenes de semillas para restaurar un bosque de Córdoba, del más recomendable al menos.","items":[{"id":"i1","texto":"Semillas de árboles nativos del mismo valle"},{"id":"i2","texto":"Semillas de la misma especie de otra provincia"},{"id":"i3","texto":"Una especie nativa de otra ecorregión"},{"id":"i4","texto":"Una especie exótica que crece rápido"}],"extremos":["Más recomendable","Menos recomendable"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto más cercano el origen, mejor adaptada la planta al lugar.","valores":{"i1":"origen local","i2":"origen lejano","i3":"no corresponde al lugar","i4":"no es restauración"}}},{"slug":"plantas-6.s3.p14","orden":14,"grupo":"plantas-6.s3.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé el plan de un vivero y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Recolectamos semillas de árboles nativos de la zona."},{"id":"s2","texto":"Arrancamos todas las semillas de cada planta madre."},{"id":"s3","texto":"Registramos el origen de cada lote de semillas."},{"id":"s4","texto":"Producimos ligustros porque se venden más."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un vivero de nativas es una pieza clave de la restauración: su calidad importa.","por_opcion":{"s2":"Hay que recolectar sin agotar las plantas madres.","s4":"El ligustro es invasor: no debe producirse para restaurar."}}},{"slug":"plantas-6.s3.p15","orden":15,"grupo":"plantas-6.s3.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para restaurar conviene usar semillas de origen {{0}}; en Iberá se reintrodujeron especies como el {{1}}; y restaurar devolviendo fauna se llama renaturalización o {{2}}.","banco":[{"id":"w1","texto":"local"},{"id":"w2","texto":"yaguareté"},{"id":"w3","texto":"rewilding"},{"id":"w4","texto":"importado"},{"id":"w5","texto":"león"},{"id":"w6","texto":"marketing"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de la restauración activa con plantas y animales nativos."}}]},{"slug":"plantas-6.s4","orden":4,"tipo":"leccion","titulo_es":"El árbol correcto donde corresponde","bajada_es":"Por qué plantar árboles no siempre es bueno: pastizales, humedales, plantaciones y promesas de carbono.","minutos":11,"pasos":[{"slug":"plantas-6.s4.p1","orden":1,"grupo":"plantas-6.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"No todo ecosistema es un bosque","cuerpo":["Los pastizales, las estepas, los humedales y los arbustales son ecosistemas valiosos por sí mismos, con especies que solo viven allí. Plantar árboles en un pastizal natural no lo \"mejora\": lo reemplaza. Los árboles sombrean a las plantas del pastizal, cambian el suelo, usan más agua y pueden secar humedales y napas. Además, en zonas con fuego natural o con aves que necesitan espacios abiertos, los árboles plantados pueden causar daño."]},"solucion":{}},{"slug":"plantas-6.s4.p2","orden":2,"grupo":"plantas-6.s4.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una forestación daña un pastizal.","items":[{"id":"i1","texto":"Se plantan pinos en un pastizal natural"},{"id":"i2","texto":"Los pinos crecen y sombrean el suelo"},{"id":"i3","texto":"Desaparecen los pastos y flores del pastizal"},{"id":"i4","texto":"Se pierden las aves e insectos que dependían de ellos"},{"id":"i5","texto":"Además, los pinos se expanden fuera de la plantación"},{"id":"i6","texto":"Los pinos aumentan la diversidad de pastos"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un ecosistema abierto no es un bosque \"incompleto\"."}},{"slug":"plantas-6.s4.p3","orden":3,"grupo":"plantas-6.s4.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Plantar árboles ayuda o daña en cada caso?","grupos":[{"id":"g1","nombre":"Ayuda"},{"id":"g2","nombre":"Daña"}],"items":[{"id":"i1","texto":"Bosque ribereño nativo desmontado"},{"id":"i2","texto":"Pastizal pampeano natural"},{"id":"i3","texto":"Claro dentro de un bosque nativo degradado"},{"id":"i4","texto":"Humedal con napa alta"},{"id":"i5","texto":"Estepa patagónica"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"El mismo acto —plantar árboles— puede restaurar o degradar, según dónde."}},{"slug":"plantas-6.s4.p4","orden":4,"grupo":"plantas-6.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Plantaciones y bosques","cuerpo":["En Argentina hay más de un millón de hectáreas de plantaciones forestales, sobre todo de pinos y eucaliptos, en provincias como Misiones, Corrientes y Entre Ríos. Son cultivos de árboles para madera y celulosa: pueden generar empleo y productos útiles, pero no son bosques nativos. Tienen pocas especies, se cosechan cada cierto tiempo y no reemplazan la biodiversidad de una selva o un monte."]},"solucion":{}},{"slug":"plantas-6.s4.p5","orden":5,"grupo":"plantas-6.s4.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una característica de una plantación forestal o de un bosque nativo?","grupos":[{"id":"g1","nombre":"Plantación forestal"},{"id":"g2","nombre":"Bosque nativo"}],"items":[{"id":"i1","texto":"Pocas especies, en filas, del mismo tamaño"},{"id":"i2","texto":"Muchas especies de distintas edades y alturas"},{"id":"i3","texto":"Se cosecha entera cada cierto tiempo"},{"id":"i4","texto":"Alberga fauna que depende de él"},{"id":"i5","texto":"Suele ser de especies exóticas"},{"id":"i6","texto":"Tiene árboles muertos en pie que usan aves y hongos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Contar árboles no alcanza: importa qué árboles, cómo están y qué vida sostienen."}},{"slug":"plantas-6.s4.p6","orden":6,"grupo":"plantas-6.s4.p6","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una plantación de pinos tiene la misma biodiversidad que un bosque nativo de la misma superficie.","razones":[{"id":"r1","texto":"Porque tienen pocas especies y estructura simple"},{"id":"r2","texto":"Porque los pinos son nativos de Misiones"},{"id":"r3","texto":"Porque los bosques nativos no tienen fauna"}]},"solucion":{"valor":false,"explicacion":"Las plantaciones tienen pocas especies y una estructura simple; albergan mucha menos biodiversidad que un bosque nativo.","clave":["r1"]}},{"slug":"plantas-6.s4.p7","orden":7,"grupo":"plantas-6.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Árboles y carbono","cuerpo":["Muchas empresas ofrecen \"compensar\" emisiones plantando árboles. Los árboles guardan carbono, pero hay riesgos: que se planten donde no corresponde, que se prometa más carbono del que realmente guardan, que se quemen o se talen y liberen ese carbono, o que la plantación se use para seguir emitiendo sin reducir. Una compensación seria mide, verifica, asegura la permanencia y no reemplaza la reducción de emisiones."]},"solucion":{}},{"slug":"plantas-6.s4.p8","orden":8,"grupo":"plantas-6.s4.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué riesgos tienen las compensaciones de carbono con árboles? Marcá todos.","opciones":[{"id":"o1","texto":"Plantar en ecosistemas que no eran bosques"},{"id":"o2","texto":"Prometer más carbono del que realmente se guarda"},{"id":"o3","texto":"Que un incendio libere el carbono guardado"},{"id":"o4","texto":"Usarlas para no reducir las emisiones propias"},{"id":"o5","texto":"Que los árboles absorban demasiado oxígeno"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Plantar árboles no es un permiso para seguir emitiendo."}},{"slug":"plantas-6.s4.p9","orden":9,"grupo":"plantas-6.s4.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una empresa emite 100 toneladas de CO₂ por año y planta 1.000 árboles que absorben en promedio 20 kg de CO₂ por año cada uno. ¿Qué porcentaje de sus emisiones compensan esos árboles?","unidad":"%","decimales":0,"contexto":"1000 árboles; 20 kg de CO₂ cada uno; 100 t de emisiones."},"solucion":{"valor":20,"tolerancia":1,"explicacion":"1.000 × 20 kg = 20 t por año; ÷ 100 ≈ 20 %. Y eso si sobreviven todos. Valores de ejemplo: reducir emisiones sigue siendo lo principal."}},{"slug":"plantas-6.s4.p9.v2","orden":9,"grupo":"plantas-6.s4.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una empresa emite 300 toneladas de CO₂ por año y planta 5.000 árboles que absorben en promedio 15 kg de CO₂ por año cada uno. ¿Qué porcentaje de sus emisiones compensan esos árboles?","unidad":"%","decimales":0,"contexto":"5000 árboles; 15 kg de CO₂ cada uno; 300 t de emisiones."},"solucion":{"valor":25,"tolerancia":1,"explicacion":"5.000 × 15 kg = 75 t por año; ÷ 300 ≈ 25 %. Y eso si sobreviven todos. Valores de ejemplo: reducir emisiones sigue siendo lo principal."}},{"slug":"plantas-6.s4.p9.v3","orden":9,"grupo":"plantas-6.s4.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una empresa emite 200 toneladas de CO₂ por año y planta 2.000 árboles que absorben en promedio 25 kg de CO₂ por año cada uno. ¿Qué porcentaje de sus emisiones compensan esos árboles?","unidad":"%","decimales":0,"contexto":"2000 árboles; 25 kg de CO₂ cada uno; 200 t de emisiones."},"solucion":{"valor":25,"tolerancia":1,"explicacion":"2.000 × 25 kg = 50 t por año; ÷ 200 ≈ 25 %. Y eso si sobreviven todos. Valores de ejemplo: reducir emisiones sigue siendo lo principal."}},{"slug":"plantas-6.s4.p10","orden":10,"grupo":"plantas-6.s4.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una empresa dice \"somos carbono neutrales porque plantamos árboles\", sin reducir sus emisiones. ¿Qué conviene preguntar?","opciones":[{"id":"o1","texto":"¿Dónde plantan, cuánto miden y cómo reducen?"},{"id":"o2","texto":"¿Cuántos árboles tiene el logo de la empresa?"},{"id":"o3","texto":"¿Los árboles son de colores lindos?"},{"id":"o4","texto":"¿Cuándo sale su próxima publicidad?"}]},"solucion":{"clave":["o1"],"explicacion":"Lo viste con el greenwashing: las afirmaciones de carbono necesitan datos verificables.","por_opcion":{"o3":"No dice nada sobre el carbono ni el ecosistema."}}},{"slug":"plantas-6.s4.p11","orden":11,"grupo":"plantas-6.s4.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué una plantación de eucaliptos puede secar un humedal?","opciones":[{"id":"o1","texto":"Porque consumen mucha agua del suelo y de la napa"},{"id":"o2","texto":"Porque sus hojas tapan el agua como un techo"},{"id":"o3","texto":"Porque atraen a las aves que toman el agua"},{"id":"o4","texto":"Porque sus raíces calientan el agua"}]},"solucion":{"clave":["o1"],"explicacion":"Árboles de alto consumo de agua en un ecosistema húmedo alteran todo su funcionamiento.","por_opcion":{"o3":"Las aves no secan humedales; el consumo de agua de los árboles sí."}}},{"slug":"plantas-6.s4.p12","orden":12,"grupo":"plantas-6.s4.p12","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas acciones de una empresa según su valor climático y ambiental, de mayor a menor.","items":[{"id":"i1","texto":"Reducir sus propias emisiones"},{"id":"i2","texto":"Financiar la conservación de un bosque nativo amenazado"},{"id":"i3","texto":"Restaurar un bosque nativo degradado con especies locales"},{"id":"i4","texto":"Plantar pinos en un pastizal y decir que compensa"}],"extremos":["Mayor valor","Menor valor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero reducir; después conservar y restaurar bien; nunca dañar ecosistemas en nombre del carbono.","valores":{"i1":"lo primero","i2":"muy valioso","i3":"valioso","i4":"puede dañar"}}},{"slug":"plantas-6.s4.p13","orden":13,"grupo":"plantas-6.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta campaña y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"Restauraremos bosque ribereño con especies nativas del lugar."},{"id":"s2","texto":"Plantaremos un millón de árboles en los pastizales del sur para salvar el planeta."},{"id":"s3","texto":"Mediremos la supervivencia y el carbono con verificación independiente."},{"id":"s4","texto":"Con esta plantación ya no necesitamos reducir nuestras emisiones."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Más árboles no siempre es mejor: depende de dónde y para qué.","por_opcion":{"s2":"Forestar pastizales naturales daña ese ecosistema.","s4":"Compensar no reemplaza reducir."}}},{"slug":"plantas-6.s4.p14","orden":14,"grupo":"plantas-6.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Plantar árboles en un pastizal natural no lo mejora, lo {{0}}; las plantaciones de pinos y eucaliptos no son bosques {{1}}; y una compensación de carbono no reemplaza {{2}} emisiones.","banco":[{"id":"w1","texto":"reemplaza"},{"id":"w2","texto":"nativos"},{"id":"w3","texto":"reducir"},{"id":"w4","texto":"mejora"},{"id":"w5","texto":"artificiales"},{"id":"w6","texto":"publicitar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para plantar con criterio y sin dañar otros ecosistemas."}}]},{"slug":"plantas-6.s5","orden":5,"tipo":"leccion","titulo_es":"Medir y sostener","bajada_es":"Indicadores, plazos largos, participación y por qué prevenir el daño es siempre más barato que restaurarlo.","minutos":12,"pasos":[{"slug":"plantas-6.s5.p1","orden":1,"grupo":"plantas-6.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué medir","cuerpo":["Una restauración se evalúa con indicadores que se comparan con la situación inicial y con el ecosistema de referencia. Por ejemplo: la cobertura de vegetación nativa, la cantidad de especies nativas, la supervivencia de lo plantado, la presencia de invasoras, la estructura en capas, el estado del suelo, y la llegada de fauna como aves, polinizadores o mamíferos. Medir permite corregir a tiempo y demostrar que el esfuerzo sirvió."]},"solucion":{}},{"slug":"plantas-6.s5.p2","orden":2,"grupo":"plantas-6.s5.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada indicador con lo que muestra.","izquierda":[{"id":"a1","texto":"Cobertura de vegetación nativa"},{"id":"a2","texto":"Riqueza de especies"},{"id":"a3","texto":"Supervivencia de plantines"},{"id":"a4","texto":"Presencia de invasoras"},{"id":"a5","texto":"Llegada de aves y polinizadores"}],"derecha":[{"id":"b1","texto":"Cuánto terreno ocupan las nativas"},{"id":"b2","texto":"Cuántas especies nativas distintas hay"},{"id":"b3","texto":"Si lo plantado prospera"},{"id":"b4","texto":"Si el control funciona"},{"id":"b5","texto":"Si vuelven las funciones del ecosistema"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Varios indicadores juntos cuentan la historia completa."}},{"slug":"plantas-6.s5.p3","orden":3,"grupo":"plantas-6.s5.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sitio tenía 10 % de cobertura nativa al empezar; hoy tiene 55 %. El ecosistema de referencia tiene 80 %. ¿Qué porcentaje del camino hacia la referencia se recorrió? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"Inicio 10 %; hoy 55 %; referencia 80 %."},"solucion":{"valor":64,"tolerancia":1,"explicacion":"(55 − 10) ÷ (80 − 10) × 100 ≈ 64 %. Comparar con la referencia muestra cuánto falta, no solo cuánto se avanzó."}},{"slug":"plantas-6.s5.p3.v2","orden":3,"grupo":"plantas-6.s5.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sitio tenía 20 % de cobertura nativa al empezar; hoy tiene 50 %. El ecosistema de referencia tiene 70 %. ¿Qué porcentaje del camino hacia la referencia se recorrió? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"Inicio 20 %; hoy 50 %; referencia 70 %."},"solucion":{"valor":60,"tolerancia":1,"explicacion":"(50 − 20) ÷ (70 − 20) × 100 ≈ 60 %. Comparar con la referencia muestra cuánto falta, no solo cuánto se avanzó."}},{"slug":"plantas-6.s5.p3.v3","orden":3,"grupo":"plantas-6.s5.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sitio tenía 5 % de cobertura nativa al empezar; hoy tiene 45 %. El ecosistema de referencia tiene 90 %. ¿Qué porcentaje del camino hacia la referencia se recorrió? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"Inicio 5 %; hoy 45 %; referencia 90 %."},"solucion":{"valor":47,"tolerancia":1,"explicacion":"(45 − 5) ÷ (90 − 5) × 100 ≈ 47 %. Comparar con la referencia muestra cuánto falta, no solo cuánto se avanzó."}},{"slug":"plantas-6.s5.p4","orden":4,"grupo":"plantas-6.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Plazos largos","cuerpo":["Restaurar lleva mucho tiempo. Un pastizal puede recuperar su aspecto en pocos años, pero un bosque maduro necesita décadas o siglos. Los proyectos que duran uno o dos años y después se abandonan suelen fracasar: los plantines mueren sin riego, las invasoras vuelven, el ganado entra. Por eso hay que planificar el financiamiento, el cuidado y el monitoreo a largo plazo desde el principio."]},"solucion":{}},{"slug":"plantas-6.s5.p5","orden":5,"grupo":"plantas-6.s5.p5","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos ecosistemas según el tiempo que suele tardar su recuperación, de menor a mayor.","items":[{"id":"i1","texto":"Pastizal con buena fuente de semillas"},{"id":"i2","texto":"Humedal al que se le devuelve el agua"},{"id":"i3","texto":"Bosque joven de crecimiento rápido"},{"id":"i4","texto":"Bosque maduro con árboles centenarios"}],"extremos":["Más rápido","Más lento"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto más complejo y longevo el ecosistema, más tarda en volver.","valores":{"i1":"pocos años","i2":"años","i3":"décadas","i4":"siglos"}}},{"slug":"plantas-6.s5.p6","orden":6,"grupo":"plantas-6.s5.p6","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué fracasan muchas restauraciones de corto plazo.","items":[{"id":"i1","texto":"Se planta mucho en un evento de un día"},{"id":"i2","texto":"No hay presupuesto para el riego y el cuidado"},{"id":"i3","texto":"Los plantines mueren en el primer verano seco"},{"id":"i4","texto":"Las invasoras vuelven a ocupar el lugar"},{"id":"i5","texto":"A los pocos años no queda casi nada"},{"id":"i6","texto":"Los plantines crecen igual sin cuidado"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Plantar es el comienzo; cuidar es lo que hace que funcione."}},{"slug":"plantas-6.s5.p7","orden":7,"grupo":"plantas-6.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Con la gente","cuerpo":["Las restauraciones que duran suelen involucrar a las comunidades: vecinos que cuidan un bosque ribereño, escuelas con viveros de nativas, productores que ganan algo con la restauración (miel, sombra para el ganado, turismo), comunidades indígenas que aportan su conocimiento del lugar. Cuando la restauración tiene sentido para quienes viven allí, se sostiene."]},"solucion":{}},{"slug":"plantas-6.s5.p8","orden":8,"grupo":"plantas-6.s5.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que una restauración se sostenga en el tiempo? Marcá todo.","opciones":[{"id":"o1","texto":"Financiamiento para el cuidado de varios años"},{"id":"o2","texto":"Participación de la comunidad local"},{"id":"o3","texto":"Monitoreo con indicadores"},{"id":"o4","texto":"Beneficios para quienes viven allí"},{"id":"o5","texto":"Un evento de plantación sin seguimiento"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La restauración es un proceso largo, social y ecológico a la vez."}},{"slug":"plantas-6.s5.p9","orden":9,"grupo":"plantas-6.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Prevenir es más barato","cuerpo":["Restaurar es posible, pero caro y lento, y casi nunca devuelve todo lo perdido. Conservar un ecosistema en pie cuesta mucho menos que recuperarlo después. Por eso la restauración no es un permiso para dañar: es el último recurso, después de evitar la degradación."]},"solucion":{}},{"slug":"plantas-6.s5.p10","orden":10,"grupo":"plantas-6.s5.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como los ecosistemas se pueden restaurar, no importa tanto desmontar hoy.","razones":[{"id":"r1","texto":"Porque restaurar es caro, lento e incompleto"},{"id":"r2","texto":"Porque los ecosistemas no se pueden restaurar nunca"},{"id":"r3","texto":"Porque desmontar ayuda a restaurar"}]},"solucion":{"valor":false,"explicacion":"Restaurar es caro, lento y casi nunca devuelve todo lo perdido. Conservar es mucho más barato y efectivo; restaurar es el último recurso.","clave":["r1"]}},{"slug":"plantas-6.s5.p11","orden":11,"grupo":"plantas-6.s5.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Conservar una hectárea de bosque cuesta unos 50 dólares por año y restaurar una degradada, unos 3.000 dólares. ¿Cuántos años de conservación se pagan con lo que cuesta restaurar una hectárea?","unidad":"años","decimales":0,"contexto":"Conservar 50 dólares por año; restaurar 3000 dólares."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"3.000 ÷ 50 = 60 años. Valores de ejemplo: prevenir la degradación es, en general, mucho más barato."}},{"slug":"plantas-6.s5.p11.v2","orden":11,"grupo":"plantas-6.s5.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Conservar una hectárea de bosque cuesta unos 80 dólares por año y restaurar una degradada, unos 2.500 dólares. ¿Cuántos años de conservación se pagan con lo que cuesta restaurar una hectárea?","unidad":"años","decimales":2,"contexto":"Conservar 80 dólares por año; restaurar 2500 dólares."},"solucion":{"valor":31.25,"tolerancia":0.625,"explicacion":"2.500 ÷ 80 = 31,25 años. Valores de ejemplo: prevenir la degradación es, en general, mucho más barato."}},{"slug":"plantas-6.s5.p11.v3","orden":11,"grupo":"plantas-6.s5.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Conservar una hectárea de bosque cuesta unos 30 dólares por año y restaurar una degradada, unos 4.000 dólares. ¿Cuántos años de conservación se pagan con lo que cuesta restaurar una hectárea?","unidad":"años","decimales":3,"contexto":"Conservar 30 dólares por año; restaurar 4000 dólares."},"solucion":{"valor":133.33333333333334,"tolerancia":2.666666666666667,"explicacion":"4.000 ÷ 30 = 133,333 años. Valores de ejemplo: prevenir la degradación es, en general, mucho más barato."}},{"slug":"plantas-6.s5.p12","orden":12,"grupo":"plantas-6.s5.p12","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un indicador de actividad o de resultado?","grupos":[{"id":"g1","nombre":"Actividad"},{"id":"g2","nombre":"Resultado"}],"items":[{"id":"i1","texto":"Cantidad de árboles plantados"},{"id":"i2","texto":"Supervivencia a los tres años"},{"id":"i3","texto":"Cantidad de jornadas realizadas"},{"id":"i4","texto":"Cobertura de vegetación nativa"},{"id":"i5","texto":"Carteles instalados"},{"id":"i6","texto":"Aves que volvieron al lugar"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los indicadores de resultado dicen si el ecosistema se recupera; los de actividad solo dicen qué se hizo."}},{"slug":"plantas-6.s5.p13","orden":13,"grupo":"plantas-6.s5.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe de una restauración y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Medimos cobertura nativa, supervivencia e invasoras cada año."},{"id":"s2","texto":"Como plantamos 5.000 árboles, la restauración ya fue exitosa."},{"id":"s3","texto":"Comparamos los resultados con un ecosistema de referencia."},{"id":"s4","texto":"El proyecto termina este año, sin presupuesto para el cuidado."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El éxito de una restauración se mide en lo que se recupera, no en lo que se planta.","por_opcion":{"s2":"Plantar no es éxito: hay que medir supervivencia y recuperación.","s4":"Sin cuidado de largo plazo, lo plantado suele perderse."}}},{"slug":"plantas-6.s5.p14","orden":14,"grupo":"plantas-6.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una restauración se evalúa con {{0}}; un bosque maduro tarda {{1}} en recuperarse; y siempre es más barato {{2}} que restaurar.","banco":[{"id":"w1","texto":"indicadores"},{"id":"w2","texto":"siglos"},{"id":"w3","texto":"conservar"},{"id":"w4","texto":"opiniones"},{"id":"w5","texto":"días"},{"id":"w6","texto":"desmontar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas clave para medir y sostener una restauración."}},{"slug":"plantas-6.s5.p15","orden":15,"grupo":"plantas-6.s5.p15","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un municipio quiere mostrar resultados rápidos de su plan de restauración. ¿Qué indicador es más honesto a los tres años?","opciones":[{"id":"o1","texto":"La supervivencia y la cobertura nativa lograda"},{"id":"o2","texto":"La cantidad de fotos del día de la plantación"},{"id":"o3","texto":"El número de árboles comprados al vivero"},{"id":"o4","texto":"La cantidad de carteles instalados"}]},"solucion":{"clave":["o1"],"explicacion":"Los indicadores de resultado dicen más que los de actividad.","por_opcion":{"o3":"Comprar no es lograr: muchos pueden haber muerto."}}}]},{"slug":"plantas-6.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: restaurar ecosistemas","bajada_es":"Definiciones, regeneración natural, restauración activa, forestación y monitoreo, mezclados.","minutos":8,"pasos":[{"slug":"plantas-6.s6.p1","orden":1,"grupo":"plantas-6.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Restaurar ecosistemas». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"plantas-6.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la ribera del arroyo","bajada_es":"Un arroyo pampeano perdió su bosque de ribera: hay ligustros, ganado que entra al agua y orillas que se desmoronan. Armá el plan de restauración.","minutos":10,"pasos":[{"slug":"plantas-6.s7.p1","orden":1,"grupo":"plantas-6.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["El tramo tiene 3 km de orilla y una franja de 20 metros de ancho a recuperar a cada lado. Hoy hay ligustros invasores en la mitad del tramo, ganado que entra a tomar agua y pisotea la orilla, y casi no quedan árboles nativos, salvo unos talas aislados. Aguas arriba, a 5 km, hay un bosque ribereño bien conservado. Un vivero de la zona produce talas, sauces criollos, ceibos y otras nativas. El municipio tiene presupuesto para tr